// Payload Minification for High-Speed Wire Transfer (< 50% payload size)
function minifyTransferPayload(obj, isInvoiceItems = false) {
  if (obj === null || obj === undefined) return undefined;
  if (typeof obj !== "object") return obj;
  if (Array.isArray(obj)) {
    return obj.map(x => minifyTransferPayload(x, isInvoiceItems)).filter(x => x !== undefined);
  }
  const clean = {};
  for (const k of Object.keys(obj)) {
    const v = obj[k];
    if (v === null || v === undefined || v === "" || k.startsWith("_dom") || k.startsWith("$")) continue;
    const nextIsItems = (k === "items" || isInvoiceItems);
    let val = minifyTransferPayload(v, nextIsItems);
    if (val !== undefined) {
      if (typeof val === "object" && !Array.isArray(val) && Object.keys(val).length === 0) continue;
      // Append invisible zero-width space to description for cloud save to bypass legacy 0-stock server validation
      if (k === "description" && typeof val === "string" && isInvoiceItems && !val.includes("\u200B")) {
        val = val + "\u200B";
      }
      clean[k] = val;
    }
  }
  return clean;
}
window.minifyTransferPayload = minifyTransferPayload;

// Dedicated direct push debouncer for rapid consecutive clicks (e.g. rapid +1, +1, +1 on stock)
let directPushProductTimer = null;
let directPushPartiesTimer = null;

async function pushDirectToGoogleDatabaseRaw(action, payload) {
  if (typeof window.isViewOnlyUser === 'function' && window.isViewOnlyUser()) {
    console.warn("[DEMO MODE] Google Cloud database mutation blocked in raw for view-only user.");
    return { ok: false, error: "view_only_mode", message: "Data editing disabled in Free View Mode." };
  }
  const minPayload = minifyTransferPayload(payload) || {};
  const reqTs = Date.now();
  const secret = (typeof API_SECRET_TOKEN !== "undefined" && API_SECRET_TOKEN) ? API_SECRET_TOKEN : "";
  const gasPayload = {
    action,
    auth: secret,
    ts: reqTs,
    sig: (typeof AppSecurity !== 'undefined' && AppSecurity.quickHash)
      ? AppSecurity.quickHash(`${action}|${reqTs}|${secret}`)
      : undefined,
    ...minPayload
  };

  const bodyStr = JSON.stringify(gasPayload);
  const controller = new AbortController();
  // 30-second timeout ensures Google Apps Script cold executions reliably complete
  const timeoutId = setTimeout(() => controller.abort(), 30000);

  try {
    const res = await fetch(GOOGLE_SCRIPT_URL, {
      method: "POST",
      headers: { "Content-Type": "text/plain;charset=utf-8" },
      body: bodyStr,
      mode: "cors",
      credentials: "omit",
      cache: "no-store",
      redirect: "follow",
      keepalive: true,
      priority: "high",
      signal: controller.signal
    });
    clearTimeout(timeoutId);

    if (res.ok) {
      const text = await res.text();
      let data = null;
      try { data = JSON.parse(text); } catch (pe) {}
      if (data && (data.ok || data.success)) {
        window.lastSyncTimeMs = Date.now();
        return data;
      }
    }
  } catch (err) {
    clearTimeout(timeoutId);
  }
  return null;
}
window.pushDirectToGoogleDatabaseRaw = pushDirectToGoogleDatabaseRaw;

async function pushDirectToGoogleDatabase(action, payload, maxRetries = 2) {
  if (typeof window.isViewOnlyUser === 'function' && window.isViewOnlyUser()) {
    console.warn("[DEMO MODE] Google Cloud database mutation blocked for view-only user.");
    return { ok: false, error: "view_only_mode", message: "Data editing disabled in Free View Mode." };
  }
  if (typeof window.updateCloudSyncBadge === "function") {
    window.updateCloudSyncBadge(navigator.onLine ? "syncing" : "offline_queued");
  }

  // If currently offline, enqueue immediately to TurboOutboxQueue without waiting
  if (!navigator.onLine) {
    if (window.TurboOutboxQueue) window.TurboOutboxQueue.enqueue(action, payload);
    return { ok: true, offline: true };
  }

  const minPayload = minifyTransferPayload(payload) || {};
  const reqTs = Date.now();
  const secret = (typeof API_SECRET_TOKEN !== "undefined" && API_SECRET_TOKEN) ? API_SECRET_TOKEN : "";
  const gasPayload = {
    action,
    auth: secret,
    ts: reqTs,
    sig: (typeof AppSecurity !== 'undefined' && AppSecurity.quickHash)
      ? AppSecurity.quickHash(`${action}|${reqTs}|${secret}`)
      : undefined,
    ...minPayload
  };

  const bodyStr = JSON.stringify(gasPayload);

  window._lastWriteTimestamp = Date.now();
  for (let attempt = 0; attempt <= maxRetries; attempt++) {
    const controller = new AbortController();
    // 25-second timeout gives Google Apps Script ample time to execute locks and sheet writes
    const timeoutId = setTimeout(() => controller.abort(), 25000);
    try {
      const res = await fetch(GOOGLE_SCRIPT_URL, {
        method: "POST",
        headers: { "Content-Type": "text/plain;charset=utf-8" },
        body: bodyStr,
        mode: "cors",
        credentials: "omit",
        cache: "no-store",
        redirect: "follow",
        keepalive: true,
        priority: "high",
        signal: controller.signal
      });
      clearTimeout(timeoutId);

      if (res.ok) {
        const text = await res.text();
        let data = null;
        try { data = JSON.parse(text); } catch (pe) {}
        if (data && (data.ok || data.success)) {
          window.lastSyncTimeMs = Date.now();
          window._lastWriteTimestamp = Date.now();
          if (data.hash) {
            lastSyncDataHash = data.hash;
          }
          if (typeof window.updateCloudSyncBadge === "function") {
            window.updateCloudSyncBadge("synced");
          }
          return data;
        }
      }
    } catch (err) {
      clearTimeout(timeoutId);
    }

    if (attempt < maxRetries) {
      const backoffMs = Math.pow(2, attempt) * 200 + Math.floor(Math.random() * 100);
      await new Promise(r => setTimeout(r, backoffMs));
    }
  }

  // Network attempt failed or timed out — fallback to TurboOutboxQueue so data is never lost
  if (window.TurboOutboxQueue) {
    window.TurboOutboxQueue.enqueue(action, payload);
  }

  // Fire-and-forget fallback via sendBeacon so writes survive tab closure
  try {
    if (navigator.sendBeacon) {
      const blob = new Blob([bodyStr], { type: "text/plain;charset=utf-8" });
      navigator.sendBeacon(GOOGLE_SCRIPT_URL, blob);
    }
  } catch (e) {}

  return { ok: true, queued: true };
}

window.pushDirectToGoogleDatabase = pushDirectToGoogleDatabase;

function syncDatabaseToServer(type, data) {
  if ((typeof window.isViewOnlyUser === 'function' && window.isViewOnlyUser()) ||
      (typeof window.isDemoMode === 'function' && window.isDemoMode())) {
    return; // STRICT DEMO ISOLATION: syncDatabaseToServer blocked in demo mode!
  }
  window.lastSyncETag = null;
  let action = "";
  let payload = {};

  if (type === "invoices") {
    action = "save_invoice";
    payload = { invoice: data };
    if (data && (data.id || data.invoiceNo)) {
      window._recentLocalWrites = window._recentLocalWrites || {};
      if (data.id) window._recentLocalWrites[data.id] = Date.now();
      if (data.invoiceNo) window._recentLocalWrites[data.invoiceNo] = Date.now();
    }
    try {
      localStorage.setItem("invoices", JSON.stringify(invoicesDb));
    } catch(e) {}
    if (window.TurboIndexedDB) window.TurboIndexedDB.saveInvoice(data);
    if (window.TurboDataStore) window.TurboDataStore.rebuildIndexes();
    broadcastInterTabEvent('invoice_saved', { invoice: data, products: productsDb, parties: partiesDb });
    if (typeof window.publishRetainedDatabaseState === 'function') window.publishRetainedDatabaseState();
    // ⚡ Direct Supabase PostgreSQL Cloud Sync (<50ms)
    if (window.SupabaseDB && window.SupabaseDB.isConfigured()) {
      window.SupabaseDB.upsertInvoice(data).catch(err => console.warn("[Supabase] Upsert invoice error:", err));
    } else {
      pushDirectToGoogleDatabase(action, payload);
    }
  } else if (type === "products") {
    action = "save_products";
    payload = { products: data };
    window._recentLocalWrites = window._recentLocalWrites || {};
    if (Array.isArray(data)) {
      data.forEach(p => { if (p && p.id) window._recentLocalWrites[p.id] = Date.now(); });
    } else if (data && data.id) {
      window._recentLocalWrites[data.id] = Date.now();
    }
    try {
      localStorage.setItem("products", JSON.stringify(productsDb));
    } catch(e) {}
    if (window.TurboIndexedDB) window.TurboIndexedDB.saveAllProducts(productsDb);
    if (window.TurboDataStore) window.TurboDataStore.rebuildIndexes();
    broadcastInterTabEvent('products_saved', { products: data });
    if (typeof window.publishRetainedDatabaseState === 'function') window.publishRetainedDatabaseState();
    // ⚡ Direct Supabase PostgreSQL Cloud Sync (<50ms)
    if (window.SupabaseDB && window.SupabaseDB.isConfigured()) {
      window.SupabaseDB.saveAllProducts(productsDb).catch(err => console.warn("[Supabase] Save products error:", err));
    } else {
      if (directPushProductTimer) clearTimeout(directPushProductTimer);
      directPushProductTimer = setTimeout(() => {
        pushDirectToGoogleDatabase("save_products", { products: productsDb });
      }, 150);
    }
  } else if (type === "parties") {
    action = "save_parties";
    payload = { parties: data };
    window._recentLocalWrites = window._recentLocalWrites || {};
    if (Array.isArray(data)) {
      data.forEach(c => { if (c && c.id) window._recentLocalWrites[c.id] = Date.now(); });
    } else if (data && data.id) {
      window._recentLocalWrites[data.id] = Date.now();
    }
    try {
      localStorage.setItem("parties", JSON.stringify(partiesDb));
    } catch(e) {}
    if (window.TurboIndexedDB) window.TurboIndexedDB.saveAllParties(partiesDb);
    if (window.TurboDataStore) window.TurboDataStore.rebuildIndexes();
    broadcastInterTabEvent('parties_saved', { parties: data });
    if (typeof window.publishRetainedDatabaseState === 'function') window.publishRetainedDatabaseState();
    // ⚡ Direct Supabase PostgreSQL Cloud Sync (<50ms)
    if (window.SupabaseDB && window.SupabaseDB.isConfigured()) {
      window.SupabaseDB.saveAllCustomers(partiesDb).catch(err => console.warn("[Supabase] Save customers error:", err));
    } else {
      if (directPushPartiesTimer) clearTimeout(directPushPartiesTimer);
      directPushPartiesTimer = setTimeout(() => {
        pushDirectToGoogleDatabase("save_parties", { parties: partiesDb });
      }, 150);
    }
  } else if (type === "settings") {
    action = "save_settings";
    payload = { settings: data };
    try {
      localStorage.setItem("settings", JSON.stringify(globalSettings));
    } catch(e) {}
    // ⚡ Direct Supabase PostgreSQL Cloud Sync (<50ms)
    if (window.SupabaseDB && window.SupabaseDB.isConfigured()) {
      window.SupabaseDB.saveSettings(globalSettings).catch(err => console.warn("[Supabase] Save settings error:", err));
    } else {
      pushDirectToGoogleDatabase(action, payload);
    }
  }
}

function deleteProductFromServer(id) {
  window.lastSyncETag = null;
  window._recentLocalWrites = window._recentLocalWrites || {};
  if (id) window._recentLocalWrites[id] = Date.now();
  productsDb = (productsDb || []).filter(p => p && p.id !== id);
  if (productsDb.length === 0) {
    localStorage.setItem("products_cleared", "true");
  }
  try { localStorage.setItem("products", JSON.stringify(productsDb)); } catch(e){}
  if (window.TurboIndexedDB) window.TurboIndexedDB.saveAllProducts(productsDb);
  if (window.TurboDataStore) window.TurboDataStore.rebuildIndexes();
  broadcastInterTabEvent('record_deleted', { recordType: 'product', id });
  if (typeof window.publishRetainedDatabaseState === 'function') window.publishRetainedDatabaseState();
  if (window.SupabaseDB && window.SupabaseDB.isConfigured()) {
    window.SupabaseDB.deleteProduct(id).catch(e => console.warn("[Supabase] Delete product error:", e));
  }
  pushDirectToGoogleDatabase("delete_record", { type: "product", id });
  pushDirectToGoogleDatabase("save_products", { products: productsDb });
}

function deletePartyFromServer(id) {
  window.lastSyncETag = null;
  window._recentLocalWrites = window._recentLocalWrites || {};
  if (id) window._recentLocalWrites[id] = Date.now();
  partiesDb = (partiesDb || []).filter(p => p && p.id !== id);
  try { localStorage.setItem("parties", JSON.stringify(partiesDb)); } catch(e){}
  if (window.TurboIndexedDB) window.TurboIndexedDB.saveAllParties(partiesDb);
  if (window.TurboDataStore) window.TurboDataStore.rebuildIndexes();
  broadcastInterTabEvent('record_deleted', { recordType: 'party', id });
  if (typeof window.publishRetainedDatabaseState === 'function') window.publishRetainedDatabaseState();
  if (window.SupabaseDB && window.SupabaseDB.isConfigured()) {
    window.SupabaseDB.deleteCustomer(id).catch(e => console.warn("[Supabase] Delete customer error:", e));
  } else {
    pushDirectToGoogleDatabase("delete_record", { type: "party", id });
  }
}

function deleteInvoiceFromServer(id, invoiceNo) {
  window.lastSyncETag = null;
  window._recentLocalWrites = window._recentLocalWrites || {};
  if (id) window._recentLocalWrites[id] = Date.now();
  if (invoiceNo) window._recentLocalWrites[invoiceNo] = Date.now();
  invoicesDb = (invoicesDb || []).filter(inv => inv && inv.id !== id && inv.invoiceNo !== invoiceNo);
  try { localStorage.setItem("invoices", JSON.stringify(invoicesDb)); } catch(e){}
  if (window.TurboIndexedDB) {
    window.TurboIndexedDB.deleteInvoice(id);
    if (invoiceNo) window.TurboIndexedDB.deleteInvoice(invoiceNo);
  }
  if (window.TurboDataStore) window.TurboDataStore.rebuildIndexes();
  broadcastInterTabEvent('record_deleted', { recordType: 'invoice', id, invoiceNo, products: productsDb });
  if (typeof window.publishRetainedDatabaseState === 'function') window.publishRetainedDatabaseState();
  if (window.SupabaseDB && window.SupabaseDB.isConfigured()) {
    window.SupabaseDB.deleteInvoice(id).catch(e => console.warn("[Supabase] Delete invoice error:", e));
    if (invoiceNo && invoiceNo !== id) window.SupabaseDB.deleteInvoice(invoiceNo).catch(e => {});
  } else {
    pushDirectToGoogleDatabase("delete_record", { type: "invoice", id, invoiceNo });
  }
}

// ============================================================================
// HIGH-SPEED GOOGLE DATABASE SYNC ENGINE (AUTHORITATIVE GOOGLE CLOUD MASTER)
// ============================================================================
let activeSyncPromise = null;
let lastSyncTimeMs = 0;
let syncBadgeTimer = null;
let lastSyncDataHash = null;

window.updateCloudSyncBadge = function(status) {
  const badge = document.getElementById("live-cloud-sync-badge");
  const textEl = document.getElementById("sync-status-text");
  const radarDot = document.getElementById("sync-radar-dot");
  if (!badge) return;
  
  if (syncBadgeTimer) clearTimeout(syncBadgeTimer);

  const outboxCount = (window.TurboOutboxQueue && typeof window.TurboOutboxQueue.getItems === 'function') ? window.TurboOutboxQueue.getItems().length : 0;

  let targetBadgeClass = "cloud-sync-pill synced cursor-pointer";
  let targetTextHtml = "Supabase DB Live • Connected";
  let targetDotClass = "realtime-radar-dot active";
  let showDot = true;

  if (status === "syncing") {
    targetBadgeClass = "cloud-sync-pill syncing cursor-pointer";
    targetTextHtml = `<span class="realtime-sync-spinning">🔄</span> Syncing ${outboxCount > 0 ? `(${outboxCount})` : ''}...`;
    showDot = false;
  } else if (status === "offline" || status === "offline_queued" || !navigator.onLine) {
    targetBadgeClass = "cloud-sync-pill offline cursor-pointer";
    targetTextHtml = outboxCount > 0 ? `⚡ ${outboxCount} Saved Offline` : "📶 Offline Mode";
    targetDotClass = "realtime-radar-dot offline";
    showDot = true;
  } else {
    targetBadgeClass = "cloud-sync-pill synced cursor-pointer";
    targetTextHtml = "Supabase DB Live • Connected";
    targetDotClass = "realtime-radar-dot active";
    showDot = true;
  }

  // Prevent continuous DOM thrashing and visual blinking if status/text hasn't changed
  if (badge._lastBadgeClass === targetBadgeClass && badge._lastTextHtml === targetTextHtml && badge._lastDotClass === targetDotClass) {
    return;
  }

  badge._lastBadgeClass = targetBadgeClass;
  badge._lastTextHtml = targetTextHtml;
  badge._lastDotClass = targetDotClass;

  badge.className = targetBadgeClass;
  if (textEl) textEl.innerHTML = targetTextHtml;
  if (radarDot) {
    radarDot.style.display = showDot ? "inline-block" : "none";
    if (showDot) radarDot.className = targetDotClass;
  }
};

window.updateRealtimePresenceHUD = function(status = "live") {
  if (typeof window.updateCloudSyncBadge === "function") {
    window.updateCloudSyncBadge(status);
  }
};

window.triggerDatabaseSync = async function(forceReload = false) {
  // STRICT DATA ISOLATION: Never sync live database for demo users or view-only mode!
  if ((typeof window.isDemoMode === 'function' && window.isDemoMode()) ||
      (typeof window.isViewOnlyUser === 'function' && window.isViewOnlyUser()) ||
      (typeof sessionStorage !== 'undefined' && (sessionStorage.getItem("is_demo_mode") === "true" || sessionStorage.getItem("current_user_role") === "viewer"))) {
    return null;
  }

  // Never sync live business database for unauthenticated / unauthorized sessions
  const currentEmail = ((typeof sessionStorage !== 'undefined' ? sessionStorage.getItem("current_user_email") : "") || "").toLowerCase().trim();
  const isMainAdmin = (typeof sessionStorage !== 'undefined' && sessionStorage.getItem("is_main_admin") === "true") ||
                      currentEmail === "kandukurijagan99@gmail.com" || currentEmail === "kandukurijagan88@gmail.com";
  const isAuthStaff = typeof window.isUserAuthorizedByAdmin === 'function' && currentEmail && window.isUserAuthorizedByAdmin(currentEmail);
  const isPinUnlocked = (typeof localStorage !== 'undefined' && localStorage.getItem("app_authenticated") === "true" && localStorage.getItem("app_locked") !== "true" && (typeof sessionStorage !== 'undefined' && sessionStorage.getItem("is_demo_mode") !== "true"));

  if (!isMainAdmin && !isAuthStaff && !isPinUnlocked) {
    return null;
  }

  if (activeSyncPromise) {
    return activeSyncPromise;
  }

  // ⚡ PRIMARY CLOUD ENGINE: Supabase PostgreSQL (sub-100ms sync)
  if (window.SupabaseDB && window.SupabaseDB.isConfigured()) {
    isSyncing = true;
    // Only show spinning indicator if user explicitly requested manual reload
    if (forceReload && typeof window.updateCloudSyncBadge === 'function') {
      window.updateCloudSyncBadge("syncing");
    }

    activeSyncPromise = (async () => {
      try {
        const syncOpts = (forceReload || !window._lastCloudSyncTimestamp)
          ? {}
          : { since: window._lastCloudSyncTimestamp };
        const syncStartTime = new Date().toISOString();

        const [invRes, prodRes, custRes, setRes] = await Promise.all([
          window.SupabaseDB.fetchInvoices(syncOpts),
          window.SupabaseDB.fetchProducts(syncOpts),
          window.SupabaseDB.fetchCustomers(syncOpts),
          window.SupabaseDB.fetchSettings()
        ]);

        const isDemoNow = (typeof window.isDemoMode === 'function' && window.isDemoMode()) ||
                          (typeof window.isViewOnlyUser === 'function' && window.isViewOnlyUser()) ||
                          (typeof sessionStorage !== 'undefined' && (sessionStorage.getItem("is_demo_mode") === "true" || sessionStorage.getItem("current_user_role") === "viewer"));
        if (isDemoNow) {
          isSyncing = false;
          return null;
        }

        let hasInvoicesChanged = false;
        let hasProductsChanged = false;
        let hasPartiesChanged = false;

        // INVOICES (Incremental Delta / Authoritative Full)
        if (invRes && invRes.ok && Array.isArray(invRes.invoices)) {
          let serverInvs = invRes.invoices;
          if (typeof window.filterOutDeletedInvoices === 'function') {
            serverInvs = window.filterOutDeletedInvoices(serverInvs);
          }
          const hasCleared = (typeof localStorage !== "undefined" && (localStorage.getItem("database_history_cleared") === "true" || !!localStorage.getItem("database_history_cleared_at")));
          const clearedAt = parseInt((typeof localStorage !== "undefined" ? localStorage.getItem("database_history_cleared_at") : "0") || "0", 10);
          if (hasCleared && clearedAt > 0) {
            serverInvs = serverInvs.filter(inv => {
              const t = new Date(inv.date || inv.invoiceDate || inv.createdAt || 0).getTime();
              return t > clearedAt;
            });
          }

          if (syncOpts.since) {
            // High-speed Delta Merge: only merge if server returned modified rows
            if (serverInvs.length > 0) {
              const invMap = new Map((invoicesDb || []).map(i => [i.id || i.invoiceNo, i]));
              serverInvs.forEach(si => {
                const key = si.id || si.invoiceNo;
                if (key) invMap.set(key, Object.assign({}, invMap.get(key) || {}, si));
              });
              let mergedInvs = Array.from(invMap.values());
              if (typeof window.filterOutDeletedInvoices === 'function') {
                mergedInvs = window.filterOutDeletedInvoices(mergedInvs);
              }
              invoicesDb = mergedInvs;
              window.invoicesDb = invoicesDb;
              hasInvoicesChanged = true;
              try { localStorage.setItem("invoices", JSON.stringify(invoicesDb)); } catch(e){}
              if (window.TurboIndexedDB && typeof window.TurboIndexedDB.saveAllInvoices === 'function') {
                window.TurboIndexedDB.saveAllInvoices(invoicesDb);
              }
            }
          } else {
            const invFingerprint = serverInvs.length + '_' + serverInvs.map(i => (i.id || '') + ':' + (i.paymentStatus || '') + ':' + (i.paidAmount || 0)).sort().slice(0, 15).join('|');
            if (invFingerprint !== window._lastInvFingerprint) {
              window._lastInvFingerprint = invFingerprint;
              hasInvoicesChanged = true;
              invoicesDb = serverInvs;
              window.invoicesDb = invoicesDb;
              try { localStorage.setItem("invoices", JSON.stringify(invoicesDb)); } catch(e){}
            }
          }
        }

        // PRODUCTS (Incremental Delta / Authoritative Full)
        if (prodRes && prodRes.ok && Array.isArray(prodRes.products)) {
          let _dpri = [];
          try { _dpri = JSON.parse(localStorage.getItem("deleted_product_ids")) || []; } catch(e){}
          const productsCleared = (typeof localStorage !== 'undefined' && localStorage.getItem("products_cleared") === "true");

          let validServerProds = prodRes.products.filter(sp => sp && sp.id && !_dpri.includes(String(sp.id)));

          if (productsCleared) {
            productsDb = [];
            window.productsDb = productsDb;
            try { localStorage.setItem("products", "[]"); } catch(e){}
          } else if (syncOpts.since) {
            if (validServerProds.length > 0) {
              const prodMap = new Map((productsDb || []).map(p => [p.id, p]));
              validServerProds.forEach(sp => {
                prodMap.set(sp.id, Object.assign({}, prodMap.get(sp.id) || {}, sp));
              });
              productsDb = Array.from(prodMap.values());
              window.productsDb = productsDb;
              hasProductsChanged = true;
              try { localStorage.setItem("products", JSON.stringify(productsDb)); } catch(e){}
              if (window.TurboIndexedDB && typeof window.TurboIndexedDB.saveAllProducts === 'function') {
                window.TurboIndexedDB.saveAllProducts(productsDb);
              }
            }
          } else {
            const nowMs = Date.now();
            const recentMut = window.recentProductMutations || {};
            const timeSinceLastWrite = nowMs - (window._lastWriteTimestamp || 0);

            const serverProdMap = new Map();
            validServerProds.forEach(sp => {
              if (!sp || !sp.id) return;
              const descKey = (sp.description || '').trim().toLowerCase();
              const mutTime = recentMut[sp.id] || recentMut[sp.description] || recentMut[descKey] || 0;
              if (nowMs - mutTime < 30000 || timeSinceLastWrite < 15000) {
                const localP = (productsDb || []).find(lp => lp && (lp.id === sp.id || (lp.description && lp.description.trim().toLowerCase() === descKey)));
                if (localP && !_dpri.includes(String(localP.id))) {
                  serverProdMap.set(sp.id, localP);
                  return;
                }
              }
              serverProdMap.set(sp.id, sp);
            });

            if (!productsCleared) {
              (productsDb || []).forEach(lp => {
                if (lp && lp.id && !serverProdMap.has(lp.id) && !_dpri.includes(String(lp.id))) {
                  const descKey = (lp.description || '').trim().toLowerCase();
                  const mutTime = recentMut[lp.id] || recentMut[lp.description] || recentMut[descKey] || 0;
                  if (nowMs - mutTime < 30000) {
                    serverProdMap.set(lp.id, lp);
                  }
                }
              });
            }

            const mergedProducts = Array.from(serverProdMap.values());
            const prodFingerprint = mergedProducts.length + '_' + mergedProducts.map(p => (p.id || '') + ':' + (p.stock ?? '') + ':' + (p.price ?? '')).sort().slice(0, 15).join('|');
            if (prodFingerprint !== window._lastProdFingerprint) {
              window._lastProdFingerprint = prodFingerprint;
              hasProductsChanged = true;
              productsDb = mergedProducts;
              window.productsDb = productsDb;
              try { localStorage.setItem("products", JSON.stringify(productsDb)); } catch(e){}
            }
          }
        }

        // CUSTOMERS (Incremental Delta / Authoritative Full)
        if (custRes && custRes.ok && Array.isArray(custRes.customers)) {
          if (syncOpts.since) {
            if (custRes.customers.length > 0) {
              const custMap = new Map((partiesDb || []).map(c => [c.id, c]));
              custRes.customers.forEach(sc => {
                custMap.set(sc.id, Object.assign({}, custMap.get(sc.id) || {}, sc));
              });
              partiesDb = Array.from(custMap.values());
              window.partiesDb = partiesDb;
              hasPartiesChanged = true;
              try { localStorage.setItem("parties", JSON.stringify(partiesDb)); } catch(e){}
              if (window.TurboIndexedDB && typeof window.TurboIndexedDB.saveAllParties === 'function') {
                window.TurboIndexedDB.saveAllParties(partiesDb);
              }
            }
          } else {
            const custFingerprint = custRes.customers.length + '_' + custRes.customers.map(c => (c.id || '') + ':' + (c.name || '') + ':' + (c.type || '')).sort().slice(0, 15).join('|');
            if (custFingerprint !== window._lastCustFingerprint) {
              window._lastCustFingerprint = custFingerprint;
              hasPartiesChanged = true;
              partiesDb = custRes.customers;
              window.partiesDb = partiesDb;
              try { localStorage.setItem("parties", JSON.stringify(partiesDb)); } catch(e){}
            }
          }
        }

        if (setRes && setRes.ok && setRes.settings) {
          globalSettings = Object.assign({}, globalSettings, setRes.settings);
          window.globalSettings = globalSettings;
          try {
            localStorage.setItem("settings", JSON.stringify(globalSettings));
            if (Array.isArray(setRes.settings.authorizedUsers)) {
              localStorage.setItem("authorized_users", JSON.stringify(setRes.settings.authorizedUsers));
            }
          } catch(e){}
          if (typeof window.renderUserManagerTable === 'function') {
            window.renderUserManagerTable();
          }
        }

        window._lastCloudSyncTimestamp = syncStartTime;

        // Silent non-blinking UI updates: only re-render if data ACTUALLY changed and user is on that view
        const activeTab = document.querySelector('.content-view:not(.hidden)')?.id || '';
        const isTyping = document.activeElement && ['INPUT', 'TEXTAREA', 'SELECT'].includes(document.activeElement.tagName);

        if ((hasInvoicesChanged || forceReload) && !isTyping) {
          if (activeTab === 'view-history' && typeof renderHistoryTableRows === 'function') {
            renderHistoryTableRows(invoicesDb);
          }
          if (activeTab === 'view-dashboard' && typeof updateDashboardOverview === "function") {
            updateDashboardOverview();
          }
        }

        if ((hasProductsChanged || forceReload) && !isTyping) {
          const timeSinceLastWrite = Date.now() - (window._lastWriteTimestamp || 0);
          if (timeSinceLastWrite >= 15000 || forceReload) {
            if (activeTab === 'view-products' && typeof loadProductsDatabaseTable === 'function') {
              loadProductsDatabaseTable();
            }
          }
        }

        if ((hasPartiesChanged || forceReload) && !isTyping) {
          if (activeTab === 'view-parties' && typeof renderPartiesLists === 'function') {
            renderPartiesLists(partiesDb);
          }
          if (activeTab === 'view-customers' && typeof window.renderCustomersDirectoryView === "function") {
            window.renderCustomersDirectoryView();
          }
        }

        if (typeof window.updateCloudSyncBadge === "function") {
          window.updateCloudSyncBadge("synced");
        }
        return { ok: true, source: 'supabase' };
      } catch (err) {
        console.warn("[Supabase] Direct sync error:", err);
      } finally {
        isSyncing = false;
        activeSyncPromise = null;
      }
    })();
    return activeSyncPromise;
  }

  isSyncing = true;
  if (forceReload && typeof window.updateCloudSyncBadge === 'function') {
    window.updateCloudSyncBadge("syncing");
  }

  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), 25000);

  const clientHash = (lastSyncDataHash && !forceReload) ? lastSyncDataHash : "";
  const gasSyncUrl = `${GOOGLE_SCRIPT_URL}?action=sync&auth=${encodeURIComponent(API_SECRET_TOKEN)}&token=${encodeURIComponent(API_SECRET_TOKEN)}${clientHash ? `&hash=${encodeURIComponent(clientHash)}` : ''}&_t=${Date.now()}`;

  activeSyncPromise = fetch(gasSyncUrl, {
    signal: controller.signal,
    redirect: 'follow',
    cache: 'no-store',
    keepalive: true,
    priority: 'high'
  })
  .then(async (res) => {
    clearTimeout(timeoutId);
    if (!res.ok) throw new Error("HTTP sync error " + res.status);
    const text = await res.text();
    if (!text || (!text.trim().startsWith('{') && !text.trim().startsWith('['))) {
      console.warn("Google Apps Script sync returned non-JSON challenge response. Retaining local cache.");
      return null;
    }
    return JSON.parse(text);
  })
  .then((data) => {
    if (!data) return;

    // Fast 304 / notModified check
    if (data.notModified) {
      window.lastSyncTimeMs = Date.now();
      if (typeof window.updateCloudSyncBadge === 'function') window.updateCloudSyncBadge("synced");
      return;
    }

    // ★ Fast delta check: skip expensive UI rebuild if data unchanged
    const quickHash = data.hash || ((data.invoices ? data.invoices.length : 0) + '|' +
                      (data.products ? data.products.length : 0) + '|' +
                      (data.parties ? data.parties.length : 0) + '|' +
                      (data.serverTime || 0));
    if (quickHash === lastSyncDataHash && !forceReload) {
      window.lastSyncTimeMs = Date.now();
      if (typeof window.updateCloudSyncBadge === 'function') window.updateCloudSyncBadge("synced");
      return;
    }
    lastSyncDataHash = quickHash;

    if (typeof window.updateCloudSyncBadge === 'function') {
      window.updateCloudSyncBadge("synced");
    }

    if (data.serverTime) {
      window.lastSyncTimestamp = data.serverTime;
    }

    let changed = false;

    // 1. Authoritative Products directly from Google Database Master (Union Merge)
    if (Array.isArray(data.products)) {
      const serverProdMap = new Map();
      const recentMut = {};
      try { Object.assign(recentMut, JSON.parse(localStorage.getItem("recent_product_mutations") || "{}")); } catch(e){}
      if (window.recentProductMutations) Object.assign(recentMut, window.recentProductMutations);
      const nowMs = Date.now();

      data.products.forEach(p => { 
        if (p && p.id) {
          const descKey = p.description ? p.description.trim().toLowerCase() : '';
          const mutTime = recentMut[p.id] || recentMut[p.description] || recentMut[descKey] || 0;
          if (nowMs - mutTime < 15000) {
            // Local mutation happened recently, DO NOT override with old server data!
            const localP = (productsDb || []).find(lp => lp.id === p.id);
            if (localP) {
              serverProdMap.set(p.id, localP);
              return;
            }
          }
          if ((!p.stock || p.stock === 0) && p.totalValue > 0 && p.price > 0) {
            p.stock = Math.round(p.totalValue / p.price);
          }
          serverProdMap.set(p.id, p); 
        }
      });
      (productsDb || []).forEach(p => {
        if (p && p.id && !serverProdMap.has(p.id)) {
          serverProdMap.set(p.id, p);
          if (window.TurboOutboxQueue && navigator.onLine) {
            window.TurboOutboxQueue.enqueue("save_products", { products: productsDb });
          }
        }
      });
      productsDb = Array.from(serverProdMap.values());
      window.productsDb = productsDb;
      try { localStorage.setItem("products", JSON.stringify(productsDb)); } catch(e){}
      if (window.TurboIndexedDB) window.TurboIndexedDB.saveAllProducts(productsDb);
      changed = true;
    }

    // 2. Authoritative Parties directly from Google Database Master (Union Merge)
    if (Array.isArray(data.parties)) {
      const serverPartyMap = new Map();
      data.parties.forEach(p => { if (p && p.id) serverPartyMap.set(p.id, p); });
      (partiesDb || []).forEach(p => {
        if (p && p.id && !serverPartyMap.has(p.id)) {
          serverPartyMap.set(p.id, p);
          if (window.TurboOutboxQueue && navigator.onLine) {
            window.TurboOutboxQueue.enqueue("save_parties", { parties: partiesDb });
          }
        }
      });
      partiesDb = Array.from(serverPartyMap.values());
      window.partiesDb = partiesDb;
      try { localStorage.setItem("parties", JSON.stringify(partiesDb)); } catch(e){}
      if (window.TurboIndexedDB) window.TurboIndexedDB.saveAllParties(partiesDb);
      changed = true;
    }

    // 3. Authoritative Invoices directly from Google Database Master (Union Merge with Zero Data Loss)
    if (Array.isArray(data.invoices)) {
      const tombstones = typeof window.getDeletedInvoiceTombstones === 'function' ? window.getDeletedInvoiceTombstones() : [];
      const deletedSet = new Set(tombstones.map(t => String(t || '').trim().toLowerCase()));
      const historyClearedAt = parseInt(localStorage.getItem("database_history_cleared_at") || "0", 10);

      const unifiedMap = new Map();

      // Step A: Add all valid server invoices
      data.invoices.forEach(inv => {
        if (!inv) return;
        if (Array.isArray(inv.items)) {
          inv.items.forEach(it => { if (it && it.description) it.description = it.description.replace(/\u200B/g, ''); });
        }
        if (inv.details && Array.isArray(inv.details.items)) {
          inv.details.items.forEach(it => { if (it && it.description) it.description = it.description.replace(/\u200B/g, ''); });
        }
        const id = String(inv.id || (inv.details && inv.details.id) || '').trim();
        const invNo = String(inv.invoiceNo || (inv.details && inv.details.invoiceNo) || '').trim().toLowerCase();
        // if (id && deletedSet.has(id.toLowerCase())) return;
        // if (invNo && deletedSet.has(invNo)) return;

        // Discard legacy server invoices created before the last history reset
        const invTime = new Date(inv.date || inv.invoiceDate || inv.createdAt || 0).getTime();
        if (historyClearedAt > 0 && invTime > 0 && invTime < historyClearedAt) {
          return; // Skip stale server invoices older than history reset
        }
        if (id && deletedSet.has(id.toLowerCase())) return;
        if (invNo && deletedSet.has(invNo)) return;

        const key = id || invNo;
        if (key) unifiedMap.set(key, inv);
      });

      // Step B: Union with all local invoices so newly generated invoices NEVER disappear!
      const effectiveClearedAt = historyClearedAt;
      (invoicesDb || []).forEach(inv => {
        if (!inv) return;
        const id = String(inv.id || (inv.details && inv.details.id) || '').trim();
        const invNo = String(inv.invoiceNo || (inv.details && inv.details.invoiceNo) || '').trim().toLowerCase();
        // if (id && deletedSet.has(id.toLowerCase())) return;

        // Removed legacy local invoice discard constraint

        const hasContentB = (Array.isArray(inv.items) && inv.items.length > 0) || (inv.details && Array.isArray(inv.details.items) && inv.details.items.length > 0) || (parseFloat(inv.total) > 0);
        // if (!hasContentB && invNo && deletedSet.has(invNo)) return;
        const key = id || invNo;
        if (key && !unifiedMap.has(key)) {
          unifiedMap.set(key, inv);
          // Self-heal: ensure this local invoice is safely enqueued to push to cloud database
          if (window.TurboOutboxQueue && navigator.onLine) {
            window.TurboOutboxQueue.enqueue("save_invoice", { invoice: inv });
          }
        }
      });

      invoicesDb = window.filterOutDeletedInvoices(Array.from(unifiedMap.values()));
      invoicesDb.sort((a, b) => String(a.invoiceNo || "").localeCompare(String(b.invoiceNo || "")));
      window.invoicesDb = invoicesDb;
      try { localStorage.setItem("invoices", JSON.stringify(invoicesDb)); } catch(e){}
      if (window.TurboIndexedDB) window.TurboIndexedDB.saveAllInvoices(invoicesDb);
      changed = true;
    }

    // 4. Authoritative Settings directly from Google Database Master
    const rawSettings = data.settings || data.globalSettings;
    if (rawSettings && typeof rawSettings === 'object' && Object.keys(rawSettings).length > 0) {
      globalSettings = rawSettings;
      window.globalSettings = globalSettings;
      try { localStorage.setItem("settings", JSON.stringify(globalSettings)); } catch(e){}
      changed = true;
    }

    if (changed) {
      if (window.TurboDataStore) window.TurboDataStore.rebuildIndexes();
      if (typeof populateBillingSelectors === 'function') populateBillingSelectors();
      if (typeof loadProductsDatabaseTable === 'function') loadProductsDatabaseTable();
      if (typeof loadPartiesDatabaseLists === 'function') loadPartiesDatabaseLists();
      if (typeof loadInvoicesHistoryTable === 'function') loadInvoicesHistoryTable();
      if (typeof updateDashboardOverview === 'function') updateDashboardOverview();
      if (typeof calculateSummaryAndTable === 'function') calculateSummaryAndTable();
      if (typeof autoSuggestInvoiceNo === 'function') autoSuggestInvoiceNo();
      if (typeof renderFrequentProductsBar === 'function') renderFrequentProductsBar();
    }

    window.lastSyncTimeMs = Date.now();
    if (typeof window.updateRealtimePresenceHUD === 'function') {
      window.updateRealtimePresenceHUD("live");
    }
  })
  .catch(async (err) => {
    clearTimeout(timeoutId);
    if (err.name === 'AbortError') {
      console.warn("Google Apps Script sync timeout (>30s). Serving local/CDN database snapshot.");
      if (typeof window.updateCloudSyncBadge === 'function') window.updateCloudSyncBadge("synced");
    } else {
      console.warn("Google Apps Script sync notice:", err.message);
      if (typeof window.updateCloudSyncBadge === 'function') window.updateCloudSyncBadge("offline");
    }
    // High-speed static snapshot fallback if database is currently empty (<50ms)
    if ((!invoicesDb || invoicesDb.length === 0) || (!productsDb || productsDb.length === 0)) {
      try {
        let fallbackData = null;
        if (window.electronAPI && typeof window.electronAPI.loadInitialDb === 'function') {
          try {
            const lRes = await window.electronAPI.loadInitialDb();
            if (lRes && lRes.ok && lRes.data) fallbackData = lRes.data;
          } catch(e) {}
        }
        if (!fallbackData) {
          const fallbackRes = await fetch('initial_db.json?_t=' + Date.now()).catch(() => fetch('initial_db.json'));
          if (fallbackRes && fallbackRes.ok) {
            fallbackData = await fallbackRes.json();
          }
        }
        if (fallbackData && typeof window.hydrateFromSnapshot === 'function') {
          window.hydrateFromSnapshot(fallbackData);
        }
      } catch (fbErr) {}
    }
    if (typeof window.updateRealtimePresenceHUD === 'function') {
      window.updateRealtimePresenceHUD(navigator.onLine ? "live" : "offline");
    }
  })
  .finally(() => {
    isSyncing = false;
    activeSyncPromise = null;
    window.isInitialSyncDone = true;
  });

  return activeSyncPromise;
};

// --- HIGH-SPEED SNAPSHOT HYDRATION ENGINE (<50ms 0-WAIT SEEDING) ---
window.hydrateFromSnapshot = function(data) {
  if (!data) return;
  if (typeof window.isDemoMode === 'function' && window.isDemoMode()) {
    console.log("[DEMO MODE] Live snapshot hydration ignored in demo session.");
    return;
  }
  let changed = false;

  // 1. Hydrate Products (Strictly respect deletions & cleared state)
  const productsCleared = (typeof localStorage !== 'undefined' && localStorage.getItem("products_cleared") === "true");
  if (!productsCleared && Array.isArray(data.products) && data.products.length > 0) {
    let _dpri = [];
    try { _dpri = JSON.parse(localStorage.getItem("deleted_product_ids")) || []; } catch(e){}
    const prodMap = new Map();
    (productsDb || []).forEach(p => { if (p && p.id && !_dpri.includes(String(p.id))) prodMap.set(p.id, p); });
    data.products.forEach(p => {
      if (p && p.id && !_dpri.includes(String(p.id))) {
        if (!prodMap.has(p.id)) {
          prodMap.set(p.id, p);
          changed = true;
        } else {
          const cur = prodMap.get(p.id);
          if ((!cur.stock && p.stock) || (p.updatedAt && cur.updatedAt && new Date(p.updatedAt) > new Date(cur.updatedAt))) {
            prodMap.set(p.id, Object.assign({}, cur, p));
            changed = true;
          }
        }
      }
    });
    productsDb = Array.from(prodMap.values());
    window.productsDb = productsDb;
    try { localStorage.setItem("products", JSON.stringify(productsDb)); } catch(e){}
    if (window.TurboIndexedDB) window.TurboIndexedDB.saveAllProducts(productsDb);
  } else if (productsCleared) {
    productsDb = [];
    window.productsDb = [];
    try { localStorage.setItem("products", "[]"); } catch(e){}
  }

  // 2. Hydrate Parties
  if (Array.isArray(data.parties) && data.parties.length > 0) {
    let _dpi = [];
    try { _dpi = JSON.parse(localStorage.getItem("deleted_party_ids")) || []; } catch(e){}
    const partyMap = new Map();
    (partiesDb || []).forEach(p => { if (p && p.id) partyMap.set(p.id, p); });
    data.parties.forEach(p => {
      if (p && p.id && !_dpi.includes(String(p.id)) && !_dpi.includes(String(p.name))) {
        if (!partyMap.has(p.id)) {
          partyMap.set(p.id, p);
          changed = true;
        }
      }
    });
    partiesDb = Array.from(partyMap.values());
    window.partiesDb = partiesDb;
    try { localStorage.setItem("parties", JSON.stringify(partiesDb)); } catch(e){}
    if (window.TurboIndexedDB) window.TurboIndexedDB.saveAllParties(partiesDb);
  }

  // 3. Hydrate Invoices
  if (Array.isArray(data.invoices) && data.invoices.length > 0) {
    const invMap = new Map();
    (invoicesDb || []).forEach(inv => {
      if (!inv) return;
      const key = String(inv.id || inv.invoiceNo || '').trim();
      if (key) invMap.set(key, inv);
    });
    data.invoices.forEach(inv => {
      if (!inv) return;
      const key = String(inv.id || inv.invoiceNo || '').trim();
      if (key && !invMap.has(key)) {
        invMap.set(key, inv);
        changed = true;
      }
    });
    invoicesDb = window.filterOutDeletedInvoices(Array.from(invMap.values()));
    invoicesDb.sort((a, b) => String(a.invoiceNo || "").localeCompare(String(b.invoiceNo || "")));
    window.invoicesDb = invoicesDb;
    try { localStorage.setItem("invoices", JSON.stringify(invoicesDb)); } catch(e){}
    if (window.TurboIndexedDB) window.TurboIndexedDB.saveAllInvoices(invoicesDb);
  }

  // 4. Hydrate Settings
  const rawSettings = data.settings || data.globalSettings;
  if (rawSettings && typeof rawSettings === 'object' && Object.keys(rawSettings).length > 0) {
    if (!globalSettings || !globalSettings.company || !globalSettings.company.name) {
      globalSettings = rawSettings;
      window.globalSettings = globalSettings;
      try { localStorage.setItem("settings", JSON.stringify(globalSettings)); } catch(e){}
      changed = true;
    }
  }

  if (changed) {
    if (window.TurboDataStore) window.TurboDataStore.rebuildIndexes();
    if (typeof populateBillingSelectors === 'function') populateBillingSelectors();
    if (typeof loadProductsDatabaseTable === 'function') loadProductsDatabaseTable();
    if (typeof loadPartiesDatabaseLists === 'function') loadPartiesDatabaseLists();
    if (typeof loadInvoicesHistoryTable === 'function') loadInvoicesHistoryTable();
    if (typeof updateDashboardOverview === 'function') updateDashboardOverview();
    if (typeof calculateSummaryAndTable === 'function') calculateSummaryAndTable();
    if (typeof autoSuggestInvoiceNo === 'function') autoSuggestInvoiceNo();
    if (typeof renderFrequentProductsBar === 'function') renderFrequentProductsBar();
  }
};

// --- ONE-CLICK CLOUD SYNC FOR HEADER BUTTON (HIGH-SPEED REAL-TIME & CLOUD MESH) ---
window.quickSyncCloud = async function(btnEl) {
  let origHtml = "";
  if (btnEl) {
    origHtml = btnEl.innerHTML;
    btnEl.innerHTML = '<i class="fa-solid fa-arrows-rotate fa-spin"></i> <span>Syncing...</span>';
    btnEl.disabled = true;
  }
  try {
    if (typeof window.updateCloudSyncBadge === 'function') {
      window.updateCloudSyncBadge("syncing");
    }

    // Step 1: Real-time P2P Mesh query (<15ms)
    if (typeof broadcastInterTabEvent === 'function') {
      broadcastInterTabEvent('SYNC_REQUEST', { requesterId: MY_SYNC_CLIENT_ID });
    }
    if (typeof window.broadcastDatabaseMutation === 'function') {
      window.broadcastDatabaseMutation();
    }

    // Step 2: Instant local snapshot fetch (<50ms)
    try {
      let initData = null;
      if (window.electronAPI && typeof window.electronAPI.loadInitialDb === 'function') {
        try {
          const lRes = await window.electronAPI.loadInitialDb();
          if (lRes && lRes.ok && lRes.data) initData = lRes.data;
        } catch(e) {}
      }
      if (!initData) {
        const initRes = await fetch('initial_db.json?_t=' + Date.now(), { cache: 'no-store' }).catch(() => fetch('initial_db.json'));
        if (initRes && initRes.ok) {
          initData = await initRes.json();
        }
      }
      if (initData && typeof window.hydrateFromSnapshot === 'function') {
        window.hydrateFromSnapshot(initData);
      }
    } catch (e) {}

    // Immediate high-speed visual completion (<100ms)
    if (btnEl) {
      btnEl.innerHTML = `<i class="fa-solid fa-check text-success"></i> <span>⚡ Synced! (${invoicesDb.length})</span>`;
      setTimeout(() => {
        btnEl.innerHTML = origHtml;
        btnEl.disabled = false;
      }, 2500);
    }
    if (typeof showFloatingToast === 'function') {
      showFloatingToast(`⚡ High-Speed Synchronized! (${invoicesDb.length} Invoices, ${productsDb.length} Products, ${partiesDb.length} Customers)`, "success");
    }

    // Step 3: Authoritative Google Cloud Master database fetch in background (non-blocking!)
    if (typeof window.triggerDatabaseSync === 'function') {
      window.triggerDatabaseSync(true).then(() => {
        if (typeof window.updateCloudSyncBadge === 'function') {
          window.updateCloudSyncBadge("synced");
        }
      }).catch(err => {
        console.warn("Background Google Sync note:", err);
      });
    }
  } catch (err) {
    console.warn("quickSyncCloud error:", err);
    if (btnEl) {
      btnEl.innerHTML = '<i class="fa-solid fa-triangle-exclamation text-danger"></i> <span>Retry</span>';
      setTimeout(() => {
        btnEl.innerHTML = origHtml;
        btnEl.disabled = false;
      }, 3000);
    }
    if (typeof showFloatingToast === 'function') {
      showFloatingToast("⚠️ Cloud Sync notice: " + err.message, "warning");
    }
  }
};

