// High-Speed Pre-Warming Engine: keeps Google Apps Script V8 container permanently hot
(function startCloudDatabasePrewarming() {
  const pingUrl = `${GOOGLE_SCRIPT_URL}?action=ping`;
  const doPing = () => {
    if (navigator.onLine) {
      fetch(pingUrl, { mode: 'no-cors', cache: 'no-store', keepalive: true, priority: 'low' }).catch(() => {});
    }
  };
  // Gentle warm-up ping
  setTimeout(doPing, 1000);
  // Keep-alive ping every 3 minutes to keep V8 warm without spamming
  setInterval(doPing, 180000);
})();

// Auto-sync heartbeat: refresh data from Google Cloud with smart debouncing (no congestion)
(function startAutoSyncHeartbeat() {
  setInterval(() => {
    const timeSinceLastWrite = Date.now() - (window._lastWriteTimestamp || 0);
    const timeSinceLastSync = Date.now() - (window.lastSyncTimeMs || 0);
    if (navigator.onLine && !isSyncing && document.visibilityState === 'visible' && timeSinceLastWrite > 20000 && timeSinceLastSync > 40000) {
      window.triggerDatabaseSync(false);
    }
  }, 45000);

  let lastFocusSync = 0;
  window.addEventListener('focus', () => {
    const timeSinceLastWrite = Date.now() - (window._lastWriteTimestamp || 0);
    if (navigator.onLine && !isSyncing && timeSinceLastWrite > 20000 && Date.now() - lastFocusSync > 45000) {
      lastFocusSync = Date.now();
      window.triggerDatabaseSync(false);
    }
  });
})();

// ============================================================================
// ⚡ SUPABASE REALTIME STREAMING ENGINE (<40ms Low-Latency Multi-Device Push)
// ============================================================================
window._recentLocalWrites = window._recentLocalWrites || {};

window.initSupabaseRealtimeStream = function() {
  if (window._hasInitRealtimeStream) return;
  if (!window.SupabaseDB || typeof window.SupabaseDB.onRealtimeEvent !== 'function') return;
  const isDemo = (typeof window.isDemoMode === 'function' && window.isDemoMode()) ||
                 (typeof window.isViewOnlyUser === 'function' && window.isViewOnlyUser()) ||
                 (typeof sessionStorage !== 'undefined' && sessionStorage.getItem("is_demo_mode") === "true");
  if (isDemo) return;

  window._hasInitRealtimeStream = true;
  console.log("⚡ [Supabase Realtime] Connecting to PostgreSQL WebSocket change stream...");

  window.SupabaseDB.onRealtimeEvent((event) => {
    try {
      if (!event || !event.table) return;
      const { table, eventType, newRow, oldRow } = event;
      const now = Date.now();

      // 1. INVOICES STREAM (<40ms)
      if (table === 'invoices') {
        const row = newRow || oldRow;
        if (!row || !row.id) return;

        // Deduplication: Ignore echo if this client just wrote this invoice locally
        if (window._recentLocalWrites[row.id] && (now - window._recentLocalWrites[row.id] < 15000)) return;
        if (row.invoice_no && window._recentLocalWrites[row.invoice_no] && (now - window._recentLocalWrites[row.invoice_no] < 15000)) return;

        if (eventType === 'DELETE' || (newRow && newRow.is_deleted)) {
          invoicesDb = (invoicesDb || []).filter(i => i && i.id !== row.id && i.invoiceNo !== row.invoice_no);
        } else if (newRow) {
          const formattedInv = (window.SupabaseDB.rowToInvoice) ? window.SupabaseDB.rowToInvoice(newRow) : (newRow.raw_data || newRow);
          if (formattedInv) {
            const idx = (invoicesDb || []).findIndex(i => i && (i.id === row.id || i.invoiceNo === row.invoice_no));
            if (idx >= 0) {
              invoicesDb[idx] = Object.assign({}, invoicesDb[idx], formattedInv);
            } else {
              invoicesDb.unshift(formattedInv);
            }
          }
        }
        window.invoicesDb = invoicesDb;
        try { localStorage.setItem("invoices", JSON.stringify(invoicesDb)); } catch(e){}
        if (window.TurboIndexedDB && typeof window.TurboIndexedDB.saveAllInvoices === 'function') {
          window.TurboIndexedDB.saveAllInvoices(invoicesDb);
        }

        const activeTab = document.querySelector('.content-view:not(.hidden)')?.id || '';
        const isTyping = document.activeElement && ['INPUT', 'TEXTAREA', 'SELECT'].includes(document.activeElement.tagName);
        if (activeTab === 'view-history' && !isTyping && typeof renderHistoryTableRows === 'function') {
          renderHistoryTableRows(invoicesDb);
        }
        if (activeTab === 'view-dashboard' && typeof updateDashboardOverview === 'function') {
          updateDashboardOverview();
        }
        if (typeof autoSuggestInvoiceNo === 'function') autoSuggestInvoiceNo(true);
      }

      // 2. PRODUCTS STREAM (<40ms)
      else if (table === 'products') {
        const row = newRow || oldRow;
        if (!row || !row.id) return;

        if (window._recentLocalWrites[row.id] && (now - window._recentLocalWrites[row.id] < 15000)) return;

        if (eventType === 'DELETE' || (newRow && newRow.is_deleted)) {
          productsDb = (productsDb || []).filter(p => p && p.id !== row.id);
        } else if (newRow) {
          const formattedProd = (window.SupabaseDB.rowToProduct) ? window.SupabaseDB.rowToProduct(newRow) : {
            id: newRow.id,
            description: newRow.description || "",
            hsn: newRow.hsn || "230990",
            packSize: newRow.pack_size || "",
            unit: newRow.unit || "NOS",
            rate: Number(newRow.rate) || 0,
            discount: Number(newRow.discount) || 0,
            price: Number(newRow.price) || 0,
            stock: Number(newRow.stock) || 0,
            totalValue: Number(newRow.total_value) || 0,
            status: newRow.status || (Number(newRow.stock) > 0 ? "In Stock" : "Out of Stock"),
            barcode: newRow.barcode || "",
            is_deleted: false,
            updatedAt: newRow.updated_at || new Date().toISOString()
          };
          const idx = (productsDb || []).findIndex(p => p && p.id === row.id);
          if (idx >= 0) {
            productsDb[idx] = Object.assign({}, productsDb[idx], formattedProd);
          } else {
            productsDb.push(formattedProd);
          }
        }
        window.productsDb = productsDb;
        try { localStorage.setItem("products", JSON.stringify(productsDb)); } catch(e){}
        if (window.TurboIndexedDB && typeof window.TurboIndexedDB.saveAllProducts === 'function') {
          window.TurboIndexedDB.saveAllProducts(productsDb);
        }

        const activeTab = document.querySelector('.content-view:not(.hidden)')?.id || '';
        const isTyping = document.activeElement && ['INPUT', 'TEXTAREA', 'SELECT'].includes(document.activeElement.tagName);
        if (activeTab === 'view-products' && !isTyping && typeof loadProductsDatabaseTable === 'function') {
          loadProductsDatabaseTable();
        }
        if (typeof populateBillingSelectors === 'function') populateBillingSelectors();
      }

      // 3. CUSTOMERS STREAM (<40ms)
      else if (table === 'customers') {
        const row = newRow || oldRow;
        if (!row || !row.id) return;

        if (window._recentLocalWrites[row.id] && (now - window._recentLocalWrites[row.id] < 15000)) return;

        if (eventType === 'DELETE' || (newRow && newRow.is_deleted)) {
          partiesDb = (partiesDb || []).filter(c => c && c.id !== row.id);
        } else if (newRow) {
          const formattedCust = (window.SupabaseDB.rowToCustomer) ? window.SupabaseDB.rowToCustomer(newRow) : {
            id: newRow.id,
            name: newRow.name || "",
            company: newRow.company || newRow.name || "",
            type: newRow.customer_type || newRow.type || "receiver",
            phone: newRow.phone || "",
            email: newRow.email || "",
            address: newRow.address || "",
            city: newRow.city || "",
            state: newRow.state || "Andhra Pradesh",
            stateCode: newRow.state_code || "37",
            gstin: newRow.gstin || "",
            is_deleted: false,
            updatedAt: newRow.updated_at || new Date().toISOString()
          };
          const idx = (partiesDb || []).findIndex(c => c && c.id === row.id);
          if (idx >= 0) {
            partiesDb[idx] = Object.assign({}, partiesDb[idx], formattedCust);
          } else {
            partiesDb.push(formattedCust);
          }
        }
        window.partiesDb = partiesDb;
        try { localStorage.setItem("parties", JSON.stringify(partiesDb)); } catch(e){}
        if (window.TurboIndexedDB && typeof window.TurboIndexedDB.saveAllParties === 'function') {
          window.TurboIndexedDB.saveAllParties(partiesDb);
        }

        const activeTab = document.querySelector('.content-view:not(.hidden)')?.id || '';
        const isTyping = document.activeElement && ['INPUT', 'TEXTAREA', 'SELECT'].includes(document.activeElement.tagName);
        if (activeTab === 'view-parties' && !isTyping && typeof renderPartiesLists === 'function') {
          renderPartiesLists(partiesDb);
        }
        if (activeTab === 'view-customers' && !isTyping && typeof window.renderCustomersDirectoryView === 'function') {
          window.renderCustomersDirectoryView();
        }
        if (typeof populateBillingSelectors === 'function') populateBillingSelectors();
      }

      // 4. SETTINGS STREAM (<40ms)
      else if (table === 'settings') {
        if (newRow && (newRow.payload || newRow.value)) {
          const stData = newRow.payload || newRow.value;
          if (typeof stData === 'object') {
            globalSettings = Object.assign({}, globalSettings, stData);
            window.globalSettings = globalSettings;
            try { localStorage.setItem("settings", JSON.stringify(globalSettings)); } catch(e){}
            if (Array.isArray(stData.authorizedUsers)) {
              try { localStorage.setItem("authorized_users", JSON.stringify(stData.authorizedUsers)); } catch(e){}
            }
            if (typeof window.renderUserManagerTable === 'function') {
              window.renderUserManagerTable();
            }
          }
        }
      }
    } catch (err) {
      console.warn("[Supabase Realtime Stream] Event error:", err);
    }
  });
};

// --- SECURE GOOGLE DRIVE PDF ARCHIVE & CLOUD SYNC ENGINE ---
async function uploadInvoicePdfToGoogleDrive(invoiceDetails, pdfBase64) {
  if (!invoiceDetails || !pdfBase64) {
    console.warn("uploadInvoicePdfToGoogleDrive: Missing details or pdfBase64");
    return null;
  }

  const invoiceNo = String(invoiceDetails.invoiceNo || invoiceDetails.id || "INV").trim();
  const filename = `Invoice_${invoiceNo}.pdf`;

  const payload = {
    action: "upload_pdf",
    auth: API_SECRET_TOKEN,
    token: API_SECRET_TOKEN,
    invoiceNo: invoiceNo,
    filename: filename,
    pdfBase64: pdfBase64
  };

  try {
    const res = await fetch(GOOGLE_SCRIPT_URL, {
      method: "POST",
      headers: { "Content-Type": "text/plain;charset=utf-8" },
      body: JSON.stringify(payload),
      redirect: "follow"
    });

    if (res.ok) {
      const data = await res.json();
      if (data && data.ok && (data.pdfUrl || data.viewUrl)) {
        const publicUrl = data.viewUrl || data.pdfUrl;
        console.log(`☁️ Successfully saved PDF to Google Drive: ${publicUrl}`);

        invoiceDetails.pdfUrl = publicUrl;
        if (invoiceDetails.details) invoiceDetails.details.pdfUrl = publicUrl;

        const idx = invoicesDb.findIndex(i => i.id === invoiceDetails.id || String(i.invoiceNo) === String(invoiceNo));
        if (idx > -1) {
          invoicesDb[idx].pdfUrl = publicUrl;
          if (invoicesDb[idx].details) invoicesDb[idx].details.pdfUrl = publicUrl;
          try { localStorage.setItem("invoices", JSON.stringify(invoicesDb)); } catch (e) {}
        }

        if (typeof showFloatingToast === "function") {
          showFloatingToast(`☁️ Invoice #${invoiceNo} PDF saved to Google Drive!`, "success");
        }
        return publicUrl;
      } else {
        console.warn("Google Drive upload API returned notice:", data?.error);
      }
    }
  } catch (err) {
    console.warn("Network error during Google Drive PDF upload, queueing in persistent outbox:", err.message);
  }

  // Resilient offline fallback: Queue in AaryanDB outbox for auto-retry
  try {
    if (window.AaryanDB && typeof window.AaryanDB.enqueueOutbox === "function") {
      window.AaryanDB.enqueueOutbox("pdf", "upload_pdf", payload);
      console.log(`📥 Invoice #${invoiceNo} PDF queued in offline outbox for automatic retry.`);
    }
  } catch (queueErr) {
    console.warn("Could not queue PDF in outbox:", queueErr);
  }

  return null;
}
window.uploadInvoicePdfToGoogleDrive = uploadInvoicePdfToGoogleDrive;

// --- DATABASE TELEMETRY & STATUS HUD ---
window.openDatabaseTelemetryModal = async function() {
  const modal = window.showAppModal("database-telemetry-modal");
  if (!modal) return;

  const pingValEl = document.getElementById("telemetry-ping-ms");
  const ramCountEl = document.getElementById("telemetry-ram-count");
  const outboxCountEl = document.getElementById("telemetry-outbox-count");
  const quotaEl = document.getElementById("telemetry-storage-quota");
  const interTabEl = document.getElementById("telemetry-intertab-status");

  if (interTabEl) {
    const meshConnected = realtimeMeshClient && realtimeMeshClient.connected;
    interTabEl.innerHTML = meshConnected 
      ? `⚡ <strong>${activeBrokerName}</strong> (Active &lt;20ms)<br><span style="font-size:11px;color:#059669;"><i class="fa-solid fa-bolt"></i> Local LAN Companion Sync Active (Port 3001)</span>` 
      : (interTabChannel ? "Connected (0.05ms P2P BroadcastChannel)" : "Single Tab Mode");
  }

  if (ramCountEl) {
    ramCountEl.innerHTML = `<strong>${invoicesDb.length}</strong> Invoices • <strong>${productsDb.length}</strong> Products • <strong>${partiesDb.length}</strong> Customers`;
  }

  if (outboxCountEl) {
    const count = await AaryanDB.getOutboxCount();
    outboxCountEl.textContent = `${count} pending operations`;
    outboxCountEl.style.color = count > 0 ? "#f59e0b" : "#10b981";
  }

  if (quotaEl && navigator.storage && navigator.storage.estimate) {
    try {
      const estimate = await navigator.storage.estimate();
      const usedMb = ((estimate.usage || 0) / (1024 * 1024)).toFixed(2);
      const quotaMb = ((estimate.quota || 0) / (1024 * 1024)).toFixed(0);
      quotaEl.textContent = `${usedMb} MB used (${quotaMb} MB allocated quota)`;
    } catch (e) {
      quotaEl.textContent = "IndexedDB High-Capacity Storage Ready";
    }
  }

  if (pingValEl) {
    pingValEl.innerHTML = `<i class="fa-solid fa-spinner fa-spin"></i> Measuring latency...`;
    const start = Date.now();
    try {
      const res = await fetch(GOOGLE_SCRIPT_URL + "?action=status&auth=" + encodeURIComponent(API_SECRET_TOKEN), { cache: "no-store", redirect: "follow" });
      const duration = Date.now() - start;
      pingValEl.innerHTML = `<span style="color:#10b981;font-weight:700;">${duration} ms</span> <span style="font-size:11px;color:#64748b;">(Google Apps Script API)</span>`;
    } catch (err) {
      pingValEl.innerHTML = `<span style="color:#ef4444;font-weight:700;">Offline / Fallback</span>`;
    }
  }
};

window.closeDatabaseTelemetryModal = function(e) {
  if (e && e.target && e.target.closest && e.target.closest('.modal-card') && !e.target.closest('.modal-close-btn') && !e.target.closest('.btn-secondary')) {
    return;
  }
  window.hideAppModal("database-telemetry-modal");
};

window.forcePushDatabaseToCloud = async function(btnEl) {
  let origHtml = "";
  if (btnEl) {
    origHtml = btnEl.innerHTML;
    btnEl.innerHTML = `<i class="fa-solid fa-spinner fa-spin"></i> Flushing Outbox & Pushing...`;
    btnEl.disabled = true;
  }

  try {
    await AaryanDB.drainOutbox();
    await window.triggerDatabaseSync(true);
    if (btnEl) {
      btnEl.innerHTML = `<i class="fa-solid fa-check text-success"></i> Synchronized!`;
      setTimeout(() => {
        btnEl.innerHTML = origHtml;
        btnEl.disabled = false;
      }, 2500);
    }
    if (typeof showFloatingToast === 'function') {
      showFloatingToast("⚡ Outbox flushed & database synchronized with cloud!");
    }
    window.openDatabaseTelemetryModal();
  } catch (err) {
    if (btnEl) {
      btnEl.innerHTML = `<i class="fa-solid fa-triangle-exclamation"></i> Error`;
      setTimeout(() => {
        btnEl.innerHTML = origHtml;
        btnEl.disabled = false;
      }, 2500);
    }
    showFloatingToast("⚠️ Sync notice: " + err.message, "warning");
  }
};

