window.handleInquiryEmailChange = function() {
  const input = document.getElementById("inquiry-email");
  if (!input || input.readOnly) return;
  const val = (input.value || "").trim().toLowerCase();
  const errorAlert = document.getElementById("inquiry-error-alert");
  const submitBtn = document.getElementById("btn-submit-inquiry");

  if (val && window.isEmailLocked(val)) {
    if (errorAlert) {
      errorAlert.innerHTML = '<i class="fa-solid fa-triangle-exclamation"></i> <span>⛔ The email <strong>' + (typeof escapeHtml === "function" ? escapeHtml(val) : val) + '</strong> has already sent a message and is locked. Each email is allowed only 1 message. Please enter a different email address.</span>';
      errorAlert.style.display = "flex";
    }
    if (submitBtn) submitBtn.disabled = true;
  } else {
    if (errorAlert && errorAlert.innerHTML.includes("has already sent a message and is locked")) {
      errorAlert.style.display = "none";
      errorAlert.innerHTML = "";
    }
    if (submitBtn) submitBtn.disabled = false;
  }
};

window.submitClientServiceInquiry = async function(e) {
  if (e && e.preventDefault) e.preventDefault();

  const name = (document.getElementById("inquiry-name")?.value || "").trim();
  const email = (document.getElementById("inquiry-email")?.value || "").trim().toLowerCase();
  const phone = (document.getElementById("inquiry-phone")?.value || "").trim();
  const business = (document.getElementById("inquiry-business")?.value || "").trim();
  const service = document.getElementById("inquiry-service")?.value || "Custom Software Solution";
  const industry = document.getElementById("inquiry-industry")?.value || "Aquaculture / Hatchery";
  const timeline = document.getElementById("inquiry-timeline")?.value || "Immediate (Within 1 week)";
  const requirements = (document.getElementById("inquiry-requirements")?.value || "").trim();

  const errorAlert = document.getElementById("inquiry-error-alert");
  const submitBtn = document.getElementById("btn-submit-inquiry");
  const btnText = document.getElementById("btn-submit-inquiry-text");
  const btnSpinner = document.getElementById("btn-submit-inquiry-spinner");

  const showError = (msg) => {
    if (errorAlert) {
      errorAlert.innerHTML = '<i class="fa-solid fa-triangle-exclamation"></i> <span>' + (typeof escapeHtml === "function" ? escapeHtml(msg) : msg) + '</span>';
      errorAlert.style.display = "flex";
      errorAlert.scrollIntoView({ behavior: "smooth", block: "nearest" });
    } else if (typeof showFloatingToast === "function") {
      showFloatingToast(msg, "warning", 6000);
    }
  };

  if (errorAlert) errorAlert.style.display = "none";

  // Client-side validations
  if (!name) {
    showError("Please enter your name or contact person name.");
    document.getElementById("inquiry-name")?.focus();
    return;
  }

  const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if (!email || !emailPattern.test(email)) {
    showError("Please enter a valid email address.");
    document.getElementById("inquiry-email")?.focus();
    return;
  }

  const cleanPhone = phone.replace(/[^0-9]/g, "");
  if (cleanPhone.length < 10) {
    showError("Please enter a valid 10-digit WhatsApp / phone number.");
    document.getElementById("inquiry-phone")?.focus();
    return;
  }

  // STRICT 1-TIME CHECK: Is this email already locked?
  if (window.isEmailLocked(email)) {
    showError("⛔ An inquiry with '" + email + "' has already been sent. Each email address is strictly locked to 1 message. Please send via another email address.");
    if (submitBtn) submitBtn.disabled = true;
    return;
  }

  // Set loading state
  if (submitBtn) submitBtn.disabled = true;
  if (btnText) btnText.textContent = "Submitting Inquiry...";
  if (btnSpinner) btnSpinner.classList.remove("hidden");

  try {
    const payload = {
      action: "submit_client_inquiry",
      name: name,
      email: email,
      phone: cleanPhone,
      businessName: business,
      service: service,
      industry: industry,
      timeline: timeline,
      requirements: requirements,
      device: navigator.userAgent || "Desktop Web",
      submittedAt: new Date().toISOString()
    };

    const targetUrl = typeof GOOGLE_SCRIPT_URL !== "undefined"
      ? GOOGLE_SCRIPT_URL
      : "https://script.google.com/macros/s/AKfycbxHi4L_xLrfRhx1KWxRxQD1QcqbVEZVMcYR37DJEGSPe2ykZyy-ATnYyZFxnSySS6OF/exec";

    const res = await fetch(targetUrl, {
      method: "POST",
      headers: { "Content-Type": "text/plain;charset=utf-8" },
      body: JSON.stringify(payload)
    });

    const result = await res.json();

    if (result && result.duplicate) {
      // DUPLICATE EMAIL DETECTED BY BACKEND! Lock it immediately!
      window.lockInquiryEmail(email);

      const formState = document.getElementById("inquiry-state-form");
      const alreadySubmittedState = document.getElementById("inquiry-state-already-submitted");
      if (formState) formState.style.display = "none";
      if (alreadySubmittedState) {
        alreadySubmittedState.style.display = "block";
        const emailEl = document.getElementById("already-submitted-email-text");
        if (emailEl) emailEl.textContent = email;
        const waBtn = document.getElementById("btn-inquiry-direct-whatsapp");
        if (waBtn) {
          waBtn.href = "https://wa.me/918367047947?text=" + encodeURIComponent(
            "Hello Jagan, I previously submitted an inquiry with " + email + ". Can we connect directly regarding my project?"
          );
        }
      }
      if (typeof showFloatingToast === "function") {
        showFloatingToast("Notice: An inquiry with this email already exists. It is now locked.", "info", 6000);
      }
      return;
    }

    if (result && (result.ok || result.success)) {
      // SUCCESS! Lock this email permanently so it can NEVER send again!
      window.lockInquiryEmail(email);

      // Transition to celebratory success state
      const formState = document.getElementById("inquiry-state-form");
      const successState = document.getElementById("inquiry-state-success");
      if (formState) formState.style.display = "none";
      if (successState) {
        successState.style.display = "block";
        const clientNameEl = document.getElementById("success-client-name");
        if (clientNameEl) clientNameEl.textContent = name;
        const clientEmailEl = document.getElementById("success-client-email");
        if (clientEmailEl) clientEmailEl.textContent = email;
        const summaryServiceEl = document.getElementById("success-summary-service");
        if (summaryServiceEl) summaryServiceEl.textContent = service;
        const lockedEmailPill = document.getElementById("success-locked-email-pill");
        if (lockedEmailPill) lockedEmailPill.textContent = email;

        const waLink = document.getElementById("success-whatsapp-link");
        if (waLink) {
          waLink.href = "https://wa.me/918367047947?text=" + encodeURIComponent(
            "Hello Jagan, I just submitted my project requirements for " + service + " (" + (business || name) + ") from email " + email + ". Excited to connect!"
          );
        }
      }

      if (typeof showFloatingToast === "function") {
        showFloatingToast("🚀 Message delivered directly to Kandukuri Jagan's inbox! Email " + email + " is now locked from further messages.", "success", 8000);
      }
    } else {
      showError(result?.error || result?.message || "Failed to submit inquiry. Please try again or chat directly on WhatsApp.");
    }

  } catch (err) {
    console.error("submitClientServiceInquiry error:", err);
    showError("Could not reach cloud server. You can message Jagan directly on WhatsApp (+91 8367047947).");
  } finally {
    if (submitBtn) submitBtn.disabled = false;
    if (btnText) btnText.textContent = "Submit Project Requirements";
    if (btnSpinner) btnSpinner.classList.add("hidden");
  }
};


// Legacy helper replacement
window.isCustomerAccountOriginal = function() {
  const currentEmail = (sessionStorage.getItem("current_user_email") || localStorage.getItem("last_logged_in_email") || "").toLowerCase().trim();
  const mainAdminEmail = (window.AUTHORIZED_LOGIN_EMAIL || "kandukurijagan99@gmail.com").toLowerCase().trim();
  if (currentEmail === mainAdminEmail) return false;
  if (sessionStorage.getItem("is_main_admin") === "true") return false;

  const currentRole = (typeof window.getCurrentResolvedRole === 'function') ? window.getCurrentResolvedRole() : (sessionStorage.getItem("current_user_role") || "admin");
  return currentRole === "customer";
};

// --- NUMBER TO WORDS ENGINE (INDIAN RUPEES SYSTEM) ---
function convertNumberToWords(num) {
  if (num === 0) return 'Zero';
  
  let str = parseFloat(num).toFixed(2).toString();
  let parts = str.split('.');
  let integerPart = parseInt(parts[0], 10);
  let decimalPart = parts[1] ? parseInt(parts[1].substring(0, 2), 10) : 0;
  
  let result = '';
  
  if (integerPart > 0) {
    result += helper(integerPart) + ' Rupees';
  }
  
  if (decimalPart > 0) {
    if (result !== '') {
      result += ' and ';
    }
    result += helper(decimalPart) + ' Paisa';
  }
  
  if (result !== '') {
    result += ' Only';
  }
  
  // Guard against duplicate phrases
  result = result.replace(/(\s*Rupees)+/gi, ' Rupees');
  result = result.replace(/(\s*Only)+/gi, ' Only');
  result = result.replace(/Rupees\s+Only\s+Rupees\s+Only/gi, 'Rupees Only');
  
  return result;
}

function helper(n) {
  const ones = ['', 'One', 'Two', 'Three', 'Four', 'Five', 'Six', 'Seven', 'Eight', 'Nine', 'Ten', 
                'Eleven', 'Twelve', 'Thirteen', 'Fourteen', 'Fifteen', 'Sixteen', 'Seventeen', 'Eighteen', 'Nineteen'];
  const tens = ['', '', 'Twenty', 'Thirty', 'Forty', 'Fifty', 'Sixty', 'Seventy', 'Eighty', 'Ninety'];
  
  if (n < 20) return ones[n];
  if (n < 100) return tens[Math.floor(n / 10)] + (n % 10 !== 0 ? ' ' + ones[n % 10] : '');
  
  if (n < 1000) {
    return ones[Math.floor(n / 100)] + ' Hundred' + (n % 100 !== 0 ? ' ' + helper(n % 100) : '');
  }
  if (n < 100000) {
    return helper(Math.floor(n / 1000)) + ' Thousand' + (n % 1000 !== 0 ? ' ' + helper(n % 1000) : '');
  }
  if (n < 10000000) {
    return helper(Math.floor(n / 100000)) + ' Lakh' + (n % 100000 !== 0 ? ' ' + helper(n % 100000) : '');
  }
  return helper(Math.floor(n / 10000000)) + ' Crore' + (n % 10000000 !== 0 ? ' ' + helper(n % 10000000) : '');
}

// --- INDIAN CURRENCY FORMATTER ---
function safeParseAmount(val) {
  if (val === null || val === undefined || val === '') return 0;
  if (typeof val === 'number') return isNaN(val) || !isFinite(val) ? 0 : val;
  const cleaned = String(val).replace(/[^0-9.-]/g, '');
  const parsed = parseFloat(cleaned);
  return isNaN(parsed) || !isFinite(parsed) ? 0 : parsed;
}

function formatCurrency(val) {
  if (val === null || val === undefined || val === '') return '0.00';
  if (typeof val === 'string') {
    val = parseFloat(val.replace(/[^0-9.-]/g, ''));
  }
  if (isNaN(val) || !isFinite(val)) return '0.00';
  let num = parseFloat(val).toFixed(2);
  let parts = num.split('.');
  let integerPart = parts[0];
  let decimalPart = parts[1];
  
  let lastThree = integerPart.substring(integerPart.length - 3);
  let otherNumbers = integerPart.substring(0, integerPart.length - 3);
  if (otherNumbers !== '') {
    lastThree = ',' + lastThree;
  }
  let res = otherNumbers.replace(/\B(?=(\d{2})+(?!\d))/g, ",") + lastThree + '.' + decimalPart;
  return res;
}

function formatTaxValue(val) {
  if (val === 0 || isNaN(val) || val === null) {
    return 'NIL';
  }
  return '₹ ' + formatCurrency(val);
}

// --- INITIALIZE SPA DASHBOARD ---
function initializeApp() {

  // Product data is now managed exclusively via the Google Cloud Master Database

  seedDatabasesIfEmpty();
  loadAllDatabases();

  // Instant Cache-First 0ms rendering from local cache
  window.isInitialSyncDone = true;
  updateDashboardOverview();
  calculateSummaryAndTable();
  autoSuggestInvoiceNo(true);
  loadProductsDatabaseTable();
  loadPartiesDatabaseLists();
  loadInvoicesHistoryTable();

  if (typeof initAudioFeedback === 'function') initAudioFeedback();
  if (typeof initKeyboardShortcuts === 'function') initKeyboardShortcuts();
  if (window.AaryanDB && typeof window.AaryanDB.init === 'function') {
    window.AaryanDB.init().then(() => {
      // Background IndexedDB cache sync
    }).catch(e => console.warn("AaryanDB background init:", e));
  }

  setupRouting();
  bindBillingFormInputs();
  setupKeyboardShortcuts();

  // Initialize WhatsApp background bot real-time status monitor (SSE + Adaptive Fast Poll)
  if (typeof updateWhatsAppBotPillUI === 'function') updateWhatsAppBotPillUI(whatsappBotStatus);
  fetchWhatsAppBotStatus();
  initWhatsAppEventSource();

  // Fast non-blocking fetch of initial_db.json from local disk / static CDN (<50ms)
  const loadInitialSnapshot = () => {
    if (typeof window.isDemoMode === 'function' && window.isDemoMode()) {
      console.log("[DEMO MODE] initial_db.json fetch bypassed.");
      return;
    }
    fetch('initial_db.json?_t=' + Date.now(), { cache: 'no-store' })
      .catch(() => fetch('initial_db.json'))
      .then(r => r && r.ok ? r.json() : null)
      .then(data => {
        if (data && (data.invoices || data.products)) {
          if (typeof window.hydrateFromSnapshot === 'function') {
            window.hydrateFromSnapshot(data);
          }
        }
      })
      .catch(async () => {
        if (window.electronAPI && typeof window.electronAPI.loadInitialDb === 'function') {
          try {
            const res = await window.electronAPI.loadInitialDb();
            if (res && res.ok && res.data && typeof window.hydrateFromSnapshot === 'function') {
              window.hydrateFromSnapshot(res.data);
            }
          } catch(e) {}
        }
      });
  };
  loadInitialSnapshot();

  // Instant parallel fetch from Supabase (<500ms) for real-time live data
  const isDemoEarly = (typeof window.isDemoMode === 'function' && window.isDemoMode()) ||
                      (typeof sessionStorage !== 'undefined' && (sessionStorage.getItem("is_demo_mode") === "true" || sessionStorage.getItem("current_user_role") === "viewer")) ||
                      (typeof localStorage !== 'undefined' && localStorage.getItem("is_demo_mode") === "true");
  const curEmailEarly = ((typeof sessionStorage !== 'undefined' ? sessionStorage.getItem("current_user_email") : "") || "").toLowerCase().trim();
  const isMainAdminEarly = (typeof sessionStorage !== 'undefined' && sessionStorage.getItem("is_main_admin") === "true") || curEmailEarly === "kandukurijagan99@gmail.com" || curEmailEarly === "kandukurijagan88@gmail.com";
  const isStaffEarly = typeof window.isUserAuthorizedByAdmin === 'function' && curEmailEarly && window.isUserAuthorizedByAdmin(curEmailEarly);
  const isUnlockedEarly = (typeof localStorage !== 'undefined' && localStorage.getItem("app_authenticated") === "true" && localStorage.getItem("app_locked") !== "true" && !isDemoEarly);

  if (isDemoEarly) {
    console.log("[DEMO MODE] Supabase live invoices fetch bypassed for demo mode.");
  } else if ((isMainAdminEarly || isStaffEarly || isUnlockedEarly) && window.SupabaseDB && typeof window.SupabaseDB.fetchInvoices === 'function') {
    window.SupabaseDB.fetchInvoices().then(res => {
      if (res && res.ok && Array.isArray(res.invoices)) {
        let validInvs = res.invoices;
        if (typeof window.filterOutDeletedInvoices === 'function') {
          validInvs = window.filterOutDeletedInvoices(validInvs);
        }
        const hasCleared = (typeof localStorage !== "undefined" && (localStorage.getItem("database_history_cleared") === "true" || !!localStorage.getItem("database_history_cleared_at")));
        const clearedAt = parseInt((typeof localStorage !== "undefined" ? localStorage.getItem("database_history_cleared_at") : "0") || "0", 10);
        if (hasCleared && clearedAt > 0) {
          validInvs = validInvs.filter(inv => {
            const t = new Date(inv.date || inv.invoiceDate || inv.createdAt || 0).getTime();
            return t > clearedAt;
          });
        }
        invoicesDb = validInvs;
        window.invoicesDb = invoicesDb;
        try { localStorage.setItem("invoices", JSON.stringify(invoicesDb)); } catch(e){}
        if (typeof renderHistoryTableRows === 'function') renderHistoryTableRows(invoicesDb);
        if (typeof updateDashboardOverview === 'function') updateDashboardOverview();
        if (typeof window.renderCustomersDirectoryView === 'function') window.renderCustomersDirectoryView();
        if (typeof window.updateCloudSyncBadge === 'function') window.updateCloudSyncBadge("synced");
      }
    }).catch(err => console.warn("[Supabase] Fast boot fetch note:", err));

    if (typeof window.initSupabaseRealtimeStream === 'function') {
      window.initSupabaseRealtimeStream();
    }
  }

  // Pre-load settings & authorized users from Supabase DB early so logins and permissions work instantly
  if (window.SupabaseDB && typeof window.SupabaseDB.fetchSettings === 'function') {
    window.SupabaseDB.fetchSettings().then(setRes => {
      if (setRes && setRes.ok && setRes.settings) {
        if (typeof globalSettings !== 'undefined') {
          globalSettings = Object.assign({}, globalSettings, setRes.settings);
          try { localStorage.setItem("settings", JSON.stringify(globalSettings)); } catch(_) {}
        }
        const authUsers = setRes.settings.authorizedUsers || setRes.settings.authorized_users;
        if (Array.isArray(authUsers)) {
          window.saveAuthorizedUsersList(authUsers, true);

          // CRITICAL: Check if current logged-in user is an active authorized Admin/Staff
          const curEmail = (sessionStorage.getItem("current_user_email") || localStorage.getItem("last_logged_in_email") || "").toLowerCase().trim();
          if (curEmail && typeof window.isUserAuthorizedByAdmin === 'function' && window.isUserAuthorizedByAdmin(curEmail)) {
            const matched = authUsers.find(u => (u.email || "").toLowerCase().trim() === curEmail);
            if (matched && String(matched.status || "active").toLowerCase().trim() === "active") {
              const role = matched.role || "admin";
              const name = matched.name || curEmail.split("@")[0];
              console.log("[AUTH] Auto-upgrading active authorized user from cloud:", curEmail, role);
              sessionStorage.removeItem("is_demo_mode");
              localStorage.removeItem("is_demo_mode");
              sessionStorage.setItem("is_demo_mode", "false");
              localStorage.setItem("is_demo_mode", "false");
              sessionStorage.setItem("current_user_role", role);
              sessionStorage.setItem("current_user_name", name);
              if (typeof window.savePersistentAuthSession === 'function') {
                window.savePersistentAuthSession({ email: curEmail, name, role, isMainAdmin: false });
              }
              if (typeof window.applyRolePermissions === 'function') {
                window.applyRolePermissions(role);
              }
              if (typeof window.fetchCloudDatabase === 'function') {
                window.fetchCloudDatabase(true);
              }
              if (typeof window.initSupabaseRealtimeStream === 'function') {
                window.initSupabaseRealtimeStream();
              }
            }
          }
        }
      }
    }).catch(err => console.warn("[Supabase] Early settings boot note:", err));
  }

  // Background non-blocking Google Apps Script sync (does not block UI rendering)
  setTimeout(() => {
    if (typeof window.triggerDatabaseSync === 'function') {
      window.triggerDatabaseSync(false).catch(e => console.warn("Background sync note:", e));
    }
  }, 500);

  // Update header cloud sync status pill
  if (typeof window.updateCloudSyncBadge === 'function') {
    window.updateCloudSyncBadge(isSyncing ? "syncing" : "synced");
  }

  // Manual Trigger for Google Drive & Live Sheets Sync
  window.triggerManualGoogleDriveSync = async function(btnEl) {
    let origHtml = "";
    if (btnEl) {
      origHtml = btnEl.innerHTML;
      btnEl.innerHTML = `<i class="fa-solid fa-spinner fa-spin"></i> Syncing to Google Drive...`;
      btnEl.disabled = true;
    }

    try {
      updateCloudSyncBadge("syncing");
      if (typeof window.triggerDatabaseSync === 'function') {
        await window.triggerDatabaseSync();
      }
      updateCloudSyncBadge("synced");
      if (btnEl) {
        btnEl.innerHTML = `<i class="fa-solid fa-check text-success"></i> Synced to Google Drive!`;
        setTimeout(() => {
          btnEl.innerHTML = origHtml;
          btnEl.disabled = false;
        }, 3000);
      }
      showFloatingToast(`☁️ All data synced to your Google Drive Master Spreadsheet!`);
    } catch (err) {
      console.warn("Manual Google Drive sync error:", err);
      updateCloudSyncBadge("offline");
      if (btnEl) {
        btnEl.innerHTML = `<i class="fa-solid fa-triangle-exclamation"></i> Sync Error`;
        setTimeout(() => {
          btnEl.innerHTML = origHtml;
          btnEl.disabled = false;
        }, 3000);
      }
      showFloatingToast("⚠️ Google Drive sync notice: " + err.message, "warning");
    }
  };

  // Batch PDF Compiler & Google Drive Cloud Linker
  window.syncAndGenerateAllDrivePdfs = async function(btnEl) {
    loadAllDatabases();
    if (!invoicesDb || invoicesDb.length === 0) {
      showFloatingToast("⚠️ No invoices found to sync!", "warning");
      return;
    }

    let origHtml = "";
    if (btnEl) {
      origHtml = btnEl.innerHTML;
      btnEl.disabled = true;
    }

    const printWrapper = document.getElementById("print-invoice-wrapper");
    if (!printWrapper) {
      showFloatingToast("⚠️ Invoice print container not found.", "warning");
      if (btnEl) btnEl.disabled = false;
      return;
    }

    printWrapper.style.display = "block";
    printWrapper.style.position = "absolute";
    printWrapper.style.left = "-9999px";
    printWrapper.style.top = "0";

    const opt = {
      margin:       [0, 0, 0, 0],
      image: { type: 'jpeg', quality: 1.0 },
      html2canvas: { scale: 3.5, useCORS: true, logging: false, letterRendering: true, dpi: 300 },
      jsPDF:        { unit: 'mm', format: 'a4', orientation: 'portrait', compress: true }
    };

    let processedCount = 0;

    for (let i = 0; i < invoicesDb.length; i++) {
      const inv = invoicesDb[i];
      if (btnEl) {
        btnEl.innerHTML = `<i class="fa-solid fa-spinner fa-spin"></i> Processing PDF ${i + 1}/${invoicesDb.length} (Inv #${inv.invoiceNo})...`;
      }

      try {
        populateA4PrintOverlay(inv.details || inv);
        const element = printWrapper.querySelector('.tally-invoice-container') || printWrapper;

        const origTallyHeight = element.style.height;
        const origTallyMaxHeight = element.style.maxHeight;
        const origTallyPadding = element.style.padding;
        const origTallyOverflow = element.style.overflow;

        element.style.height = "auto";
        element.style.maxHeight = "none";
        element.style.padding = "4.5mm 7mm";
        element.style.overflow = "hidden";

        const blob = await html2pdf().from(element).set(opt).toPdf().get('pdf').then(pdf => {
          const totalPages = pdf.internal.getNumberOfPages();
          for (let p = totalPages; p > 1; p--) {
            pdf.deletePage(p);
          }
          return pdf.output('blob');
        });

        element.style.height = origTallyHeight;
        element.style.maxHeight = origTallyMaxHeight;
        element.style.padding = origTallyPadding;
        element.style.overflow = origTallyOverflow;

        const reader = new FileReader();
        const pdfBase64 = await new Promise((resolve) => {
          reader.onloadend = () => resolve(reader.result);
          reader.readAsDataURL(blob);
        });

        const uploadedUrl = await uploadInvoicePdfToGoogleDrive(inv, pdfBase64);
        if (uploadedUrl) {
          inv.pdfUrl = uploadedUrl;
          if (inv.details) inv.details.pdfUrl = uploadedUrl;
          processedCount++;
        }
      } catch (err) {
        console.warn(`Error generating PDF for invoice #${inv.invoiceNo}:`, err);
      }
    }

    printWrapper.style.display = "";
    printWrapper.style.position = "";
    printWrapper.style.left = "";

    localStorage.setItem("invoices", JSON.stringify(invoicesDb));
    if (typeof renderHistoryTableRows === 'function') {
      renderHistoryTableRows(invoicesDb);
    }

    if (btnEl) {
      btnEl.innerHTML = `<i class="fa-solid fa-check text-success"></i> All ${processedCount} PDFs Linked!`;
      setTimeout(() => {
        btnEl.innerHTML = origHtml;
        btnEl.disabled = false;
      }, 3500);
    }

    showFloatingToast(`🎉 Successfully uploaded ${processedCount} PDFs to Google Drive & updated Google Sheet!`, 5000);
  };

  // ============================================================================
  // ADAPTIVE CLOUD DATABASE SYNC ENGINE (15s CLOUD HEARTBEAT + INSTANT 0ms MESH)
  // ============================================================================
  let multiUserSyncTimer = null;
  let lastCloudSyncPoll = 0;
  let nextStaggeredPollInterval = 2000;

  async function performCloudHeartbeat(force = false) {
    const now = Date.now();
    const timeSinceLastWrite = now - (window._lastWriteTimestamp || 0);
    if (timeSinceLastWrite < 15000) {
      return; // Skip background/forced cloud poll while user is actively making changes!
    }
    if (force || (now - lastCloudSyncPoll >= 15000)) {
      lastCloudSyncPoll = now;
      nextStaggeredPollInterval = 15000;
      try {
        if (navigator.onLine && typeof window.triggerDatabaseSync === "function" && !isSyncing) {
          await window.triggerDatabaseSync(false);
        }
      } catch (e) {}
    }
    if (!isSyncing && navigator.onLine && typeof window.updateRealtimePresenceHUD === 'function') {
      window.updateRealtimePresenceHUD("live");
    }
  }

  // Unthrottled Web Worker Heartbeat (Keeps HUD clock live and triggers 15s cloud checks even in background)
  try {
    const workerBlob = new Blob([
      "setInterval(function(){ self.postMessage('tick'); }, 15000);"
    ], { type: 'application/javascript' });
    const syncWorker = new Worker(URL.createObjectURL(workerBlob));
    syncWorker.onmessage = function(e) {
      if (e.data === 'tick') {
        performCloudHeartbeat(false);
      }
    };
  } catch (workerErr) {
    console.warn("Background worker heartbeat note, using standard interval:", workerErr);
    setInterval(() => performCloudHeartbeat(false), 15000);
  }

  // Complementary foreground heartbeat
  function scheduleNextCloudHeartbeat() {
    if (multiUserSyncTimer) clearTimeout(multiUserSyncTimer);
    multiUserSyncTimer = setTimeout(async () => {
      await performCloudHeartbeat(false);
      scheduleNextCloudHeartbeat();
    }, 15000);
  }
  scheduleNextCloudHeartbeat();

  // Sync immediately when window/tab is focused or returned to
  window.addEventListener("focus", () => {
    if (navigator.onLine && typeof window.triggerDatabaseSync === "function" && !isSyncing) {
      performCloudHeartbeat(true);
    }
  });

  // Sync immediately when tab becomes visible
  document.addEventListener("visibilitychange", () => {
    if (document.visibilityState === "visible") {
      if (navigator.onLine && typeof window.triggerDatabaseSync === "function" && !isSyncing) {
        performCloudHeartbeat(true);
      }
    }
  });

  // REAL-WORLD ENTERPRISE SESSION PERSISTENCE (Strict Main Admin Authorization)
  if (typeof window.cleanStorageOfUnauthorizedUsers === 'function') {
    window.cleanStorageOfUnauthorizedUsers();
  }

  const savedSession = (typeof window.getPersistentAuthSession === 'function') ? window.getPersistentAuthSession() : null;
  const isManuallyLocked = sessionStorage.getItem("manual_locked") === "true";
  const lockoutStatus = AppSecurity.isLockedOut();

  let canStayUnlocked = false;
  let candidateEmail = (savedSession?.email || sessionStorage.getItem("current_user_email") || "").toLowerCase().trim();

  // If candidate is an authorized admin/staff, CLEAR all demo flags!
  const isCandidateAuthorized = candidateEmail && typeof window.isUserAuthorizedByAdmin === 'function' && window.isUserAuthorizedByAdmin(candidateEmail);
  if (isCandidateAuthorized) {
    try {
      localStorage.removeItem("is_demo_mode");
      sessionStorage.removeItem("is_demo_mode");
      sessionStorage.setItem("is_demo_mode", "false");
      localStorage.setItem("is_demo_mode", "false");
    } catch(e) {}
  }

  // FREE VIEW MODE CHECK - ONLY for non-authorized users!
  const isDemoSession = !isCandidateAuthorized && (
    sessionStorage.getItem("is_demo_mode") === "true" || 
    localStorage.getItem("is_demo_mode") === "true" || 
    savedSession?.role === "viewer" ||
    (typeof window.isViewOnlyUser === 'function' && candidateEmail && window.isViewOnlyUser(candidateEmail))
  );
  if (isDemoSession) {
    canStayUnlocked = true;
    isLocked = false;
    localStorage.removeItem("app_locked");
    document.body.classList.remove("app-is-locked");
    const lockOverlay = document.getElementById("lock-screen-overlay");
    if (lockOverlay) {
      lockOverlay.classList.add("hidden");
      lockOverlay.style.setProperty("display", "none", "important");
    }
    const wrapper = document.querySelector('.dashboard-wrapper');
    if (wrapper) wrapper.classList.remove("blur-dashboard-wrapper");

    if (typeof window.loginAsFreeViewer === 'function') {
      window.loginAsFreeViewer({
        email: candidateEmail || "demo@viewer.com",
        name: sessionStorage.getItem("current_user_name") || savedSession?.name || "Prospective Buyer"
      });
    }
    // Free viewers go directly to billing tab
    setTimeout(() => {
      if (typeof window.switchTab === 'function') {
        window.switchTab('billing');
      }
    }, 50);
    return;
  }

  // STRICT AUDIT: If currently stored email is not authorized by Main Admin and NOT in demo mode, purge!
  if (candidateEmail && typeof window.isUserAuthorizedByAdmin === 'function' && !window.isUserAuthorizedByAdmin(candidateEmail)) {
    console.warn("Purging unauthorized session on boot for:", candidateEmail);
    if (typeof window.clearPersistentAuthSession === 'function') {
      window.clearPersistentAuthSession();
    }
    sessionStorage.clear();
    localStorage.removeItem("aaryan_auth_session");
    localStorage.removeItem("app_authenticated");
    localStorage.setItem("app_locked", "true");
    candidateEmail = "";
  }

  if (candidateEmail && typeof window.isUserAuthorizedByAdmin === 'function' && window.isUserAuthorizedByAdmin(candidateEmail) && !isManuallyLocked && !lockoutStatus.locked) {
    const isMainAdmin = (candidateEmail === window.AUTHORIZED_LOGIN_EMAIL.toLowerCase().trim());
    const usersList = (typeof window.getAuthorizedUsersList === 'function') ? window.getAuthorizedUsersList() : [];
    const matchedUser = isMainAdmin
      ? { status: "active", role: "super_admin", name: "Jagan (Main Admin)" }
      : usersList.find(u => (u.email || "").toLowerCase().trim() === candidateEmail && u.status === "active");

    if (matchedUser) {
      canStayUnlocked = true;
      const role = matchedUser.role || "customer";
      const name = matchedUser.name || (isMainAdmin ? "Jagan (Main Admin)" : candidateEmail.split("@")[0]);
      sessionStorage.setItem("session_authenticated", "true");
      sessionStorage.setItem("current_user_email", candidateEmail);
      sessionStorage.setItem("current_user_name", name);
      sessionStorage.setItem("current_user_role", role);
      sessionStorage.setItem("is_main_admin", isMainAdmin ? "true" : "false");
      sessionStorage.setItem("manual_locked", "false");
      sessionStorage.setItem("session_last_active_time", Date.now().toString());
      localStorage.setItem("app_authenticated", "true");
      localStorage.setItem("app_locked", "false");
    } else {
      if (typeof window.clearPersistentAuthSession === 'function') {
        window.clearPersistentAuthSession();
      }
      sessionStorage.clear();
      localStorage.removeItem("aaryan_auth_session");
      localStorage.removeItem("app_authenticated");
      localStorage.setItem("app_locked", "true");
    }
  }

  // Auto-migrate legacy cleartext saved_password to cryptographic SHA-256 token
  const savedPwd = localStorage.getItem("saved_password") || "";
  if (savedPwd) {
    AppSecurity.purgePlaintextPasswords();
  }

  // Counter Privacy Shield: Always UNBLURRED by default to guarantee 100% financial clarity
  document.body.classList.remove("counter-privacy-active", "strict-privacy-enabled");
  try {
    localStorage.setItem("counter_privacy_mode", "false");
    if (globalSettings && globalSettings.security) {
      globalSettings.security.counterPrivacyMode = false;
    }
  } catch (e) {}

  if (canStayUnlocked) {
    unlockSystemSilently(false);
    const roleToApply = (typeof window.getCurrentResolvedRole === 'function') ? window.getCurrentResolvedRole() : (sessionStorage.getItem("current_user_role") || "admin");
    if (typeof window.applyRolePermissions === 'function') {
      window.applyRolePermissions(roleToApply);
    }
  } else {
    // STRICT LOCKOUT: System must remain securely locked behind authentication overlay!
    const lockReason = isManuallyLocked ? "manual" : "initial";
    triggerLockOverlay(lockReason, false);
    document.body.classList.add("app-is-locked");
    const overlay = document.getElementById("lock-screen-overlay");
    if (overlay) {
      overlay.classList.remove("hidden");
      overlay.style.setProperty("display", "flex", "important");
    }
    autofillRememberedCredentials();
  }

  // Reset lock timer on activity and start live session timing ticker
  resetAutolockTimer();
  if (typeof startSessionTimerTick === 'function') {
    startSessionTimerTick();
  }
  ['mousemove', 'mousedown', 'keydown', 'touchstart', 'scroll', 'wheel', 'click'].forEach(evt => {
    document.addEventListener(evt, resetAutolockTimer, { passive: true, capture: true });
  });

  // Background Tab Inactivity Auto-Lock (visibilitychange listener)
  document.addEventListener("visibilitychange", function() {
    if (document.hidden) {
      sessionStorage.setItem("tab_hidden_timestamp", Date.now().toString());
    } else {
      const hiddenTimeStr = sessionStorage.getItem("tab_hidden_timestamp") || localStorage.getItem("tab_hidden_timestamp");
      if (hiddenTimeStr) {
        const hiddenTime = parseInt(hiddenTimeStr, 10);
        const elapsedSec = (Date.now() - hiddenTime) / 1000;
        const lockThreshold = (typeof lockTimerSeconds !== "undefined" && lockTimerSeconds > 0) ? lockTimerSeconds : 1800;
        if (lockThreshold > 0 && elapsedSec >= lockThreshold && !isLocked) {
          AppSecurity.logEvent("BACKGROUND_AUTOLOCK", `App locked after ${Math.round(elapsedSec)}s inactive in background tab`, "INFO");
          triggerLockOverlay("inactivity_timeout", true);
        } else if (!isLocked) {
          resetAutolockTimer();
        }
        sessionStorage.removeItem("tab_hidden_timestamp");
        localStorage.removeItem("tab_hidden_timestamp");
      }
    }
  });

  // Default suggestions
  resetBillingForm();
  updateDashboardOverview();
  updateLiveDateTime();
  setInterval(updateLiveDateTime, 1000);

  // Initialize Google Ads & Analytics Engine (v423)
  if (typeof window.initGoogleAdsAndAnalytics === 'function') {
    window.initGoogleAdsAndAnalytics();
  }

  // Mobile touch/click fast-response listener for Generate & Save Invoice
  const saveBtn = document.getElementById("btn-save-generate-invoice");
  if (saveBtn) {
    let lastTapTime = 0;
    saveBtn.addEventListener("touchend", (e) => {
      const now = Date.now();
      if (now - lastTapTime < 450) return;
      lastTapTime = now;
      if (e.cancelable) e.preventDefault();
      window.saveAndGenerateInvoiceOnly(saveBtn);
    }, { passive: false });
  }

  window.addEventListener('resize', () => {
    if (window.innerWidth > 768) {
      closeMobileSidebar();
    }
  });

  // Service Worker disabled to prevent file caching issues
  /*
  if ('serviceWorker' in navigator) {
    navigator.serviceWorker.register('./sw.js').then(reg => {
      reg.update();
    }).catch(err => {
      console.log('SW registration failed:', err);
    });
  }
  */
}

