async function sendTelegramInvoiceNotification(invoice) {
  const token = globalSettings.telegram?.token;
  const chat = globalSettings.telegram?.chatId;

  if (!token || !chat) return;

  const chatIds = chat.split(/[\s,]+/).filter(id => id.trim() !== "");
  if (chatIds.length === 0) return;

  try {
    const textMsg = `🔔 NEW INVOICE GENERATED!\n` +
                    `-------------------------\n` +
                    `Invoice No : #${invoice.invoiceNo} (${invoice.details?.invoiceType || 'Invoice'})\n` +
                    `Date       : ${formatInputDateString(invoice.invoiceDate)}\n` +
                    `Customer   : ${invoice.customerName}\n` +
                    `Items      : ${invoice.itemsCount} products\n` +
                    `Grand Total: ₹ ${formatCurrency(invoice.total)}\n` +
                    `Payment    : ${invoice.details?.paymentStatus || 'Paid'} via ${invoice.details?.paymentMode || 'Cash'}\n` +
                    `-------------------------\n` +
                    `Aaryan Aqua Needs billing system`;

    const text = encodeURIComponent(textMsg);
    chatIds.forEach(id => {
      fetch(`https://api.telegram.org/bot${token}/sendMessage?chat_id=${id}&text=${text}`);
    });
  } catch (err) {
    console.error("Failed to dispatch Telegram bot notification", err);
  }
}

// --- ACTIVITY AUTO-LOCK & LIVE SESSION TIMING CONTROLLER (v422) ---
let lastActivityRecordTime = Date.now();
let sessionTimerTickInterval = null;

function formatSessionDuration(seconds) {
  if (seconds <= 0) return "00:00";
  const hrs = Math.floor(seconds / 3600);
  const mins = Math.floor((seconds % 3600) / 60);
  const secs = Math.floor(seconds % 60);
  if (hrs > 0) {
    return `${hrs}:${mins < 10 ? '0' : ''}${mins}:${secs < 10 ? '0' : ''}${secs}`;
  }
  return `${mins < 10 ? '0' : ''}${mins}:${secs < 10 ? '0' : ''}${secs}`;
}

function updateSessionTimerUI() {
  const pill = document.getElementById("live-session-timer-pill");
  if (pill) {
    pill.style.display = "none";
  }

  if (isLocked) {
    return;
  }

  if (!lockTimerSeconds || lockTimerSeconds <= 0) {
    return;
  }

  const now = Date.now();
  const lastActive = lastActivityRecordTime || now;
  const elapsedSec = Math.floor((now - lastActive) / 1000);
  const remainingSec = Math.max(0, lockTimerSeconds - elapsedSec);

  // Trigger silent background security auto-lock strictly if session timing exhausted
  if (remainingSec <= 0 && !isLocked) {
    triggerLockOverlay("inactivity_timeout", true);
  }
}

function startSessionTimerTick() {
  if (sessionTimerTickInterval) clearInterval(sessionTimerTickInterval);
  updateSessionTimerUI();
  sessionTimerTickInterval = setInterval(updateSessionTimerUI, 1000);
}

window.renewUserSession = function() {
  if (isLocked) return;
  lastActivityRecordTime = Date.now();
  sessionStorage.setItem("session_last_active_time", lastActivityRecordTime.toString());
  resetAutolockTimer();
  updateSessionTimerUI();
  const durationLabel = lockTimerSeconds > 0 ? `${Math.round(lockTimerSeconds / 60)} min` : "unlimited";
  if (typeof showFloatingToast === 'function') {
    showFloatingToast(`⏱️ Active session timing renewed (${durationLabel})!`, 2500);
  }
  if (typeof AppSecurity !== 'undefined' && AppSecurity.logEvent) {
    AppSecurity.logEvent("SESSION_RENEWED", `Session timing renewed to ${lockTimerSeconds}s`, "INFO");
  }
};

window.onAutoLockSettingChange = function(newVal) {
  const parsed = parseInt(newVal, 10);
  if (!Number.isNaN(parsed)) {
    lockTimerSeconds = parsed;
    lastActivityRecordTime = Date.now();
    sessionStorage.setItem("session_last_active_time", lastActivityRecordTime.toString());
    resetAutolockTimer();
    updateSessionTimerUI();
    const label = parsed > 0 ? `${Math.round(parsed / 60)} min` : "disabled";
    if (typeof showFloatingToast === 'function') {
      showFloatingToast(`⏱️ Session timing preview: Auto-lock set to ${label}`, 2000);
    }
  }
};

function resetAutolockTimer() {
  if (isLocked) return;

  const now = Date.now();
  window._inactivityWarningToastShown = false; // Reset warning toast flag on interaction

  if (!lastActivityRecordTime || now - lastActivityRecordTime > 2000) {
    lastActivityRecordTime = now;
    try {
      sessionStorage.setItem("session_last_active_time", now.toString());
      localStorage.setItem("last_active_time", now);
      localStorage.setItem("app_locked", "false");
    } catch (_) {}
    updateSessionTimerUI();
  }

  clearTimeout(autolockInterval);
  if (!lockTimerSeconds || lockTimerSeconds <= 0) {
    updateSessionTimerUI();
    return;
  }

  autolockInterval = setTimeout(() => {
    triggerLockOverlay("inactivity_timeout", true);
  }, lockTimerSeconds * 1000);
}

function unlockSystemSilently(shouldBroadcast = false) {
  isLocked = false;
  localStorage.setItem("app_locked", "false");
  localStorage.setItem("app_authenticated", "true");
  sessionStorage.setItem("session_authenticated", "true");
  sessionStorage.setItem("manual_locked", "false");
  lastActivityRecordTime = Date.now();
  sessionStorage.setItem("session_last_active_time", lastActivityRecordTime.toString());
  localStorage.setItem("last_active_time", lastActivityRecordTime);
  document.body.classList.remove("app-is-locked");
  
  if (typeof window.hideAppModal === 'function') {
    window.hideAppModal("lock-screen-overlay");
  } else {
    const overlay = document.getElementById("lock-screen-overlay");
    if (overlay) {
      overlay.classList.add("hidden");
      overlay.style.removeProperty("display");
      overlay.style.removeProperty("visibility");
      overlay.style.removeProperty("opacity");
      overlay.style.removeProperty("pointer-events");
      overlay.style.removeProperty("z-index");
      overlay.style.setProperty("display", "none", "important");
      overlay.style.setProperty("visibility", "hidden", "important");
      overlay.style.setProperty("opacity", "0", "important");
      overlay.style.setProperty("pointer-events", "none", "important");
      overlay.style.setProperty("z-index", "-1", "important");
    }
  }
  const wrapper = document.querySelector('.dashboard-wrapper');
  if (wrapper) {
    wrapper.classList.remove("blur-dashboard-wrapper");
    wrapper.style.removeProperty("display");
    wrapper.style.removeProperty("visibility");
    wrapper.style.removeProperty("opacity");
    wrapper.style.removeProperty("pointer-events");
  }

  // Re-render open verification modal if visible so admin controls populate
  if (window.currentVerifiedInvoiceNo && typeof openInvoiceVerificationModal === 'function') {
    const vModal = document.getElementById("invoice-verification-modal");
    if (vModal && !vModal.classList.contains("hidden")) {
      openInvoiceVerificationModal(window.currentVerifiedInvoiceNo);
    }
  }

  // Restart live session timer tick & inactivity auto-lock timer
  startSessionTimerTick();
  if (typeof resetAutolockTimer === 'function') {
    resetAutolockTimer();
  }

  // Apply user role permissions and update profile badge
  if (typeof window.applyRolePermissions === 'function') {
    window.applyRolePermissions();
  }

  if (shouldBroadcast) {
    const email = sessionStorage.getItem("current_user_email") || "";
    const name = sessionStorage.getItem("current_user_name") || "";
    const role = sessionStorage.getItem("current_user_role") || "operator";
    broadcastAuthEvent("LOGIN", { email, name, role });
  }
}
window.unlockSystemSilently = unlockSystemSilently;

