window.sendLoginOtpCodeDirectly = async function() {
  const userField = document.getElementById("login-email");
  const rawEmail = (userField?.value || "").trim();
  const enteredEmail = rawEmail.toLowerCase();
  const errBlock = document.getElementById("login-error-message");

  if (!enteredEmail || !enteredEmail.includes("@")) {
    if (errBlock) {
      errBlock.innerHTML = `
        <div style="font-weight: 700; color: #f43f5e; margin-bottom: 2px;">
          <i class="fa-solid fa-envelope"></i> Valid Email Address Required!
        </div>
        <div style="font-size: 11.5px; color: #cbd5e1;">
          Please enter your email above before requesting an OTP code.
        </div>
      `;
      errBlock.classList.remove("hidden");
    }
    if (userField) userField.focus();
    return false;
  }

  const mainAdminNorm = (window.AUTHORIZED_LOGIN_EMAIL || "kandukurijagan99@gmail.com").toLowerCase().trim();
  const isMainAdmin = (enteredEmail === mainAdminNorm);

  // STRICT BLOCK FOR SUSPENDED ACCOUNTS
  if (!isMainAdmin && typeof window.isUserSuspendedByAdmin === 'function' && window.isUserSuspendedByAdmin(enteredEmail)) {
    if (errBlock) {
      errBlock.innerHTML = `
        <div style="background: rgba(239, 68, 68, 0.18); border: 1.5px solid #ef4444; border-radius: 10px; padding: 12px 14px; text-align: left;">
          <div style="font-weight: 800; color: #f43f5e; margin-bottom: 4px; font-size: 13px;">
            <i class="fa-solid fa-user-lock"></i> Account Suspended
          </div>
          <div style="font-size: 11.5px; color: #cbd5e1;">
            Your account (<strong style="color: #fca5a5;">${escapeHtml(enteredEmail)}</strong>) has been paused by the Main Administrator. Access is blocked.
          </div>
        </div>
      `;
      errBlock.classList.remove("hidden");
    }
    showFloatingToast(`⛔ Account ${enteredEmail} is suspended by Main Admin.`, "error", 6000);
    return false;
  }

  // Clear previous error
  if (errBlock) errBlock.classList.add("hidden");

  // Generate clean 6-digit OTP
  const generatedCode = Math.floor(100000 + Math.random() * 900000).toString();
  sessionStorage.setItem("pending_login_otp", generatedCode);
  sessionStorage.setItem("pending_login_email", enteredEmail);

  // Reveal OTP container and update UI state
  const otpContainer = document.getElementById("otp-input-container");
  if (otpContainer) {
    otpContainer.style.display = "block";
  }
  const btnRequestText = document.getElementById("btn-request-mail-text");
  if (btnRequestText) {
    btnRequestText.textContent = "Resend Code to Email";
  }

  showFloatingToast(`⏳ Sending 6-digit login passcode to ${enteredEmail}...`, "info", 4500);

  // Send via Google Apps Script MailApp with origin
  let dispatched = false;
  if (typeof GOOGLE_SCRIPT_URL !== 'undefined') {
    try {
      const res = await fetch(GOOGLE_SCRIPT_URL, {
        method: "POST",
        headers: { "Content-Type": "text/plain;charset=utf-8" },
        body: JSON.stringify({
          action: "send_login_otp",
          email: enteredEmail,
          otp: generatedCode,
          origin: window.location.origin + window.location.pathname,
          token: (typeof API_SECRET_TOKEN !== 'undefined' ? API_SECRET_TOKEN : '')
        })
      });
      const data = await res.json();
      if (data && data.ok) dispatched = true;
    } catch (e) {}
  }

  if (dispatched) {
    showFloatingToast(`📩 6-digit OTP sent to ${enteredEmail}! Check your inbox.`, "success", 6000);
  } else {
    // Passcode fallback notification
    showFloatingToast(`📩 Passcode for ${enteredEmail}: [ ${generatedCode} ] (Valid for 15 mins)`, "success", 12000);
  }

  const passField = document.getElementById("login-password");
  if (passField) {
    passField.value = "";
    passField.placeholder = "Enter 6-digit code received in mail";
    passField.focus();
  }
  return true;
};

window.handleMailLoginSubmit = async function(e) {
  if (e && e.preventDefault) e.preventDefault();

  const emailField = document.getElementById("login-email");
  const otpField = document.getElementById("login-password");
  const errBlock = document.getElementById("login-error-message");
  const spinner = document.getElementById("login-btn-spinner");
  const btnText = document.getElementById("login-btn-text");

  const rawEmail = (emailField?.value || "").trim();
  const enteredEmail = rawEmail.toLowerCase();
  const enteredOtp = (otpField?.value || "").trim();

  if (!enteredEmail || !enteredEmail.includes("@")) {
    if (errBlock) {
      errBlock.innerHTML = `
        <div style="font-weight: 700; color: #f43f5e; margin-bottom: 2px;">
          <i class="fa-solid fa-envelope"></i> Email Required
        </div>
        <div style="font-size: 11.5px; color: #cbd5e1;">Please enter a valid email address.</div>
      `;
      errBlock.classList.remove("hidden");
    }
    if (emailField) emailField.focus();
    return;
  }

  const mainAdminNorm = (window.AUTHORIZED_LOGIN_EMAIL || "kandukurijagan99@gmail.com").toLowerCase().trim();
  const isMainAdmin = (enteredEmail === mainAdminNorm);

  // STRICT BLOCK FOR SUSPENDED ACCOUNTS
  if (!isMainAdmin && typeof window.isUserSuspendedByAdmin === 'function' && window.isUserSuspendedByAdmin(enteredEmail)) {
    if (errBlock) {
      errBlock.innerHTML = `
        <div style="background: rgba(239, 68, 68, 0.18); border: 1.5px solid #ef4444; border-radius: 10px; padding: 12px 14px; text-align: left;">
          <div style="font-weight: 800; color: #f43f5e; margin-bottom: 4px; font-size: 13px;">
            <i class="fa-solid fa-user-lock"></i> Account Suspended
          </div>
          <div style="font-size: 11.5px; color: #cbd5e1;">
            Your account (<strong style="color: #fca5a5;">${escapeHtml(enteredEmail)}</strong>) has been paused by the Main Administrator. Access is blocked.
          </div>
        </div>
      `;
      errBlock.classList.remove("hidden");
    }
    showFloatingToast(`⛔ Account ${enteredEmail} is suspended by Main Admin.`, "error", 6000);
    return;
  }

  // If OTP container is hidden or passcode not yet entered, send OTP first
  const otpContainer = document.getElementById("otp-input-container");
  if (!otpContainer || otpContainer.style.display === "none" || !enteredOtp) {
    await window.sendLoginOtpCodeDirectly();
    return;
  }

  if (errBlock) errBlock.classList.add("hidden");
  if (spinner) spinner.classList.remove("hidden");
  if (btnText) btnText.textContent = "Verifying...";

  try {
    const pendingOtp = sessionStorage.getItem("pending_login_otp");
    const pendingEmail = (sessionStorage.getItem("pending_login_email") || "").toLowerCase();

    // Verify passcode: check session match or Google Apps Script verify_login_otp
    let isCodeValid = Boolean(pendingOtp && pendingEmail && enteredOtp === pendingOtp && enteredEmail === pendingEmail);

    if (!isCodeValid && typeof GOOGLE_SCRIPT_URL !== 'undefined') {
      try {
        const verifyRes = await fetch(GOOGLE_SCRIPT_URL, {
          method: "POST",
          headers: { "Content-Type": "text/plain;charset=utf-8" },
          body: JSON.stringify({
            action: "verify_login_otp",
            email: enteredEmail,
            otp: enteredOtp,
            token: (typeof API_SECRET_TOKEN !== 'undefined' ? API_SECRET_TOKEN : '')
          })
        });
        const vData = await verifyRes.json();
        if (vData && (vData.ok || vData.verified)) {
          isCodeValid = true;
        }
      } catch (ve) {}
    }

    if (!isCodeValid) {
      if (errBlock) {
        errBlock.innerHTML = `
          <div style="font-weight: 700; color: #f43f5e; margin-bottom: 2px;">
            <i class="fa-solid fa-circle-xmark"></i> Invalid Passcode!
          </div>
          <div style="font-size: 11.5px; color: #cbd5e1;">The 6-digit email passcode entered is incorrect or expired.</div>
        `;
        errBlock.classList.remove("hidden");
      }
      if (otpField) {
        otpField.focus();
        otpField.select();
      }
      return;
    }

    // Role assignment & Permissions
    const usersList = (typeof window.getAuthorizedUsersList === 'function') ? window.getAuthorizedUsersList() : [];
    const matchedUser = isMainAdmin
      ? { email: window.AUTHORIZED_LOGIN_EMAIL, name: "Jagan Kandukuri (Main Admin)", role: "super_admin", status: "active", isMainAdmin: true }
      : usersList.find(u => (u.email || "").toLowerCase().trim() === enteredEmail);

    if (matchedUser && String(matchedUser.status).toLowerCase().trim() === "suspended") {
      if (errBlock) {
        errBlock.innerHTML = `
          <div style="background: rgba(239, 68, 68, 0.18); border: 1.5px solid #ef4444; border-radius: 10px; padding: 12px 14px; text-align: left;">
            <div style="font-weight: 800; color: #f43f5e; margin-bottom: 4px; font-size: 13px;">
              <i class="fa-solid fa-user-lock"></i> Account Suspended
            </div>
            <div style="font-size: 11.5px; color: #cbd5e1;">
              Your account (<strong style="color: #fca5a5;">${escapeHtml(enteredEmail)}</strong>) has been paused by the Main Administrator. Access is blocked.
            </div>
          </div>
        `;
        errBlock.classList.remove("hidden");
      }
      return;
    }

    const isAuthorized = isMainAdmin || (matchedUser && matchedUser.status === "active");

    let assignedRole = "viewer";
    let displayName = enteredEmail.split("@")[0] || "User";

    if (isAuthorized) {
      assignedRole = isMainAdmin ? "super_admin" : (matchedUser?.role || "admin");
      displayName = isMainAdmin ? "Jagan Kandukuri (Main Admin)" : (matchedUser?.name || enteredEmail.split("@")[0]);
    } else {
      let customerName = "";
      if (Array.isArray(window.invoices)) {
        const match = window.invoices.find(inv => {
          const b = inv.buyer || inv.details?.buyer || {};
          const be = (b.email || "").toLowerCase().trim();
          return (be && be === enteredEmail);
        });
        if (match) {
          const b = match.buyer || match.details?.buyer || {};
          customerName = b.name || b.tradeName || match.customerName || "Customer";
        }
      }
      assignedRole = customerName ? "customer" : "viewer";
      displayName = customerName || enteredEmail.split("@")[0] || "Guest Viewer";
    }

    // Set persistent & session state
    sessionStorage.setItem("current_user_email", enteredEmail);
    sessionStorage.setItem("current_user_name", displayName);
    sessionStorage.setItem("current_user_role", assignedRole);
    sessionStorage.setItem("is_demo_mode", assignedRole === "viewer" ? "true" : "false");
    localStorage.setItem("is_demo_mode", assignedRole === "viewer" ? "true" : "false");
    localStorage.setItem("authenticated_user_email", enteredEmail);
    localStorage.setItem("user_role", assignedRole);

    // Clear pending OTP
    sessionStorage.removeItem("pending_login_otp");
    sessionStorage.removeItem("pending_login_email");

    // Unlock application
    unlockSystemSilently(true);

    if (typeof window.applyRolePermissions === 'function') {
      window.applyRolePermissions(assignedRole);
    }

    if (assignedRole === "viewer") {
      if (typeof window.switchTab === 'function') window.switchTab('billing');
      showFloatingToast(`👁️ Logged in with Limited Read-Only Access. You can view GST Billing, Invoices & Products. Editing/actions are restricted.`, "info", 6500);
    } else {
      showFloatingToast(`👋 Welcome back, ${displayName}!`, "success", 4000);
    }

  } catch (err) {
    console.error("Mail login error:", err);
    if (errBlock) {
      errBlock.innerHTML = `
        <div style="font-weight: 700; color: #f43f5e; margin-bottom: 2px;">
          <i class="fa-solid fa-triangle-exclamation"></i> Login Error
        </div>
        <div style="font-size: 11.5px; color: #cbd5e1;">${escapeHtml(err.message || 'Could not complete login.')}</div>
      `;
      errBlock.classList.remove("hidden");
    }
  } finally {
    if (spinner) spinner.classList.add("hidden");
    if (btnText) btnText.textContent = "Sign In with Email";
  }
};


window.sendMailOtpToJagan = async function(mode = 'code') {
  const userField = document.getElementById("login-username") || document.getElementById("login-email");
  const rawEmail = (userField?.value || "").trim();
  const enteredEmail = rawEmail.toLowerCase();
  const errBlock = document.getElementById("login-error-message");

  // The server-side Script Properties allowlist is authoritative. Local storage
  // is editable by the browser owner and must never decide who receives an OTP.
  if (!enteredEmail) {
    if (errBlock) {
      errBlock.innerHTML = `
        <div style="font-weight: 700; color: #f43f5e; margin-bottom: 2px;">
          <i class="fa-solid fa-ban"></i> Access Denied: Unauthorized Email!
        </div>
        <div style="font-size: 11.5px; color: #cbd5e1;">
          Only authorized users can receive login codes. "${escapeHtml(rawEmail || 'empty')}" is not permitted to access this application.
        </div>
      `;
      errBlock.classList.remove("hidden");
    }
    const card = document.querySelector(".login-card");
    if (card) {
      card.classList.remove("shake-animation");
      void card.offsetWidth;
      card.classList.add("shake-animation");
    }
    return;
  }

  const isLinkMode = (mode === 'link');
  const actionDescription = isLinkMode ? "direct 1-click Gmail login link" : "6-digit security code";
  showFloatingToast(`⏳ Sending ${actionDescription} to ${enteredEmail}...`, "info", 4000);

  const otpField = document.getElementById("login-otp-code");
  if (otpField) {
    otpField.value = "";
    otpField.focus();
  }

  try {
    const res = await fetch(GOOGLE_SCRIPT_URL, {
      method: "POST",
      headers: { "Content-Type": "text/plain;charset=utf-8" },
      body: JSON.stringify({
        action: "send_login_otp",
        email: enteredEmail,
        otp: generatedCode,
        token: API_SECRET_TOKEN
      })
    });
    const data = await res.json();
    if (data && data.ok) {
      if (isLinkMode) {
        showFloatingToast(`📩 Direct login link sent to ${enteredEmail}! Open Gmail and click the link to unlock.`, "success", 7000);
      } else {
        showFloatingToast(`📩 6-Digit code sent to ${enteredEmail}! Check your inbox.`, "success", 6000);
      }
    } else {
      console.warn("GAS send_login_otp error:", data?.error);
      const errMsg = data?.error ? ` (${data.error})` : "";
      showFloatingToast(`⚠️ Email service unavailable${errMsg}. Click "Continue with Google" above for instant 1-click login!`, "warning", 8000);
    }
  } catch (err) {
    showFloatingToast("⚠️ Could not contact mail service. Click 'Continue with Google' above for instant 1-click login!", "warning", 7000);
  }
};

window.toggleLoginPasswordVisibility = function() {
  const passInput = document.getElementById("login-password");
  const icon = document.getElementById("toggle-login-pass-icon");
  if (!passInput) return;
  if (passInput.type === "password") {
    passInput.type = "text";
    if (icon) {
      icon.classList.remove("fa-eye");
      icon.classList.add("fa-eye-slash");
    }
  } else {
    passInput.type = "password";
    if (icon) {
      icon.classList.remove("fa-eye-slash");
      icon.classList.add("fa-eye");
    }
  }
};

window.toggleAlternateEmailInput = function() {
  const container = document.getElementById("login-alt-email-container");
  const toggleBtn = document.getElementById("btn-toggle-alt-email");
  if (!container) return;
  const isHidden = (container.style.display === "none" || !container.style.display);
  container.style.display = isHidden ? "block" : "none";
  if (toggleBtn) {
    toggleBtn.innerHTML = isHidden 
      ? '<i class="fa-solid fa-user-check"></i> Using Staff Email' 
      : '<i class="fa-solid fa-users"></i> Staff Sign-in';
  }
  if (isHidden) {
    const emailField = document.getElementById("login-email");
    if (emailField) {
      emailField.focus();
      emailField.select();
    }
  }
};

window.handleTraditionalLoginSubmit = async function(e) {
  if (e && e.preventDefault) e.preventDefault();
  
  const userField = document.getElementById("login-email");
  const rawEmail = (userField?.value || "").trim();
  const enteredEmail = rawEmail.toLowerCase();
  
  const passField = document.getElementById("login-password");
  const enteredPass = (passField?.value || "").trim();

  const btnText = document.getElementById("login-btn-text");
  const btnSpinner = document.getElementById("login-btn-spinner");
  const submitBtn = document.querySelector(".btn-login-submit");
  const errBlock = document.getElementById("login-error-message");

  // Check rate limit lockout first
  const currentLock = AppSecurity.isLockedOut();
  if (currentLock.locked) {
    AppSecurity.startLockoutCountdown(submitBtn, errBlock);
    return;
  }

  const mainAdminNorm = (window.AUTHORIZED_LOGIN_EMAIL || "kandukurijagan99@gmail.com").toLowerCase().trim();
  const isMainAdmin = (enteredEmail === mainAdminNorm);

  // STRICT BLOCK FOR SUSPENDED ACCOUNTS
  if (!isMainAdmin && enteredEmail && typeof window.isUserSuspendedByAdmin === 'function' && window.isUserSuspendedByAdmin(enteredEmail)) {
    if (submitBtn) submitBtn.disabled = false;
    if (btnText) btnText.classList.remove("hidden");
    if (btnSpinner) btnSpinner.classList.add("hidden");
    if (errBlock) {
      errBlock.innerHTML = `
        <div style="background: rgba(239, 68, 68, 0.18); border: 1.5px solid #ef4444; border-radius: 10px; padding: 12px 14px; text-align: left;">
          <div style="font-weight: 800; color: #f43f5e; margin-bottom: 4px; font-size: 13px;">
            <i class="fa-solid fa-user-lock"></i> Account Suspended
          </div>
          <div style="font-size: 11.5px; color: #cbd5e1;">
            Your account (<strong style="color: #fca5a5;">${escapeHtml(enteredEmail)}</strong>) has been paused by the Main Administrator. Access is blocked.
          </div>
        </div>
      `;
      errBlock.classList.remove("hidden");
    }
    showFloatingToast(`⛔ Account ${enteredEmail} is suspended by Main Admin.`, "error", 6000);
    return;
  }

  const customPin = String(globalSettings?.security?.securityPin || globalSettings?.security?.pin || "").trim();
  const sysPin = customPin || "2024";
  const sysPass = String(globalSettings?.security?.password || (customPin ? "" : "Aaryan@2024")).trim();

  // MASTER PIN QUICK-UNLOCK: If user typed master PIN in either input
  const isDirectMasterPin = (enteredEmail === sysPin || enteredPass === sysPin || enteredPass === "2024" || enteredEmail === "2024");
  const isStandalonePin = isDirectMasterPin && (!enteredEmail || enteredEmail === sysPin || enteredEmail === "2024" || !enteredPass || enteredPass === sysPin || enteredPass === "2024" || enteredEmail === mainAdminNorm);

  if (!isStandalonePin) {
    // 1. Check Email required if not entering direct PIN
    if (!enteredEmail) {
      if (errBlock) {
        errBlock.innerHTML = `
          <div style="font-weight: 700; color: #f43f5e; margin-bottom: 2px;">
            <i class="fa-solid fa-triangle-exclamation"></i> Email or PIN Required!
          </div>
          <div style="font-size: 11.5px; color: #cbd5e1;">
            Please enter your authorized email address or Master PIN (2024).
          </div>
        `;
        errBlock.classList.remove("hidden");
      }
      const card = document.querySelector(".login-card");
      if (card) {
        card.classList.remove("shake-animation");
        void card.offsetWidth;
        card.classList.add("shake-animation");
      }
      if (userField) userField.focus();
      return;
    }

    // 2. Password or code required
    if (!enteredPass && enteredEmail !== "2024" && enteredEmail !== sysPin) {
      if (errBlock) {
        errBlock.innerHTML = `
          <div style="font-weight: 700; color: #f59e0b; margin-bottom: 2px;">
            <i class="fa-solid fa-key"></i> Password or PIN Required!
          </div>
          <div style="font-size: 11.5px; color: #cbd5e1; line-height: 1.4;">
            Please enter your assigned password or security PIN.
          </div>
        `;
        errBlock.classList.remove("hidden");
      }
      const card = document.querySelector(".login-card");
      if (card) {
        card.classList.remove("shake-animation");
        void card.offsetWidth;
        card.classList.add("shake-animation");
      }
      if (passField) passField.focus();
      return;
    }
  }

  if (submitBtn) submitBtn.disabled = true;
  if (btnText) btnText.classList.add("hidden");
  if (btnSpinner) btnSpinner.classList.remove("hidden");

  let isOtpValid = false;
  let verifiedRole = "admin";
  let matchedUser = null;

  const checkUserPassword = (u, pass) => {
    if (!u) return false;
    const pStr = String(pass).trim();
    if (u.password && String(u.password).trim() === pStr) return true;
    if (u.pin && String(u.pin).trim() === pStr) return true;
    if (u.otp && String(u.otp).trim() === pStr) return true;
    return false;
  };

  // Step 0.5: Check Pending Session Mail OTP Code
  const pendingOtp = sessionStorage.getItem("pending_login_otp");
  const pendingEmail = (sessionStorage.getItem("pending_login_email") || "").toLowerCase().trim();
  if (pendingOtp && enteredPass === pendingOtp && (!pendingEmail || pendingEmail === enteredEmail)) {
    if (!isMainAdmin && typeof window.isUserSuspendedByAdmin === 'function' && window.isUserSuspendedByAdmin(enteredEmail)) {
      if (submitBtn) submitBtn.disabled = false;
      if (btnText) btnText.classList.remove("hidden");
      if (btnSpinner) btnSpinner.classList.add("hidden");
      if (errBlock) {
        errBlock.innerHTML = `
          <div style="background: rgba(239, 68, 68, 0.18); border: 1.5px solid #ef4444; border-radius: 10px; padding: 12px 14px; text-align: left;">
            <div style="font-weight: 800; color: #f43f5e; margin-bottom: 4px; font-size: 13px;">
              <i class="fa-solid fa-user-lock"></i> Account Suspended
            </div>
            <div style="font-size: 11.5px; color: #cbd5e1;">
              Your account (<strong style="color: #fca5a5;">${escapeHtml(enteredEmail)}</strong>) has been paused by the Main Administrator. Access is blocked.
            </div>
          </div>
        `;
        errBlock.classList.remove("hidden");
      }
      return;
    }
    isOtpValid = true;
    sessionStorage.removeItem("pending_login_otp");
    sessionStorage.removeItem("pending_login_email");
    if (isMainAdmin) {
      verifiedRole = "super_admin";
      matchedUser = { email: window.AUTHORIZED_LOGIN_EMAIL, name: "Jagan Kandukuri (Main Admin)", role: "super_admin", status: "active", isMainAdmin: true };
    } else {
      let uRec = (typeof window.getAuthorizedUsersList === 'function') ? window.getAuthorizedUsersList().find(u => (u.email || "").toLowerCase().trim() === enteredEmail) : null;
      verifiedRole = uRec?.role || "admin";
      matchedUser = {
        email: enteredEmail,
        name: uRec?.name || enteredEmail.split("@")[0],
        role: verifiedRole,
        status: "active"
      };
    }
  }

  // Step 1: Check Main Admin credentials or Master PIN
  if (!isOtpValid && (isMainAdmin || isDirectMasterPin)) {
    const validSysPass = Boolean(sysPass && sysPass.length >= 4);
    const validSysPin = Boolean(sysPin && sysPin.length >= 4);
    if ((validSysPass && enteredPass === sysPass) || (validSysPin && enteredPass === sysPin) || enteredPass === "2024" || enteredPass === sysPin || enteredEmail === "2024" || enteredEmail === sysPin) {
      isOtpValid = true;
      verifiedRole = "super_admin";
      matchedUser = { email: window.AUTHORIZED_LOGIN_EMAIL || "kandukurijagan99@gmail.com", name: "Jagan Kandukuri (Main Admin)", role: "super_admin", status: "active", isMainAdmin: true };
    }
  }

  // Step 2: Check Local & Bundled Authorized Users List
  if (!isOtpValid) {
    let usersList = window.getAuthorizedUsersList();
    matchedUser = usersList.find(u => (u.email || "").toLowerCase().trim() === enteredEmail);
    if (matchedUser) {
      if (matchedUser.status === "suspended") {
        if (submitBtn) submitBtn.disabled = false;
        if (btnText) btnText.classList.remove("hidden");
        if (btnSpinner) btnSpinner.classList.add("hidden");
        if (errBlock) {
          errBlock.innerHTML = `
            <div style="background: rgba(239, 68, 68, 0.18); border: 1.5px solid #ef4444; border-radius: 10px; padding: 12px; text-align: left;">
              <div style="font-weight: 800; color: #f43f5e; margin-bottom: 4px; font-size: 13px;">
                <i class="fa-solid fa-user-lock"></i> Account Suspended
              </div>
              <div style="font-size: 11.5px; color: #cbd5e1;">
                Your account (<strong style="color: #fca5a5;">${escapeHtml(enteredEmail)}</strong>) has been paused by the Main Admin.
              </div>
            </div>
          `;
          errBlock.classList.remove("hidden");
        }
        return;
      }

      if (checkUserPassword(matchedUser, enteredPass)) {
        isOtpValid = true;
        verifiedRole = matchedUser.role || "cashier";
      }
    }
  }

  // Step 2.9: If not validated yet, fetch fresh settings from Supabase DB immediately
  if (!isOtpValid && window.SupabaseDB && typeof window.SupabaseDB.fetchSettings === 'function') {
    try {
      const sbRes = await window.SupabaseDB.fetchSettings();
      if (sbRes && sbRes.ok && sbRes.settings) {
        const cloudSett = sbRes.settings;
        const authList = cloudSett.authorizedUsers || cloudSett.authorized_users;
        if (Array.isArray(authList)) {
          if (typeof globalSettings !== 'undefined') {
            globalSettings = Object.assign({}, globalSettings, cloudSett);
            try { localStorage.setItem("settings", JSON.stringify(globalSettings)); } catch(_) {}
          }
          window.saveAuthorizedUsersList(authList, true);
          const freshList = window.getAuthorizedUsersList();
          matchedUser = freshList.find(u => (u.email || "").toLowerCase().trim() === enteredEmail);
          if (matchedUser) {
            if (matchedUser.status === "suspended") {
              if (submitBtn) submitBtn.disabled = false;
              if (btnText) btnText.classList.remove("hidden");
              if (btnSpinner) btnSpinner.classList.add("hidden");
              if (errBlock) {
                errBlock.innerHTML = `
                  <div style="background: rgba(239, 68, 68, 0.18); border: 1.5px solid #ef4444; border-radius: 10px; padding: 12px; text-align: left;">
                    <div style="font-weight: 800; color: #f43f5e; margin-bottom: 4px; font-size: 13px;">
                      <i class="fa-solid fa-user-lock"></i> Account Suspended
                    </div>
                    <div style="font-size: 11.5px; color: #cbd5e1;">
                      Your account (<strong style="color: #fca5a5;">${escapeHtml(enteredEmail)}</strong>) has been paused by the Main Admin.
                    </div>
                  </div>
                `;
                errBlock.classList.remove("hidden");
              }
              return;
            }
            if (checkUserPassword(matchedUser, enteredPass) || enteredPass === sysPin || enteredPass === "2024") {
              isOtpValid = true;
              verifiedRole = matchedUser.role || "admin";
            }
          }
        }
      }
    } catch(sbErr) {
      console.warn("[Supabase] Cloud credentials check:", sbErr);
    }
  }

  // Step 3: If not validated yet, fetch fresh settings from Google Cloud (in case admin added user on another device)
  if (!isOtpValid && typeof GOOGLE_SCRIPT_URL !== 'undefined') {
    try {
      const syncUrl = `${GOOGLE_SCRIPT_URL}?action=sync&auth=${encodeURIComponent(API_SECRET_TOKEN || '')}&token=${encodeURIComponent(API_SECRET_TOKEN || '')}&_t=${Date.now()}`;
      const res = await fetch(syncUrl, { redirect: 'follow', cache: 'no-store' });
      if (res.ok) {
        const data = await res.json();
        const cloudSettings = data ? (data.settings || data.globalSettings) : null;
        if (cloudSettings && typeof cloudSettings === 'object') {
          const authList = cloudSettings.authorizedUsers || cloudSettings.authorized_users;
          if (authList && Array.isArray(authList)) {
            window.saveAuthorizedUsersList(authList, true);
            const freshList = window.getAuthorizedUsersList();
            matchedUser = freshList.find(u => (u.email || "").toLowerCase().trim() === enteredEmail);
            if (matchedUser && matchedUser.status === "active") {
              if (checkUserPassword(matchedUser, enteredPass) || enteredPass === sysPin || enteredPass === "2024") {
                isOtpValid = true;
                verifiedRole = matchedUser.role || "admin";
              }
            }
          }
        }
      }
    } catch (e) {
      console.warn("Cloud credentials verification check:", e);
    }
  }

  // Step 4: Fallback to Google Apps Script verify_login_otp if email OTP code was requested
  if (!isOtpValid && typeof GOOGLE_SCRIPT_URL !== 'undefined') {
    try {
      const res = await fetch(GOOGLE_SCRIPT_URL, {
        method: "POST",
        headers: { "Content-Type": "text/plain;charset=utf-8" },
        body: JSON.stringify({
          action: "verify_login_otp",
          email: enteredEmail,
          otp: enteredPass,
          token: API_SECRET_TOKEN
        })
      });
      const data = await res.json();
      if (data && (data.ok || data.verified)) {
        isOtpValid = true;
        verifiedRole = data.role || verifiedRole;
      }
    } catch (_) {}
  }

  // If still not valid:
  if (!isOtpValid) {
    if (submitBtn) submitBtn.disabled = false;
    if (btnText) btnText.classList.remove("hidden");
    if (btnSpinner) btnSpinner.classList.add("hidden");

    const isKnownAuthorized = window.isUserAuthorizedByAdmin(enteredEmail);
    if (isKnownAuthorized) {
      if (errBlock) {
        errBlock.innerHTML = `
          <div style="font-weight: 700; color: #f43f5e; margin-bottom: 2px;">
            <i class="fa-solid fa-triangle-exclamation"></i> Incorrect Password!
          </div>
          <div style="font-size: 11.5px; color: #cbd5e1;">
            The password entered for <strong style="color: #fca5a5;">${escapeHtml(enteredEmail)}</strong> is incorrect.
          </div>
        `;
        errBlock.classList.remove("hidden");
      }
    } else {
      // Unregistered user -> offer 1-click Free View Mode
      if (errBlock) {
        errBlock.innerHTML = `
          <div style="background: rgba(14, 165, 233, 0.15); border: 1.5px solid #0ea5e9; border-radius: 10px; padding: 12px; margin-bottom: 6px; text-align: left;">
            <div style="font-weight: 800; color: #38bdf8; margin-bottom: 4px; font-size: 13px; display: flex; align-items: center; gap: 6px;">
              <i class="fa-solid fa-circle-info"></i> Unregistered User Account
            </div>
            <div style="font-size: 11.5px; color: #e2e8f0; line-height: 1.4; margin-bottom: 10px;">
              <strong>${escapeHtml(enteredEmail)}</strong> has not been given edit access by the owner. You can explore the full software in <strong>Free View Mode</strong>:
            </div>
            <button type="button" onclick="window.loginAsFreeViewer({ email: '${escapeHtml(enteredEmail)}' })" style="width: 100%; padding: 9px; background: linear-gradient(135deg, #0ea5e9, #0284c7); color: #fff; border: none; border-radius: 7px; font-weight: 700; font-size: 12.5px; cursor: pointer; display: flex; align-items: center; justify-content: center; gap: 6px; box-shadow: 0 2px 8px rgba(14, 165, 233, 0.3);">
              <i class="fa-solid fa-eye"></i> Open in Free View Mode (Demo)
            </button>
          </div>
        `;
        errBlock.classList.remove("hidden");
      }
    }
    if (passField) {
      passField.value = "";
      passField.focus();
    }
    const card = document.querySelector(".login-card");
    if (card) {
      card.classList.remove("shake-animation");
      void card.offsetWidth;
      card.classList.add("shake-animation");
    }
    return;
  }

  // VERIFIED! UNLOCK SYSTEM WITH ASSIGNED ROLE
  if (errBlock) errBlock.classList.add("hidden");

  const effectiveEmail = (matchedUser && matchedUser.email) ? matchedUser.email : (isMainAdmin ? window.AUTHORIZED_LOGIN_EMAIL : (enteredEmail || window.AUTHORIZED_LOGIN_EMAIL));
  AppSecurity.recordSuccessfulLogin(effectiveEmail, "Password/PIN Authentication");

  const finalRole = matchedUser ? matchedUser.role : (isMainAdmin ? "super_admin" : verifiedRole);
  const finalName = matchedUser ? matchedUser.name : (isMainAdmin ? "Jagan Kandukuri (Main Admin)" : effectiveEmail.split("@")[0]);

  // Remove demo mode flags so full edit access is active!
  sessionStorage.removeItem("is_demo_mode");
  localStorage.removeItem("is_demo_mode");
  sessionStorage.setItem("is_demo_mode", "false");
  localStorage.setItem("is_demo_mode", "false");

  sessionStorage.setItem("session_authenticated", "true");
  sessionStorage.setItem("current_user_email", effectiveEmail);
  sessionStorage.setItem("current_user_name", finalName);
  sessionStorage.setItem("current_user_role", finalRole);
  sessionStorage.setItem("is_main_admin", (isMainAdmin || finalRole === 'super_admin') ? "true" : "false");
  sessionStorage.setItem("manual_locked", "false");
  sessionStorage.setItem("session_last_active_time", Date.now().toString());

  if (typeof window.savePersistentAuthSession === 'function') {
    window.savePersistentAuthSession({
      email: effectiveEmail,
      name: finalName,
      role: finalRole,
      isMainAdmin: (isMainAdmin || finalRole === 'super_admin')
    });
  }

  if (typeof window.updateUserLastLogin === 'function') {
    window.updateUserLastLogin(effectiveEmail);
  }

  unlockSystemSilently(true);

  if (typeof window.applyRolePermissions === 'function') {
    window.applyRolePermissions(finalRole);
  }

  const demoTopBanner = document.getElementById("demo-mode-top-banner");
  if (demoTopBanner) demoTopBanner.style.display = "none";

  if (typeof showFloatingToast === 'function') {
    showFloatingToast(`🔓 Welcome back, ${finalName}! Full Edit Access verified.`, "success", 4000);
  }

  if (submitBtn) submitBtn.disabled = false;
  if (btnText) btnText.classList.remove("hidden");
  if (btnSpinner) btnSpinner.classList.add("hidden");
};

