// 3. Import and restore complete store database from Master Excel (.xlsx)
window.importDataFromMasterExcel = async function(event) {
  if (typeof window.isViewOnlyUser === 'function' && window.isViewOnlyUser()) {
    if (typeof window.showProductBuyModal === 'function') {
      window.showProductBuyModal("To import Excel backups, please upgrade to a Commercial License.");
    }
    return;
  }

  const file = event.target?.files?.[0];
  if (!file) return;

  if (typeof XLSX === 'undefined') {
    showFloatingToast("⚠️ Excel library is loading. Please check internet connection.", "warning", 4000);
    return;
  }

  showFloatingToast("⏳ Reading and parsing Master Excel Workbook...", "info", 3000);

  // Helper: Safe number parsing from Excel cells
  function safeParseExcelNumber(val, defaultVal = 0) {
    if (val === null || val === undefined || val === '') return defaultVal;
    if (typeof val === 'number') return isNaN(val) ? defaultVal : val;
    const cleaned = String(val).replace(/[₹$,\s]/g, '').trim();
    const num = parseFloat(cleaned);
    return isNaN(num) ? defaultVal : num;
  }

  // Helper: Safe date parsing from Excel cells (supports Date objects, serials, ISO strings)
  function formatExcelDate(val) {
    if (!val) return new Date().toISOString().split('T')[0];
    if (val instanceof Date) {
      return val.toISOString().split('T')[0];
    }
    if (typeof val === 'number') {
      if (val > 10000 && val < 60000) {
        const utc_days = Math.floor(val - 25569);
        const utc_value = utc_days * 86400;
        const date_info = new Date(utc_value * 1000);
        return date_info.toISOString().split('T')[0];
      }
    }
    const str = String(val).trim();
    if (/^\d{4}-\d{2}-\d{2}/.test(str)) return str.substring(0, 10);
    if (/^\d{1,2}[-\/]\d{1,2}[-\/]\d{4}/.test(str)) {
      const parts = str.split(/[-\/]/);
      if (parts[2].length === 4) {
        const d = parts[0].padStart(2, '0');
        const m = parts[1].padStart(2, '0');
        const y = parts[2];
        return `${y}-${m}-${d}`;
      }
    }
    const d = new Date(str);
    if (!isNaN(d.getTime())) return d.toISOString().split('T')[0];
    return new Date().toISOString().split('T')[0];
  }

  const reader = new FileReader();
  reader.onload = async function(e) {
    try {
      const data = new Uint8Array(e.target.result);
      const workbook = XLSX.read(data, { type: 'array', cellDates: true });
      const sheetNames = workbook.SheetNames || [];

      // 1. Smart Sheet Resolver: checks sheet name keyword first; if not found, inspects header row!
      function findSheetByHeaderOrName(nameKeywords, headerKeywords) {
        for (let i = 0; i < sheetNames.length; i++) {
          const sName = sheetNames[i].toLowerCase();
          if (nameKeywords.some(kw => sName.includes(kw))) {
            return sheetNames[i];
          }
        }
        for (let i = 0; i < sheetNames.length; i++) {
          try {
            const sheet = workbook.Sheets[sheetNames[i]];
            if (!sheet) continue;
            const rows = XLSX.utils.sheet_to_json(sheet, { header: 1, range: 0, defval: "" });
            if (rows && rows.length > 0) {
              const headerRow = (rows[0] || []).map(c => String(c).toLowerCase().trim());
              const matchCount = headerKeywords.filter(kw => headerRow.some(h => h.includes(kw))).length;
              if (matchCount >= 2 || (headerKeywords.length === 1 && matchCount === 1)) {
                return sheetNames[i];
              }
            }
          } catch(e) {}
        }
        return null;
      }

      const prodSheetName = findSheetByHeaderOrName(
        ["stock", "product", "inventory"],
        ["selling price", "cost rate", "hsn code", "stock quantity", "description"]
      );

      const custSheetName = findSheetByHeaderOrName(
        ["customer", "part", "client", "buyer"],
        ["customer / business name", "customer id", "billing address", "customer type", "state code"]
      );

      const itemsSheetName = findSheetByHeaderOrName(
        ["line", "item"],
        ["item description", "total item amount", "taxable value", "pack size"]
      );

      const paySheetName = findSheetByHeaderOrName(
        ["payment", "ledger", "installment"],
        ["installment no", "payment date", "remaining balance", "payment mode"]
      );

      const invSheetName = findSheetByHeaderOrName(
        ["invoices_summary", "invoice_master", "bills", "sales"],
        ["invoice number", "taxable subtotal", "document type", "grand total", "round off"]
      ) || (sheetNames.find(s => s.toLowerCase().includes("invoice") && !s.toLowerCase().includes("item")));

      // Single-sheet multi-table support (e.g. CSV or stacked Excel sheet)
      let singleSheetProds = [];
      let singleSheetCusts = [];
      let singleSheetInvs = [];
      let singleSheetItems = [];
      let singleSheetPays = [];

      if (sheetNames.length === 1 && (!prodSheetName && !custSheetName && !invSheetName)) {
        try {
          const sheet = workbook.Sheets[sheetNames[0]];
          const rawGrid = XLSX.utils.sheet_to_json(sheet, { header: 1, defval: "" });
          let curSection = null;
          let curHeaders = [];

          for (let r = 0; r < rawGrid.length; r++) {
            const row = rawGrid[r];
            if (!row || row.length === 0 || row.every(c => String(c).trim() === "")) continue;
            const rowStr = row.map(c => String(c).toLowerCase().trim()).join(" , ");

            if (rowStr.includes("description") && (rowStr.includes("selling price") || rowStr.includes("stock") || rowStr.includes("product id"))) {
              curSection = "products";
              curHeaders = row.map(c => String(c).trim());
              continue;
            }
            if ((rowStr.includes("customer / business name") || rowStr.includes("customer name")) && (rowStr.includes("customer id") || rowStr.includes("billing address") || rowStr.includes("phone"))) {
              curSection = "customers";
              curHeaders = row.map(c => String(c).trim());
              continue;
            }
            if (rowStr.includes("invoice number") && (rowStr.includes("document type") || rowStr.includes("taxable subtotal") || rowStr.includes("grand total"))) {
              curSection = "invoices";
              curHeaders = row.map(c => String(c).trim());
              continue;
            }
            if (rowStr.includes("invoice number") && (rowStr.includes("item description") || rowStr.includes("pack size") || rowStr.includes("total item amount"))) {
              curSection = "items";
              curHeaders = row.map(c => String(c).trim());
              continue;
            }
            if (rowStr.includes("installment no") || (rowStr.includes("invoice number") && rowStr.includes("amount paid") && rowStr.includes("payment mode"))) {
              curSection = "payments";
              curHeaders = row.map(c => String(c).trim());
              continue;
            }

            if (curSection && curHeaders.length > 0) {
              const rowObj = {};
              curHeaders.forEach((h, colIdx) => {
                if (h) rowObj[h] = row[colIdx];
              });
              if (curSection === "products") singleSheetProds.push(rowObj);
              else if (curSection === "customers") singleSheetCusts.push(rowObj);
              else if (curSection === "invoices") singleSheetInvs.push(rowObj);
              else if (curSection === "items") singleSheetItems.push(rowObj);
              else if (curSection === "payments") singleSheetPays.push(rowObj);
            }
          }
        } catch (singleErr) {
          console.warn("Single-sheet multi-table parse note:", singleErr);
        }
      }

      // A. Parse Products & Stock Master
      let importedProducts = [];
      const rawProds = prodSheetName ? XLSX.utils.sheet_to_json(workbook.Sheets[prodSheetName]) : singleSheetProds;
      if (rawProds && rawProds.length > 0) {
        importedProducts = rawProds.map((row, idx) => {
          const desc = String(row["Description / Product Name"] || row["Description"] || row["Product Name"] || row["Item Name"] || row["description"] || "").trim();
          if (!desc) return null;
          const qty = safeParseExcelNumber(row["Current Stock Quantity"] || row["Stock Quantity"] || row["Stock"] || row["stock"] || 0);
          const prc = safeParseExcelNumber(row["Selling Price (₹)"] || row["Price"] || row["price"] || row["Selling Price"] || 0);
          const rate = safeParseExcelNumber(row["Cost Rate (₹)"] || row["Cost"] || row["Rate"] || row["rate"] || prc);
          const disc = safeParseExcelNumber(row["Default Discount %"] || row["Discount %"] || row["discount"] || 0);
          const hsn = String(row["HSN Code"] || row["HSN"] || row["hsn"] || "230990");
          const unit = String(row["Unit"] || row["unit"] || "NOS");
          const pack = String(row["Pack Size"] || row["packSize"] || "");
          const id = String(row["Product ID"] || row["ID"] || row["id"] || `PRD-${Date.now()}-${idx}`);
          const barcode = String(row["Barcode"] || row["barcode"] || "");
          const totVal = safeParseExcelNumber(row["Total Stock Valuation (₹)"] || row["Total Value"] || (qty * prc));
          return {
            id,
            description: desc,
            hsn,
            packSize: pack,
            unit,
            rate,
            discount: disc,
            price: prc,
            stock: qty,
            totalValue: totVal,
            status: qty > 10 ? "In Stock" : (qty > 0 ? "Low Stock" : "Out of Stock"),
            barcode,
            is_deleted: false,
            updatedAt: new Date().toISOString()
          };
        }).filter(Boolean);
      }

      // B. Parse Customer Directory
      let importedParties = [];
      const rawCusts = custSheetName ? XLSX.utils.sheet_to_json(workbook.Sheets[custSheetName]) : singleSheetCusts;
      if (rawCusts && rawCusts.length > 0) {
        importedParties = rawCusts.map((row, idx) => {
          const name = String(row["Customer / Business Name"] || row["Customer Name"] || row["Name"] || row["name"] || "").trim();
          if (!name) return null;
          const rawType = String(row["Customer Type"] || row["type"] || "receiver").trim().toLowerCase();
          const pType = (rawType === 'consignee' || rawType.includes('consignee')) ? 'consignee' : 'receiver';
          return {
            id: String(row["Customer ID"] || row["ID"] || row["id"] || `party-${Date.now()}-${idx}`),
            name,
            phone: String(row["Phone Number"] || row["Phone"] || row["phone"] || "").trim(),
            email: String(row["Email Address"] || row["Email"] || row["email"] || "").trim(),
            gstin: String(row["GSTIN"] || row["gstin"] || "").trim(),
            address: String(row["Billing Address"] || row["Address"] || row["address"] || "").trim(),
            city: String(row["City"] || row["city"] || "").trim(),
            state: String(row["State"] || row["state"] || "Andhra Pradesh").trim(),
            stateCode: String(row["State Code"] || row["stateCode"] || "37").trim(),
            type: pType,
            company: String(row["Customer / Business Name"] || name),
            is_deleted: false,
            updatedAt: new Date().toISOString()
          };
        }).filter(Boolean);
      }

      // C. Parse Invoice Line Items
      const itemsByInvoiceNo = new Map();
      const rawItems = itemsSheetName ? XLSX.utils.sheet_to_json(workbook.Sheets[itemsSheetName]) : singleSheetItems;
      if (rawItems && rawItems.length > 0) {
        rawItems.forEach(row => {
          const rawInvNo = String(row["Invoice Number"] || row["Invoice No"] || row["Invoice #"] || row["invoiceNo"] || "").trim();
          if (!rawInvNo) return;
          const cleanInvNo = rawInvNo.replace(/^#/, '');
          const itemObj = {
            productId: String(row["Product ID"] || `PRD-${Date.now()}`),
            description: String(row["Item Description"] || row["Description"] || "Product Item"),
            hsn: String(row["HSN Code"] || row["HSN"] || "230990"),
            packSize: String(row["Pack Size"] || ""),
            unit: String(row["Unit"] || "NOS"),
            quantity: safeParseExcelNumber(row["Quantity"] || row["Qty"] || 1),
            rate: safeParseExcelNumber(row["Rate (₹)"] || row["Rate"] || 0),
            discount: safeParseExcelNumber(row["Discount %"] || 0),
            taxableValue: safeParseExcelNumber(row["Taxable Value (₹)"] || 0),
            taxRate: safeParseExcelNumber(row["GST Rate %"] || 0),
            amount: safeParseExcelNumber(row["Total Item Amount (₹)"] || row["Amount"] || 0)
          };
          [rawInvNo, cleanInvNo, cleanInvNo.toLowerCase(), rawInvNo.toLowerCase()].forEach(k => {
            if (k) {
              if (!itemsByInvoiceNo.has(k)) itemsByInvoiceNo.set(k, []);
              itemsByInvoiceNo.get(k).push(itemObj);
            }
          });
        });
      }

      // D. Parse Payment Ledger History
      const paymentsByInvoiceNo = new Map();
      const rawPay = paySheetName ? XLSX.utils.sheet_to_json(workbook.Sheets[paySheetName]) : singleSheetPays;
      if (rawPay && rawPay.length > 0) {
        rawPay.forEach(row => {
          const rawInvNo = String(row["Invoice Number"] || row["Invoice No"] || row["Invoice #"] || row["invoiceNo"] || "").trim();
          if (!rawInvNo) return;
          const cleanInvNo = rawInvNo.replace(/^#/, '');
          const payDate = formatExcelDate(row["Payment Date & Time"] || row["Payment Date"] || row["Date"] || new Date().toISOString());
          const payObj = {
            id: `pay_${Date.now()}_${Math.floor(Math.random() * 1000)}`,
            installmentNo: safeParseExcelNumber(row["Installment No"] || 1),
            date: payDate,
            amount: safeParseExcelNumber(row["Amount Paid (₹)"] || row["Amount Paid"] || row["Amount"] || 0),
            mode: String(row["Payment Mode"] || row["Mode"] || "UPI / Online"),
            reference: String(row["Reference / UTR No"] || row["Reference"] || row["UTR"] || ""),
            note: String(row["Payment Note"] || row["Notes"] || "Installment payment"),
            balanceAfter: safeParseExcelNumber(row["Remaining Balance After (₹)"] || 0)
          };
          [rawInvNo, cleanInvNo, cleanInvNo.toLowerCase(), rawInvNo.toLowerCase()].forEach(k => {
            if (k) {
              if (!paymentsByInvoiceNo.has(k)) paymentsByInvoiceNo.set(k, []);
              paymentsByInvoiceNo.get(k).push(payObj);
            }
          });
        });
      }

      // E. Parse Invoices Summary
      let importedInvoices = [];
      const rawInvs = invSheetName ? XLSX.utils.sheet_to_json(workbook.Sheets[invSheetName]) : singleSheetInvs;
      if (rawInvs && rawInvs.length > 0) {
        importedInvoices = rawInvs.map((row, idx) => {
          const rawInvNo = String(row["Invoice Number"] || row["Invoice No"] || row["Invoice #"] || row["invoiceNo"] || `INV-${Date.now()}-${idx}`).trim();
          const cleanInvNo = rawInvNo.replace(/^#/, '');
          const invDate = formatExcelDate(row["Invoice Date"] || row["Date"]);
          const custName = String(row["Customer Name"] || row["Customer"] || "Cash Customer").trim();
          const custPhone = String(row["Customer Phone"] || row["Phone"] || "").trim();
          const gstin = String(row["Customer GSTIN"] || row["GSTIN"] || "").trim();
          const docType = String(row["Document Type"] || (cleanInvNo.startsWith("EST-") ? "Bill of Supply" : "Tax Invoice")).trim();
          const isEstimate = Boolean(cleanInvNo.startsWith("EST-") || docType.toLowerCase().includes("estimate") || docType.toLowerCase().includes("quotation"));

          const gTotal = safeParseExcelNumber(row["Grand Total (₹)"] || row["Grand Total"] || row["Total"] || 0);
          const paid = safeParseExcelNumber(row["Amount Paid on Invoice Date (₹)"] || row["Amount Paid"] || row["Paid"] || 0);
          const bal = safeParseExcelNumber(row["Balance Due (₹)"] || row["Balance"] || Math.max(0, gTotal - paid));
          const subtotal = safeParseExcelNumber(row["Taxable Subtotal (₹)"] || row["Subtotal"] || gTotal);
          const cgst = safeParseExcelNumber(row["CGST Amount (₹)"] || row["CGST"] || 0);
          const sgst = safeParseExcelNumber(row["SGST Amount (₹)"] || row["SGST"] || 0);
          const igst = safeParseExcelNumber(row["IGST Amount (₹)"] || row["IGST"] || 0);
          const roundOff = safeParseExcelNumber(row["Round Off (₹)"] || row["Round Off"] || 0);
          const status = String(row["Payment Status"] || (bal <= 0.01 ? "Paid" : (paid > 0 ? "Partial" : "Credit")));
          const mode = String(row["Payment Mode"] || "UPI / Online");
          const lastPay = formatExcelDate(row["Last Payment Date"] || invDate);

          const items = itemsByInvoiceNo.get(cleanInvNo) || itemsByInvoiceNo.get(rawInvNo) || itemsByInvoiceNo.get(cleanInvNo.toLowerCase()) || [
            {
              productId: "PRD-EXCEL-01",
              description: "Items per Excel Master",
              quantity: 1,
              unit: "NOS",
              rate: subtotal,
              amount: subtotal
            }
          ];

          const paymentHistory = paymentsByInvoiceNo.get(cleanInvNo) || paymentsByInvoiceNo.get(rawInvNo) || paymentsByInvoiceNo.get(cleanInvNo.toLowerCase()) || (paid > 0 ? [{
            id: `pay_${Date.now()}_${idx}`,
            installmentNo: 1,
            date: invDate,
            amount: paid,
            mode: mode,
            reference: "Upfront Bill Settlement",
            note: "Initial settlement",
            balanceAfter: bal
          }] : []);

          const uniqueId = String(row["id"] || row["ID"] || (cleanInvNo.startsWith("inv_") ? cleanInvNo : `inv_${Date.now()}_${idx}`));
          const randSuffix = Math.random().toString(36).substring(2, 6).toUpperCase();
          const qrToken = `Q-${cleanInvNo}-${Date.now().toString(36).slice(-4).toUpperCase()}${randSuffix}`;
          const invTs = new Date(invDate).getTime() || Date.now();

          return {
            id: uniqueId,
            qrToken: qrToken,
            invoiceNo: cleanInvNo,
            invoiceDate: invDate,
            date: invDate,
            customerName: custName,
            customerPhone: custPhone,
            phone: custPhone,
            buyer: {
              name: custName,
              phone: custPhone,
              gstin: gstin
            },
            consignee: {
              name: custName,
              phone: custPhone,
              gstin: gstin
            },
            items: items,
            itemsCount: items.length,
            taxable: subtotal,
            subtotal: subtotal,
            cgst: cgst,
            sgst: sgst,
            igst: igst,
            taxAmount: cgst + sgst + igst,
            roundOff: roundOff,
            total: gTotal,
            grandTotal: gTotal,
            totalAmount: gTotal,
            paidAmount: paid,
            balanceDue: bal,
            balanceAmount: bal,
            paymentStatus: status,
            paymentMode: mode,
            isEstimate: isEstimate,
            _ts: invTs,
            lastPaymentTime: lastPay,
            paymentHistory: paymentHistory,
            isDeleted: false,
            details: {
              id: uniqueId,
              invoiceNo: cleanInvNo,
              invoiceDate: invDate,
              date: invDate,
              docType: docType,
              isEstimate: isEstimate,
              buyer: {
                name: custName,
                phone: custPhone,
                gstin: gstin
              },
              consignee: {
                name: custName,
                phone: custPhone,
                gstin: gstin
              },
              items: items,
              totals: {
                subtotal: subtotal,
                cgst: cgst,
                sgst: sgst,
                igst: igst,
                roundOff: roundOff,
                grandTotal: gTotal
              },
              total: gTotal,
              grandTotal: gTotal,
              subtotal: subtotal,
              paidAmount: paid,
              balanceDue: bal,
              paymentStatus: status,
              paymentMode: mode,
              paymentHistory: paymentHistory
            }
          };
        });
      }

      // Auto-Synthesis: If line items referenced products not in Stock & Products, ensure they exist
      if (itemsByInvoiceNo.size > 0) {
        const seenPids = new Set(importedProducts.map(p => p.id || p.description));
        itemsByInvoiceNo.forEach(items => {
          items.forEach(it => {
            const pid = it.productId || `PRD-${Date.now()}`;
            const desc = it.description;
            if (desc && !seenPids.has(pid) && !seenPids.has(desc)) {
              seenPids.add(pid);
              seenPids.add(desc);
              importedProducts.push({
                id: pid,
                description: desc,
                hsn: it.hsn || "310590",
                packSize: it.packSize || "",
                unit: it.unit || "NOS",
                rate: it.rate || 0,
                discount: it.discount || 0,
                price: it.rate || 0,
                stock: 100,
                totalValue: (it.rate || 0) * 100,
                status: "In Stock",
                barcode: "",
                is_deleted: false,
                updatedAt: new Date().toISOString()
              });
            }
          });
        });
      }

      // Auto-Synthesis: If invoices reference customers not in Customer Directory, ensure they exist
      if (importedInvoices.length > 0) {
        const seenCusts = new Set(importedParties.map(p => String(p.name || '').trim().toLowerCase()));
        importedInvoices.forEach(inv => {
          const cName = String(inv.customerName || '').trim();
          if (cName && !seenCusts.has(cName.toLowerCase())) {
            seenCusts.add(cName.toLowerCase());
            importedParties.push({
              id: `party-${Date.now()}-${Math.floor(Math.random() * 1000)}`,
              name: cName,
              phone: String(inv.customerPhone || '').trim(),
              email: '',
              gstin: String((inv.buyer && inv.buyer.gstin) || '').trim(),
              address: '',
              city: '',
              state: 'Andhra Pradesh',
              stateCode: '37',
              type: 'receiver',
              company: cName,
              is_deleted: false,
              updatedAt: new Date().toISOString()
            });
          }
        });
      }

      const confirmMsg = `📊 RESTORE MASTER EXCEL DATABASE (.XLSX)?\n\n` +
        `• 📦 Products & Stock: ${importedProducts.length}\n` +
        `• 👥 Customers & Ledgers: ${importedParties.length}\n` +
        `• 📄 Invoices & Line Items: ${importedInvoices.length}\n\n` +
        `Click OK to restore these records and synchronize across Supabase Cloud.`;

      if (!confirm(confirmMsg)) {
        if (event.target) event.target.value = "";
        return;
      }

      // CRITICAL: Clear ALL deletion tombstones, cancelled lists, and history clearance flags
      try {
        ["deleted_party_ids", "deleted_invoice_ids", "cancelled_invoices",
         "database_history_cleared", "database_history_cleared_at",
         "products_cleared", "deleted_product_ids", "deleted_customer_ids",
         "turbo_outbox_queue"].forEach(k => {
          localStorage.removeItem(k);
          try { sessionStorage.removeItem(k); } catch(e){}
        });
        window.databaseHistoryClearedAt = 0;
      } catch(e) {}

      // Explicitly unblock each restored invoice
      importedInvoices.forEach(inv => {
        if (typeof window.clearInvoiceTombstone === 'function') {
          window.clearInvoiceTombstone(inv.invoiceNo, inv.id);
        }
      });

      // 1. Commit Products
      if (importedProducts.length > 0) {
        productsDb = importedProducts;
        window.productsDb = productsDb;
        localStorage.setItem("products", JSON.stringify(productsDb));
        if (window.TurboIndexedDB && typeof window.TurboIndexedDB.saveAllProducts === 'function') {
          window.TurboIndexedDB.saveAllProducts(productsDb);
        }
        if (window.AaryanDB && typeof window.AaryanDB.saveAllProducts === 'function') {
          window.AaryanDB.saveAllProducts(productsDb);
        }
      }

      // 2. Commit Customers / Parties
      if (importedParties.length > 0) {
        partiesDb = importedParties;
        window.partiesDb = partiesDb;
        localStorage.setItem("parties", JSON.stringify(partiesDb));
        localStorage.setItem("parties_seeded", "true");
        if (window.TurboIndexedDB && typeof window.TurboIndexedDB.saveAllParties === 'function') {
          window.TurboIndexedDB.saveAllParties(partiesDb);
        }
        if (window.AaryanDB && typeof window.AaryanDB.saveAllParties === 'function') {
          window.AaryanDB.saveAllParties(partiesDb);
        }
      }

      // 3. Commit Invoices
      if (importedInvoices.length > 0) {
        invoicesDb = importedInvoices;
        window.invoicesDb = invoicesDb;
        localStorage.setItem("invoices", JSON.stringify(invoicesDb));
        if (window.TurboIndexedDB && typeof window.TurboIndexedDB.saveAllInvoices === 'function') {
          window.TurboIndexedDB.saveAllInvoices(invoicesDb);
        } else if (window.TurboIndexedDB && typeof window.TurboIndexedDB.saveInvoice === 'function') {
          for (let i = 0; i < invoicesDb.length; i++) {
            window.TurboIndexedDB.saveInvoice(invoicesDb[i]);
          }
        }
        if (window.AaryanDB && typeof window.AaryanDB.saveAllInvoices === 'function') {
          window.AaryanDB.saveAllInvoices(invoicesDb);
        }
      }

      if (window.TurboDataStore && typeof window.TurboDataStore.rebuildIndexes === 'function') {
        window.TurboDataStore.rebuildIndexes();
      }

      // Refresh memory stores
      loadAllDatabases();

      // Clear any search filter inputs on the tables
      if (elements && elements.searchHistoryInput) elements.searchHistoryInput.value = "";
      if (elements && elements.historyTypeFilter) elements.historyTypeFilter.value = "";
      if (elements && elements.historyPaymentStatusFilter) elements.historyPaymentStatusFilter.value = "";
      if (elements && elements.searchProductsInput) elements.searchProductsInput.value = "";
      const custSearchInput = document.getElementById("search-customers-directory-input");
      if (custSearchInput) custSearchInput.value = "";
      window.isInitialSyncDone = true;

      // Refresh all UI views completely
      if (typeof populateBillingSelectors === 'function') populateBillingSelectors();
      if (typeof loadInvoicesHistoryTable === 'function') loadInvoicesHistoryTable();
      if (typeof renderHistoryTableRows === 'function') renderHistoryTableRows(invoicesDb);
      if (typeof loadProductsDatabaseTable === 'function') loadProductsDatabaseTable();
      if (typeof loadPartiesDatabaseLists === 'function') loadPartiesDatabaseLists();
      if (typeof renderPartiesLists === 'function') renderPartiesLists(partiesDb);
      if (typeof renderPartiesTable === 'function') renderPartiesTable();
      if (typeof window.renderCustomersDirectoryView === 'function') window.renderCustomersDirectoryView();
      if (typeof updateDashboardOverview === 'function') updateDashboardOverview();
      if (typeof autoSuggestInvoiceNo === 'function') autoSuggestInvoiceNo(true);
      if (elements && elements.historyCount) elements.historyCount.textContent = String(invoicesDb.length);

      // Push restored data to Supabase Cloud Database in background
      if (window.SupabaseDB && window.SupabaseDB.isConfigured()) {
        try {
          if (importedProducts.length > 0) {
            window.SupabaseDB.saveAllProducts(productsDb).catch(console.warn);
          }
          if (importedParties.length > 0) {
            window.SupabaseDB.saveAllCustomers(partiesDb).catch(console.warn);
          }
          if (importedInvoices.length > 0) {
            if (typeof window.SupabaseDB.bulkUpsertInvoices === 'function') {
              window.SupabaseDB.bulkUpsertInvoices(invoicesDb).catch(console.warn);
            } else {
              for (let i = 0; i < invoicesDb.length; i++) {
                window.SupabaseDB.upsertInvoice(invoicesDb[i]).catch(console.warn);
              }
            }
          }
        } catch (sbErr) {
          console.warn("[Excel Import] Supabase push error:", sbErr);
        }
      }

      showFloatingToast(`🎉 Master Excel Restore Completed! Restored ${importedProducts.length} Products, ${importedParties.length} Customers, and ${importedInvoices.length} Invoices.`, "success", 7000);

    } catch (err) {
      console.error("Excel import error:", err);
      showFloatingToast(`❌ Failed importing Excel file: ${err.message}`, "error", 6000);
    } finally {
      if (event.target) event.target.value = "";
    }
  };
  reader.readAsArrayBuffer(file);
};

// ============================================================================
// 1-Click Store Database Backup to Email (.xlsx Master Excel + .json Archive)
// ============================================================================
window.sendDataBackupToEmail = async function(options = {}) {
  const isSilent = !!options.isSilent;
  const scheduleType = options.scheduleType || "MANUAL";

  const emailInput = document.getElementById('backup-target-email');
  const sendBtn = document.getElementById('btn-email-backup');
  let targetEmail = (emailInput ? emailInput.value : "").trim().toLowerCase();
  if (!targetEmail || !targetEmail.includes('@')) {
    targetEmail = (globalSettings?.company?.email || window.AUTHORIZED_LOGIN_EMAIL || "kandukurijagan99@gmail.com").toLowerCase().trim();
    if (emailInput) emailInput.value = targetEmail;
  }

  loadAllDatabases();
  const authUsers = (typeof window.getAuthorizedUsersList === 'function') ? window.getAuthorizedUsersList() : [];
  const sanitizedUsers = (authUsers || []).map(u => ({
    email: u.email,
    name: u.name,
    role: u.role,
    status: u.status,
    lastLogin: u.lastLogin
  }));

  const backupObj = {
    app: "Aaryan Aqua GST Billing & Store Management",
    version: "5.29.0",
    exportDate: new Date().toISOString(),
    scheduleType: scheduleType,
    invoices: invoicesDb || [],
    products: productsDb || [],
    parties: partiesDb || [],
    settings: globalSettings || {},
    authorized_users: sanitizedUsers
  };

  // Generate Master Excel (.xlsx) file in memory
  let excelBase64 = null;
  let excelArrayBuffer = null;
  try {
    if (typeof window.generateMasterExcelWorkbook === 'function') {
      const xlRes = window.generateMasterExcelWorkbook(backupObj);
      excelBase64 = xlRes.base64;
      excelArrayBuffer = xlRes.arrayBuffer;
    }
  } catch (xlErr) {
    console.warn("Could not generate Excel attachment:", xlErr);
  }

  // 1. Instant local offline copies (JSON + Excel) if manual
  if (!isSilent) {
    try {
      const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(backupObj, null, 2));
      const dl = document.createElement('a');
      dl.setAttribute("href", dataStr);
      const today = new Date().toISOString().split('T')[0];
      dl.setAttribute("download", `Aaryan_Aqua_Backup_${today}.json`);
      document.body.appendChild(dl);
      dl.click();
      dl.remove();
    } catch (_) {}
  }

  // 2. Dispatch email with Excel + JSON attachments via Google Apps Script MailApp
  const origBtnHtml = sendBtn ? sendBtn.innerHTML : "";
  if (sendBtn && !isSilent) {
    sendBtn.disabled = true;
    sendBtn.innerHTML = `<i class="fa-solid fa-spinner fa-spin"></i> Sending...`;
  }

  if (!isSilent) {
    showFloatingToast(`📤 Dispatching complete store backup (Excel .xlsx + JSON) to ${targetEmail}...`, "info", 4000);
  }

  try {
    const scriptUrl = typeof GOOGLE_SCRIPT_URL !== 'undefined' ? GOOGLE_SCRIPT_URL : "https://script.google.com/macros/s/AKfycbxHi4L_xLrfRhx1KWxRxQD1QcqbVEZVMcYR37DJEGSPe2ykZyy-ATnYyZFxnSySS6OF/exec";
    const res = await fetch(scriptUrl, {
      method: "POST",
      headers: { "Content-Type": "text/plain;charset=utf-8" },
      body: JSON.stringify({
        action: "email_backup",
        email: targetEmail,
        backup: backupObj,
        excelBase64: excelBase64,
        scheduleType: scheduleType,
        token: typeof API_SECRET_TOKEN !== 'undefined' ? API_SECRET_TOKEN : ""
      })
    });

    const resJson = await res.json().catch(() => null);
    if (resJson && resJson.ok) {
      const msg = scheduleType === "WEEKLY_AUTOMATED"
        ? `📅 Weekly Automated Backup (Excel + JSON) delivered to ${targetEmail}!`
        : (scheduleType === "MONTHLY_AUTOMATED"
          ? `📊 Monthly Automated Backup (Excel + JSON) delivered to ${targetEmail}!`
          : `✅ Success! Complete Store Backup (Excel .xlsx + JSON) delivered to ${targetEmail}!`);

      showFloatingToast(msg, "success", 7000);
      if (sendBtn && !isSilent) {
        sendBtn.innerHTML = `<i class="fa-solid fa-check"></i> Sent!`;
        setTimeout(() => {
          sendBtn.disabled = false;
          sendBtn.innerHTML = origBtnHtml;
        }, 3000);
      }
      return;
    }
    throw new Error(resJson?.error || "Script returned error");
  } catch (err) {
    console.warn("[Backup to Email] Primary cloud dispatch note:", err);
    if (!isSilent) {
      const compName = globalSettings.company?.name || "Aaryan Aqua Needs";
      const subject = encodeURIComponent(`📦 Store Database Backup Snapshot - ${compName}`);
      const body = encodeURIComponent(
        `Store Database Backup generated on ${new Date().toLocaleString()}\n\n` +
        `Summary:\n` +
        `• Total Invoices: ${(backupObj.invoices || []).length}\n` +
        `• Total Products: ${(backupObj.products || []).length}\n` +
        `• Total Parties: ${(backupObj.parties || []).length}\n\n` +
        `The full JSON backup file has been saved to your Downloads folder and can be restored anytime via Settings > Import Excel / Backup.`
      );
      window.open(`mailto:${targetEmail}?subject=${subject}&body=${body}`, '_blank');
      showFloatingToast(`📁 Backup downloaded to your computer & email draft opened for ${targetEmail}.`, "info", 6000);
      if (sendBtn) {
        sendBtn.disabled = false;
        sendBtn.innerHTML = origBtnHtml;
      }
    }
  }
};

// ============================================================================
// AUTOMATED BACKUP SCHEDULE CONTROLLER
// ============================================================================
window.saveBackupScheduleSettings = async function() {
  const freqSelect = document.getElementById("backup-schedule-frequency");
  const autoToggle = document.getElementById("backup-auto-enabled");
  const emailInput = document.getElementById("backup-target-email");
  const statusBadge = document.getElementById("backup-schedule-status-badge");
  const saveBtn = document.getElementById("btn-save-backup-schedule");

  const freq = freqSelect ? freqSelect.value : "both";
  const enabled = autoToggle ? autoToggle.checked : true;
  const targetEmail = (emailInput ? emailInput.value : "").trim().toLowerCase() || (globalSettings.company?.email || "kandukurijagan99@gmail.com");

  globalSettings.backupSchedule = {
    enabled,
    frequency: freq,
    targetEmail,
    lastSaved: new Date().toISOString()
  };

  try { localStorage.setItem("settings", JSON.stringify(globalSettings)); } catch(_) {}
  if (window.SupabaseDB && typeof window.SupabaseDB.saveSettings === 'function') {
    window.SupabaseDB.saveSettings(globalSettings).catch(() => {});
  }

  let origBtn = saveBtn ? saveBtn.innerHTML : "";
  if (saveBtn) {
    saveBtn.disabled = true;
    saveBtn.innerHTML = `<i class="fa-solid fa-spinner fa-spin"></i> Saving...`;
  }

  try {
    const scriptUrl = typeof GOOGLE_SCRIPT_URL !== 'undefined' ? GOOGLE_SCRIPT_URL : "";
    if (scriptUrl) {
      await fetch(scriptUrl, {
        method: "POST",
        headers: { "Content-Type": "text/plain;charset=utf-8" },
        body: JSON.stringify({
          action: "setup_backup_schedule",
          frequency: enabled ? freq : "manual",
          email: targetEmail,
          token: typeof API_SECRET_TOKEN !== 'undefined' ? API_SECRET_TOKEN : ""
        })
      });
    }
    if (statusBadge) {
      statusBadge.textContent = enabled
        ? `🟢 Active: Automated ${freq === 'both' ? 'Weekly & Monthly' : (freq === 'weekly' ? 'Weekly' : 'Monthly')} Cloud Cron`
        : "⏸️ Paused: Manual Backups Only";
    }
    showFloatingToast("✅ Automated Cloud Backup Schedule saved and synced with Google Cloud Cron!", "success", 6000);
  } catch (err) {
    showFloatingToast("✅ Backup schedule saved locally.", "info", 4000);
  } finally {
    if (saveBtn) {
      saveBtn.disabled = false;
      saveBtn.innerHTML = origBtn;
    }
  }
};

window.importDataBackupJSON = function(event) {
  const file = event.target.files[0];
  if (!file) return;

  const reader = new FileReader();
  reader.onload = async function(e) {
    try {
      const data = JSON.parse(e.target.result);
      if (!data || typeof data !== 'object') {
        throw new Error("Invalid backup JSON format.");
      }

      const importedInvoices = Array.isArray(data.invoices) ? data.invoices : [];
      const importedProducts = Array.isArray(data.products) ? data.products : [];
      const importedParties = Array.isArray(data.parties) ? data.parties : [];
      const importedSettings = data.settings || null;
      const importedUsers = Array.isArray(data.authorized_users) ? data.authorized_users : [];

      const confirmMsg = `📦 RESTORE COMPLETE STORE BACKUP?\n\n` +
        `• Invoices to restore: ${importedInvoices.length}\n` +
        `• Products to restore: ${importedProducts.length}\n` +
        `• Parties / Customers to restore: ${importedParties.length}\n` +
        `• Store Configuration: ${importedSettings ? 'Yes' : 'No'}\n\n` +
        `Click OK to overwrite local data and synchronize with Supabase Cloud.`;

      if (confirm(confirmMsg)) {
        // Clear any previous deletion flags and tombstones so imported data loads clean
        try {
          localStorage.removeItem("products_cleared");
          localStorage.removeItem("database_history_cleared");
          localStorage.removeItem("database_history_cleared_at");
          window.databaseHistoryClearedAt = 0;
          localStorage.removeItem("deleted_party_ids");
          localStorage.removeItem("deleted_invoice_ids");
          localStorage.removeItem("cancelled_invoices");
          localStorage.removeItem("deleted_product_ids");
          localStorage.removeItem("deleted_customer_ids");
          localStorage.removeItem("turbo_outbox_queue");
        } catch(err) {}

        importedInvoices.forEach(inv => {
          if (typeof window.clearInvoiceTombstone === 'function') {
            window.clearInvoiceTombstone(inv.invoiceNo, inv.id);
          }
        });

        localStorage.setItem("invoices", JSON.stringify(importedInvoices));
        localStorage.setItem("products", JSON.stringify(importedProducts));
        localStorage.setItem("parties", JSON.stringify(importedParties));
        if (importedSettings) {
          localStorage.setItem("settings", JSON.stringify(importedSettings));
          window.globalSettings = importedSettings;
        }

        // Restore to IndexedDB
        if (window.TurboIndexedDB) {
          if (typeof window.TurboIndexedDB.saveAllInvoices === 'function') window.TurboIndexedDB.saveAllInvoices(importedInvoices);
          if (typeof window.TurboIndexedDB.saveAllProducts === 'function') window.TurboIndexedDB.saveAllProducts(importedProducts);
          if (typeof window.TurboIndexedDB.saveAllParties === 'function') window.TurboIndexedDB.saveAllParties(importedParties);
        }

        // Push to Supabase Cloud
        if (window.SupabaseDB && window.SupabaseDB.isConfigured()) {
          try {
            if (importedProducts.length > 0) window.SupabaseDB.bulkUpsertProducts(importedProducts);
            if (importedParties.length > 0) {
              for (const p of importedParties) {
                window.SupabaseDB.upsertCustomer(p).catch(() => {});
              }
            }
          } catch(err) {
            console.warn("[Restore] Supabase sync notice:", err);
          }
        }

        if (typeof syncDatabaseToServer === 'function') {
          for (const inv of importedInvoices) {
            syncDatabaseToServer("invoices", inv);
          }
          syncDatabaseToServer("products", importedProducts);
          syncDatabaseToServer("parties", importedParties);
          if (importedSettings) syncDatabaseToServer("settings", importedSettings);
        }

        showFloatingToast(`✅ Restored ${importedInvoices.length} Invoices, ${importedProducts.length} Products, ${importedParties.length} Parties! Reloading...`, "success", 4000);
        setTimeout(() => {
          window.location.reload();
        }, 1200);
      }
    } catch (err) {
      showFloatingToast("⚠️ Failed to parse backup file: " + err.message, "warning");
    } finally {
      event.target.value = "";
    }
  };
  reader.readAsText(file);
};

// --- UNIVERSAL MODAL BACKDROP AND ESCAPE-KEY DISMISS ---
(function() {
  function dismissAllActiveModals() {
    document.querySelectorAll('.modal-overlay, .turbo-omni-modal').forEach(modal => {
      if (typeof window.hideAppModal === 'function') {
        window.hideAppModal(modal);
      } else {
        modal.classList.add('hidden');
        modal.style.setProperty('display', 'none', 'important');
      }
    });
    if (typeof whatsappPollInterval !== 'undefined' && whatsappPollInterval) {
      clearInterval(whatsappPollInterval);
      whatsappPollInterval = null;
    }
  }

  // Backdrop click on any overlay
  document.addEventListener('click', function(e) {
    if (e.target && e.target.classList && (e.target.classList.contains('modal-overlay') || e.target.classList.contains('turbo-omni-modal'))) {
      if (typeof window.hideAppModal === 'function') {
        window.hideAppModal(e.target);
      } else {
        e.target.classList.add('hidden');
        e.target.style.setProperty('display', 'none', 'important');
      }
      if (e.target.id === 'whatsapp-bot-modal' && typeof closeWhatsAppBotModal === 'function') {
        closeWhatsAppBotModal();
      }
    }
  }, true);

  // SaaS Global Keyboard Shortcuts & Modal Escape
  document.addEventListener('keydown', function(e) {
    if (e.key === 'Escape' || e.key === 'Esc') {
      dismissAllActiveModals();
      return;
    }

    // Ctrl / Cmd keyboard shortcuts (Pro SaaS speedrun)
    if (e.ctrlKey || e.metaKey) {
      const key = (e.key || '').toLowerCase();
      if (key === 'b') {
        e.preventDefault();
        if (typeof window.switchTab === 'function') window.switchTab('billing');
      } else if (key === 'd') {
        e.preventDefault();
        if (typeof window.switchTab === 'function') window.switchTab('dashboard');
      } else if (key === 'h') {
        e.preventDefault();
        if (typeof window.switchTab === 'function') window.switchTab('history');
      } else if (key === 'k') {
        e.preventDefault();
        const activeNav = document.querySelector('.sidebar-nav .nav-item.active');
        const activeTab = activeNav ? activeNav.getAttribute('data-tab') : '';
        if (activeTab === 'history') {
          const histInput = document.getElementById('search-history-input');
          if (histInput) { histInput.focus(); histInput.select(); }
        } else if (activeTab === 'products') {
          const prodInput = document.getElementById('search-products-input');
          if (prodInput) { prodInput.focus(); prodInput.select(); }
        } else if (activeTab === 'billing') {
          const itemInput = document.getElementById('bill-item-name') || document.getElementById('bill-buyer-name');
          if (itemInput) { itemInput.focus(); itemInput.select(); }
        } else {
          if (typeof window.switchTab === 'function') window.switchTab('history');
          setTimeout(() => {
            const histInput = document.getElementById('search-history-input');
            if (histInput) { histInput.focus(); histInput.select(); }
          }, 80);
        }
      }
    }
  });
})();

