window.submitModalAdminUnlock = async function() {
  const pwdInput = document.getElementById("modal-admin-pwd-input");
  const errEl = document.getElementById("modal-admin-pwd-error");
  const unlockBtn = document.querySelector("#verify-admin-unlock-form .btn-success");
  const enteredVal = (pwdInput?.value || "").trim();

  // Check rate limit lockout first
  const currentLock = AppSecurity.isLockedOut();
  if (currentLock.locked) {
    if (errEl) {
      errEl.textContent = `❌ Security cooldown active: Try again in ${currentLock.remainingSeconds}s.`;
      errEl.style.display = "block";
    }
    if (unlockBtn) unlockBtn.disabled = true;
    return;
  }

  if (!enteredVal) {
    if (errEl) {
      errEl.textContent = "Please enter your admin password or PIN!";
      errEl.style.display = "block";
    }
    return;
  }

  const sec = globalSettings?.security || {};
  const customPwd = (sec.password || "").toString().trim();
  const customPin = (sec.whatsappPin || sec.securityPin || sec.pin || "").toString().trim();

  let isMatch = false;
  if (customPwd && (enteredVal === customPwd || enteredVal.toLowerCase() === customPwd.toLowerCase())) {
    isMatch = true;
  } else if (customPin && enteredVal === customPin) {
    isMatch = true;
  } else if (!customPwd && !customPin && (enteredVal === "Aaryan@2024" || enteredVal === "2024")) {
    isMatch = true;
  }

  if (isMatch) {
    AppSecurity.recordSuccessfulLogin("Store Owner", "Invoice Verification Modal");
    unlockSystemSilently();
    if (typeof showFloatingToast === 'function') {
      showFloatingToast("🔓 Admin authenticated! Settlement mode unlocked.", "success", 3000);
    }
    if (window.currentVerifiedInvoiceNo && typeof openInvoiceVerificationModal === 'function') {
      openInvoiceVerificationModal(window.currentVerifiedInvoiceNo);
    }
  } else {
    const penalty = AppSecurity.recordFailedAttempt("Invoice Verification Modal");
    if (penalty.lockoutSec > 0) {
      if (errEl) {
        errEl.textContent = `🚨 Rate-limit activated! ${penalty.lockoutSec}s cooldown penalty.`;
        errEl.style.display = "block";
      }
      if (unlockBtn) unlockBtn.disabled = true;
      setTimeout(() => {
        const s = AppSecurity.isLockedOut();
        if (!s.locked && unlockBtn) unlockBtn.disabled = false;
      }, penalty.lockoutSec * 1000);
    } else {
      const left = 3 - (penalty.attempts % 3);
      if (errEl) {
        errEl.textContent = `❌ Invalid password or PIN. (Attempt ${penalty.attempts} — ${left} left before cooldown)`;
        errEl.style.display = "block";
      }
    }
    if (pwdInput) {
      pwdInput.value = "";
      pwdInput.focus();
    }
  }
};

window.toggleVerifyCustomAmount = function(status) {
  const wrap = document.getElementById("verify-custom-amount-wrap");
  const btn = document.getElementById("verify-done-pay-btn");
  const input = document.getElementById("verify-pay-amount-input");
  
  let curBal = 0;
  if (window.currentVerifiedInvoiceNo) {
    const inv = (typeof invoicesDb !== "undefined" ? invoicesDb : []).find(i => 
      String(i.invoiceNo || "").trim().toLowerCase() === String(window.currentVerifiedInvoiceNo).trim().toLowerCase() ||
      String(i.id || "").trim().toLowerCase() === String(window.currentVerifiedInvoiceNo).trim().toLowerCase()
    );
    if (inv) {
      const payInfo = typeof getInvoicePaidAndBalance === "function" ? getInvoicePaidAndBalance(inv) : { balance: inv.balanceDue || 0 };
      curBal = payInfo.balance;
    }
  }

  if (status === "Partial") {
    if (wrap) wrap.style.display = "block";
    if (input && (!input.value || parseFloat(input.value) <= 0)) {
      input.value = curBal > 0 ? (curBal / 2).toFixed(2) : "0";
    }
    if (btn) btn.innerHTML = '<i class="fa-solid fa-circle-check"></i> Record Partial Payment & Update Database';
  } else {
    if (wrap) wrap.style.display = "none";
    if (input) input.value = curBal.toFixed(2);
    if (btn) btn.innerHTML = `<i class="fa-solid fa-circle-check"></i> Settle Full Balance (₹ ${formatCurrency(curBal)}) & Update Database`;
  }
};

window.submitInvoicePaymentSettlement = function() {
  // Strict Security: Allowed ONLY when authenticated inside the admin dashboard as authorized admin
  const isViewOnly = (typeof window.isViewOnlyUser === 'function') && window.isViewOnlyUser();
  const isDemo = (typeof window.isDemoMode === 'function' && window.isDemoMode()) ||
                 (sessionStorage.getItem("is_demo_mode") === "true") || 
                 (sessionStorage.getItem("current_user_role") === "viewer") || 
                 (sessionStorage.getItem("current_user_role") === "customer") || 
                 (sessionStorage.getItem("current_user_role") === "demo") || 
                 (sessionStorage.getItem("current_user_role") === "guest") || 
                 isViewOnly;

  if (isDemo) {
    if (typeof showFloatingToast === "function") showFloatingToast("🔒 Payment collection & settlement are disabled in Demo Preview.", "warning", 4000);
    return;
  }

  const currentUserEmail = (sessionStorage.getItem("current_user_email") || "").toLowerCase().trim();
  const mainAdminEmail = (window.AUTHORIZED_LOGIN_EMAIL || "kandukurijagan99@gmail.com").toLowerCase().trim();
  const isMainAdmin = (currentUserEmail === mainAdminEmail) || (sessionStorage.getItem("is_main_admin") === "true");
  const isAuthorized = isMainAdmin || ((typeof window.isUserAuthorizedByAdmin === 'function') && window.isUserAuthorizedByAdmin(currentUserEmail));
  const isSessionAuth = (sessionStorage.getItem("session_authenticated") === "true") || (localStorage.getItem("app_authenticated") === "true");
  const isAppLocked = (typeof isLocked !== "undefined" && isLocked) || (sessionStorage.getItem("manual_locked") === "true");

  const isAdminLoggedIn = isAuthorized && isSessionAuth && !isAppLocked;
  if (!isAdminLoggedIn) {
    if (typeof showFloatingToast === "function") showFloatingToast("🔒 Access Denied: Authorized Admin credentials required to settle payments.", "warning", 4000);
    return;
  }

  if (!window.currentVerifiedInvoiceNo && !window.currentVerifiedInvoiceId) return;
  const invNo = String(window.currentVerifiedInvoiceNo || "").trim();
  const cleanNo = invNo.replace(/^#/, '');
  const targetId = String(window.currentVerifiedInvoiceId || "").trim();
  const inv = (typeof invoicesDb !== "undefined" ? invoicesDb : []).find(i => 
    (targetId && String(i.id || "").trim().toLowerCase() === targetId.toLowerCase()) ||
    (invNo && String(i.invoiceNo || "").trim().toLowerCase() === invNo.toLowerCase()) ||
    (cleanNo && String(i.invoiceNo || "").trim().toLowerCase() === cleanNo.toLowerCase()) ||
    (invNo && String(i.id || "").trim().toLowerCase() === invNo.toLowerCase())
  );

  if (!inv) {
    if (typeof showFloatingToast === "function") showFloatingToast("❌ Error: Invoice record not found.", "warning");
    return;
  }

  const payInfo = typeof getInvoicePaidAndBalance === "function" 
    ? getInvoicePaidAndBalance(inv) 
    : { total: parseFloat(inv.total) || 0, paid: parseFloat(inv.paidAmount) || 0, balance: parseFloat(inv.balanceDue) || 0 };
  const totalAmt = payInfo.total;
  const curPaid = payInfo.paid;
  const curBal = payInfo.balance;

  const selectedStatus = document.getElementById("verify-pay-status-select")?.value || "Paid";
  const payMode = document.getElementById("verify-pay-mode-select")?.value || "UPI / Online";
  const payRef = document.getElementById("verify-pay-ref-input")?.value.trim() || "";

  let settledAmount = 0;
  let newPaid = 0;
  let newBal = 0;
  let finalStatus = "Paid";

  if (selectedStatus === "Partial") {
    const customAmt = parseFloat(document.getElementById("verify-pay-amount-input")?.value) || 0;
    if (customAmt <= 0) {
      if (typeof showFloatingToast === "function") showFloatingToast("⚠️ Please enter a valid payment amount.", "warning");
      return;
    }
    settledAmount = Math.min(customAmt, curBal);
    newPaid = curPaid + settledAmount;
    newBal = Math.max(0, curBal - settledAmount);
    finalStatus = newBal <= 0.01 ? "Paid" : "Partial";
  } else {
    // Full settlement of balance
    settledAmount = curBal;
    newPaid = totalAmt;
    newBal = 0;
    finalStatus = "Paid";
  }

  inv.paidAmount = newPaid;
  inv.balanceDue = newBal;
  inv.balancePaid = (inv.balancePaid || 0) + settledAmount;
  inv.paymentStatus = finalStatus;
  inv.paymentMode = payMode;
  if (payRef) inv.paymentReference = payRef;

  if (inv.details) {
    inv.details.paidAmount = newPaid;
    inv.details.balanceDue = newBal;
    inv.details.balancePaid = (inv.details.balancePaid || 0) + settledAmount;
    inv.details.paymentStatus = finalStatus;
    inv.details.paymentMode = payMode;
    if (payRef) inv.details.paymentReference = payRef;
  }

  if (!inv.paymentHistory) inv.paymentHistory = [];
  inv.paymentHistory.push({
    date: new Date().toISOString(),
    amount: settledAmount,
    mode: payMode,
    reference: payRef,
    status: finalStatus,
    source: "Admin Verification Modal Settlement"
  });
  if (typeof window.ensureInvoicePaymentHistory === 'function') {
    window.ensureInvoicePaymentHistory(inv);
  }

  if (isDemo) {
    try { sessionStorage.setItem("demo_invoices", JSON.stringify(invoicesDb)); } catch(e) {}
    window.openInvoiceVerificationModal(invNo);
    if (typeof updateDashboardOverview === "function") updateDashboardOverview();
    if (typeof loadInvoicesHistoryTable === "function") loadInvoicesHistoryTable();
    if (typeof renderRecentInvoicesTable === "function") renderRecentInvoicesTable();
    if (typeof renderCustomerLedgerSummary === "function") renderCustomerLedgerSummary();
    if (typeof window.renderCustomersDirectoryView === "function") window.renderCustomersDirectoryView();
    if (typeof showFloatingToast === "function") {
      showFloatingToast(`✅ Demo Settlement Simulated: Invoice #${cleanNo} marked as ${finalStatus}! (Demo preview — no live data modified)`, "success", 4500);
    }
    if (typeof playAudioFeedback === "function") playAudioFeedback("success");
    return;
  }

  try {
    localStorage.setItem("invoices", JSON.stringify(invoicesDb));
    window.invoicesDb = invoicesDb;
  } catch (e) {
    console.warn("Error persisting invoices:", e);
  }
  if (window.AaryanDB && typeof window.AaryanDB.saveInvoice === 'function') {
    try { window.AaryanDB.saveInvoice(inv); } catch (e) {}
  }
  if (window.SupabaseDB && window.SupabaseDB.isConfigured()) {
    try { window.SupabaseDB.upsertInvoice(inv).catch(err => console.warn("[Supabase] Post-payment sync error:", err)); } catch (e) {}
  }
  if (typeof syncDatabaseToServer === 'function') {
    try { syncDatabaseToServer("invoices", inv); } catch (e) {}
  }
  if (typeof renderInvoicesTable === "function") renderInvoicesTable();
  if (typeof loadInvoicesHistoryTable === "function") loadInvoicesHistoryTable();
  if (typeof updateDashboardOverview === "function") updateDashboardOverview();
  if (typeof broadcastInterTabEvent === 'function') {
    broadcastInterTabEvent('INVOICE_SETTLED', {
      invoiceId: inv.id,
      invoiceNo: inv.invoiceNo,
      paidAmount: newPaid,
      balanceDue: newBal,
      balancePaid: inv.balancePaid,
      paymentStatus: finalStatus,
      paymentMode: payMode,
      paymentReference: payRef,
      paymentHistory: inv.paymentHistory,
      invoice: inv
    });
    if (typeof window.publishRetainedDatabaseState === 'function') window.publishRetainedDatabaseState();
  } else if (typeof window.broadcastDatabaseMutation === 'function') {
    window.broadcastDatabaseMutation();
    if (typeof window.publishRetainedDatabaseState === 'function') window.publishRetainedDatabaseState();
  }

  // Track Google Ads conversion for payment settlement
  if (typeof window.trackGoogleAdsConversion === 'function') {
    window.trackGoogleAdsConversion('payment_settled', {
      transaction_id: String(inv.invoiceNo || ''),
      value: Number(settledAmount || 0),
      currency: 'INR',
      payment_mode: payMode
    });
  }

  if (typeof playSuccessChime === "function") playSuccessChime();

  if (typeof showFloatingToast === "function") {
    showFloatingToast(`✅ Payment of ₹ ${formatCurrency(settledAmount)} recorded! Invoice #${inv.invoiceNo} marked as ${finalStatus}.`, "success", 4000);
  }

  openInvoiceVerificationModal(inv.invoiceNo);
};



