// Universal Dynamic Screen-Fit Controller for Dashboard
window.toggleDashboardScreenFit = function() {
  const dash = document.getElementById('view-dashboard');
  if (!dash) return;
  const isFitted = dash.classList.toggle('dashboard-fitted-mode');
  try {
    localStorage.setItem('aaryan_dashboard_view_mode', isFitted ? 'fitted' : 'normal');
  } catch (e) {}
  updateDashboardFitButton(isFitted);

  if (typeof salesChartInstance !== 'undefined' && salesChartInstance) {
    salesChartInstance.resize();
  }
  if (typeof gstChartInstance !== 'undefined' && gstChartInstance) {
    gstChartInstance.resize();
  }
  if (typeof showToast === 'function') {
    showToast(isFitted ? "Compact Fitted View Active" : "Full Dashboard View Active", "info");
  }
};

function updateDashboardFitButton(isFitted) {
  const btn = document.getElementById('dashboard-fit-toggle-btn');
  const icon = document.getElementById('dashboard-fit-icon');
  const label = document.getElementById('dashboard-fit-label');
  if (!btn) return;
  if (isFitted) {
    btn.classList.add('btn-cyan');
    btn.classList.remove('btn-secondary');
    if (icon) icon.className = 'fa-solid fa-compress';
    if (label) label.textContent = 'Full View';
  } else {
    btn.classList.remove('btn-cyan');
    btn.classList.add('btn-secondary');
    if (icon) icon.className = 'fa-solid fa-expand';
    if (label) label.textContent = 'Fit Screen';
  }
}

function initDashboardScreenFit() {
  try {
    const dash = document.getElementById('view-dashboard');
    const savedMode = localStorage.getItem('aaryan_dashboard_view_mode');
    // If user has chosen 'fitted' or on compact laptop screens (height <= 820px) without explicit choice
    const shouldFit = savedMode === 'fitted' || (!savedMode && window.innerHeight <= 820);
    if (shouldFit) {
      if (dash) dash.classList.add('dashboard-fitted-mode');
      updateDashboardFitButton(true);
    } else {
      if (dash) dash.classList.remove('dashboard-fitted-mode');
      updateDashboardFitButton(false);
    }
  } catch (e) {}

  // Automatically recalculate chart sizes on any window resize or orientation change
  let resizeTimer = null;
  window.addEventListener('resize', () => {
    clearTimeout(resizeTimer);
    resizeTimer = setTimeout(() => {
      if (typeof salesChartInstance !== 'undefined' && salesChartInstance) {
        salesChartInstance.resize();
      }
      if (typeof gstChartInstance !== 'undefined' && gstChartInstance) {
        gstChartInstance.resize();
      }
    }, 100);
  });
}

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', initDashboardScreenFit);
} else {
  initDashboardScreenFit();
}

// ==========================================
// 🧮 SMART QUICK CALCULATOR & BILL INJECTOR
// ==========================================
let calcState = {
  currentInput: '0',
  previousInput: '',
  operator: null,
  waitingForOperand: false,
  lastResult: null,
  history: []
};

window.toggleQuickCalculator = function() {
  if (isLocked) return;
  const modal = document.getElementById("quick-calculator-modal");
  if (!modal) return;
  const isHidden = modal.classList.contains("hidden") || modal.style.display === "none";
  if (isHidden) {
    window.showAppModal(modal);
    if (typeof playSubtleClickAudio === "function") playSubtleClickAudio();
    updateCalcDisplay();
  } else {
    window.hideAppModal(modal);
  }
};

function updateCalcDisplay() {
  const display = document.getElementById("calc-display");
  const historyTape = document.getElementById("calc-history-tape");
  if (display) {
    display.value = calcState.currentInput;
  }
  if (historyTape) {
    if (calcState.operator && calcState.previousInput) {
      const opSym = calcState.operator === '*' ? '×' : (calcState.operator === '/' ? '÷' : (calcState.operator === '-' ? '−' : '+'));
      historyTape.textContent = `${calcState.previousInput} ${opSym} ${calcState.waitingForOperand ? '' : calcState.currentInput}`;
    } else if (calcState.history.length > 0) {
      historyTape.textContent = calcState.history[calcState.history.length - 1];
    } else {
      historyTape.textContent = "Ready";
    }
  }
}

window.calcAction = function(type, val) {
  if (typeof playSubtleClickAudio === "function") playSubtleClickAudio();
  if (type === 'num') {
    if (calcState.waitingForOperand) {
      calcState.currentInput = String(val);
      calcState.waitingForOperand = false;
    } else {
      calcState.currentInput = calcState.currentInput === '0' ? String(val) : calcState.currentInput + val;
    }
    if (calcState.currentInput.length > 14) {
      calcState.currentInput = calcState.currentInput.slice(0, 14);
    }
  } else if (type === 'dot') {
    if (calcState.waitingForOperand) {
      calcState.currentInput = '0.';
      calcState.waitingForOperand = false;
    } else if (!calcState.currentInput.includes('.')) {
      calcState.currentInput += '.';
    }
  } else if (type === 'negate') {
    if (calcState.currentInput !== '0') {
      if (calcState.currentInput.startsWith('-')) {
        calcState.currentInput = calcState.currentInput.slice(1);
      } else {
        calcState.currentInput = '-' + calcState.currentInput;
      }
    }
  } else if (type === 'percent') {
    const num = parseFloat(calcState.currentInput) || 0;
    if (calcState.operator && calcState.previousInput) {
      const prev = parseFloat(calcState.previousInput) || 0;
      const pct = (prev * num) / 100;
      calcState.currentInput = String(pct);
    } else {
      calcState.currentInput = String(num / 100);
    }
  } else if (type === 'clear') {
    calcState.currentInput = '0';
    calcState.previousInput = '';
    calcState.operator = null;
    calcState.waitingForOperand = false;
    calcState.lastResult = null;
  } else if (type === 'backspace') {
    if (!calcState.waitingForOperand) {
      if (calcState.currentInput.length > 1) {
        calcState.currentInput = calcState.currentInput.slice(0, -1);
      } else {
        calcState.currentInput = '0';
      }
    }
  } else if (type === 'op') {
    const currentVal = parseFloat(calcState.currentInput) || 0;
    if (calcState.operator && !calcState.waitingForOperand) {
      const prevVal = parseFloat(calcState.previousInput) || 0;
      const res = executeCalcOperation(prevVal, currentVal, calcState.operator);
      calcState.currentInput = formatCalcResult(res);
      calcState.previousInput = calcState.currentInput;
    } else {
      calcState.previousInput = calcState.currentInput;
    }
    calcState.operator = val;
    calcState.waitingForOperand = true;
  } else if (type === 'equal') {
    if (calcState.operator && calcState.previousInput) {
      const prevVal = parseFloat(calcState.previousInput) || 0;
      const currentVal = parseFloat(calcState.currentInput) || 0;
      const res = executeCalcOperation(prevVal, currentVal, calcState.operator);
      const opSym = calcState.operator === '*' ? '×' : (calcState.operator === '/' ? '÷' : (calcState.operator === '-' ? '−' : '+'));
      const expr = `${calcState.previousInput} ${opSym} ${calcState.currentInput} = ${formatCalcResult(res)}`;
      calcState.history.push(expr);
      if (calcState.history.length > 10) calcState.history.shift();
      calcState.currentInput = formatCalcResult(res);
      calcState.previousInput = '';
      calcState.operator = null;
      calcState.waitingForOperand = true;
      calcState.lastResult = res;
    }
  }
  updateCalcDisplay();
};

function executeCalcOperation(a, b, op) {
  switch (op) {
    case '+': return a + b;
    case '-': return a - b;
    case '*': return a * b;
    case '/': return b !== 0 ? a / b : 'Error';
    default: return b;
  }
}

function formatCalcResult(num) {
  if (num === 'Error') return 'Error';
  if (isNaN(num) || !isFinite(num)) return '0';
  const rounded = Math.round(num * 1000000) / 1000000;
  return String(rounded);
}

window.insertCalcToBill = function(targetField) {
  const raw = calcState.currentInput;
  if (raw === 'Error') return;
  const val = parseFloat(raw);
  if (isNaN(val) || val <= 0) {
    if (typeof showFloatingToast === 'function') {
      showFloatingToast('Please calculate a valid amount first', 'warning');
    }
    return;
  }

  if (typeof switchTab === 'function') {
    switchTab('billing');
  }

  if (targetField === 'rate') {
    if (typeof elements !== "undefined" && elements.billItemRate) {
      elements.billItemRate.value = val;
      if (typeof updateItemAmount === 'function') updateItemAmount();
      if (typeof showFloatingToast === 'function') {
        showFloatingToast(`💰 Injected ₹ ${formatCurrency(val)} into Bill Rate!`, 'success');
      }
    }
  } else if (targetField === 'qty') {
    if (typeof elements !== "undefined" && elements.billItemQty) {
      elements.billItemQty.value = val;
      if (typeof updateItemAmount === 'function') updateItemAmount();
      if (typeof showFloatingToast === 'function') {
        showFloatingToast(`📦 Injected ${val} into Bill Quantity!`, 'success');
      }
    }
  }

  window.toggleQuickCalculator();
};

window.copyCalcResult = function() {
  const display = document.getElementById("calc-display");
  const val = display ? display.value : calcState.currentInput;
  if (val && val !== 'Error') {
    navigator.clipboard.writeText(val).then(() => {
      if (typeof showFloatingToast === 'function') {
        showFloatingToast(`📋 Copied "${val}" to clipboard!`, 'info', 2500);
      }
    }).catch(() => {
      if (typeof showFloatingToast === 'function') {
        showFloatingToast(`Result: ${val}`, 'info');
      }
    });
  }
};

// Global Calculator Keyboard Listeners
document.addEventListener('keydown', (e) => {
  // Alt+C toggles calculator
  if (e.altKey && (e.key.toLowerCase() === 'c' || e.key.toLowerCase() === 'k')) {
    e.preventDefault();
    window.toggleQuickCalculator();
    return;
  }

  const modal = document.getElementById("quick-calculator-modal");
  if (!modal || modal.classList.contains("hidden")) return;

  if (e.key >= '0' && e.key <= '9') {
    e.preventDefault();
    window.calcAction('num', e.key);
  } else if (e.key === '.') {
    e.preventDefault();
    window.calcAction('dot');
  } else if (e.key === '+') {
    e.preventDefault();
    window.calcAction('op', '+');
  } else if (e.key === '-') {
    e.preventDefault();
    window.calcAction('op', '-');
  } else if (e.key === '*' || e.key.toLowerCase() === 'x') {
    e.preventDefault();
    window.calcAction('op', '*');
  } else if (e.key === '/') {
    e.preventDefault();
    window.calcAction('op', '/');
  } else if (e.key === '%') {
    e.preventDefault();
    window.calcAction('percent');
  } else if (e.key === 'Enter' || e.key === '=') {
    e.preventDefault();
    window.calcAction('equal');
  } else if (e.key === 'Backspace') {
    e.preventDefault();
    window.calcAction('backspace');
  } else if (e.key === 'Escape') {
    e.preventDefault();
    window.toggleQuickCalculator();
  }
});

// // ============================================================================
// TURBO SPEED & MULTI-LOT WEIGHT SUMMATION ENGINE (Fish Lots / Basket Calculator)
// ============================================================================
window.parseMultiLotWeight = function(str) {
  if (!str) return { total: 1, count: 1, isMulti: false, avg: 1 };
  const cleaned = String(str).trim();
  
  // Support multiplier expressions like "10 * 20" or "5 x 25.5"
  if (cleaned.includes('*') || cleaned.toLowerCase().includes('x')) {
    const parts = cleaned.replace(/x/gi, '*').split('*').map(x => parseFloat(x.trim())).filter(x => !isNaN(x));
    if (parts.length === 2 && parts[0] > 0 && parts[1] > 0) {
      const total = parts[0] * parts[1];
      return { total: Math.round(total * 100) / 100, count: Math.round(parts[0]), isMulti: true, avg: parts[1] };
    }
  }

  // Support space or plus separated multi-lot numbers e.g. "25.5 + 30.2 + 28.4" or "25.5 30.2 28.4"
  if (cleaned.includes('+') || (cleaned.includes(' ') && !cleaned.includes('-'))) {
    const parts = cleaned.split(/[\s+]+/).map(x => parseFloat(x.trim())).filter(x => !isNaN(x) && x > 0);
    if (parts.length > 1) {
      const total = parts.reduce((acc, v) => acc + v, 0);
      const avg = total / parts.length;
      return { total: Math.round(total * 100) / 100, count: parts.length, isMulti: true, avg: Math.round(avg * 100) / 100 };
    }
  }

  const val = parseFloat(cleaned) || 1;
  return { total: Math.max(0.01, val), count: 1, isMulti: false, avg: val };
};

// ============================================================================
// DYNAMIC UPI SMART QR CODE & INSTANT PAYMENT COMPLETION ENGINE
// ============================================================================
let currentActiveUpiInvoice = null;

window.openDynamicBillingUpiQr = function() {
  if (typeof calculateSummaryAndTable === 'function') {
    calculateSummaryAndTable();
  }
  const items = (currentInvoice && Array.isArray(currentInvoice.items)) ? currentInvoice.items : [];
  if (items.length === 0) {
    if (typeof showFloatingToast === 'function') {
      showFloatingToast("⚠️ Please add items to the bill before showing UPI payment QR code.", "warning", 3500);
    }
    return;
  }

  const grandTotalText = document.getElementById('sum-grand-total')?.textContent?.replace(/[^\d.]/g, '') || '0';
  const total = Number(currentInvoice?.grandTotal || parseFloat(grandTotalText) || 0);
  if (total <= 0) {
    if (typeof showFloatingToast === 'function') {
      showFloatingToast("⚠️ Total bill amount is ₹ 0.00. Please check item rates.", "warning", 3500);
    }
    return;
  }

  const draftInv = {
    invoiceNo: (elements.billInvoiceNo?.value) || '0001',
    customerName: (elements.billBuyerName?.value) || 'Cash Customer',
    phone: (elements.billBuyerPhone?.value) || '',
    grandTotal: total,
    isDraftBilling: true
  };
  window.showDynamicUpiQr(draftInv);
};

window.showDynamicUpiQr = function(invOrId) {
  let inv = null;
  if (typeof invOrId === 'object' && invOrId !== null) {
    inv = invOrId;
  } else if (invOrId) {
    const list = window.invoicesHistory || invoicesDb || [];
    inv = list.find(x => x && (x.id === invOrId || x.invoiceNo === invOrId));
  }
  if (!inv) {
    // Check active billing form
    const grandTotalText = document.getElementById('sum-grand-total')?.textContent?.replace(/[^\d.]/g, '') || '0';
    const total = Number((currentInvoice && currentInvoice.grandTotal) || parseFloat(grandTotalText) || 0);
    inv = {
      invoiceNo: (elements.billInvoiceNo?.value) || '0001',
      customerName: (elements.billBuyerName?.value) || 'Customer',
      phone: (elements.billBuyerPhone?.value) || '',
      grandTotal: total,
      isDraftBilling: true
    };
  }

  currentActiveUpiInvoice = inv;
  const d = inv.details || inv;
  const invNo = inv.invoiceNo || d.invoiceNo || '0001';
  const total = Number(d.balanceDue !== undefined && d.balanceDue > 0 ? d.balanceDue : (d.grandTotal || d.total || inv.grandTotal || 0));
  const merchantName = (globalSettings?.company?.name || 'Aaryan Aqua Needs').replace(/[^a-zA-Z0-9 ]/g, '').trim();
  const upiId = (globalSettings.upiId || globalSettings.bank?.upi || globalSettings.bank?.upiId || "7386262139@upi").trim();

  const modal = document.getElementById("dynamic-upi-qr-modal");
  const amtText = document.getElementById("dynamic-upi-amount-text");
  const btnAmtText = document.getElementById("dynamic-upi-btn-amt");
  const nameText = document.getElementById("dynamic-upi-merchant-name");
  const upiIdText = document.getElementById("dynamic-upi-id-text");
  const invNoText = document.getElementById("dynamic-upi-inv-no");
  const utrInput = document.getElementById("dynamic-upi-utr-input");
  const partialWrap = document.getElementById("dynamic-upi-partial-wrap");
  const partialAmtInput = document.getElementById("dynamic-upi-partial-amt");

  if (amtText) amtText.textContent = `₹ ${formatCurrency(total)}`;
  if (btnAmtText) btnAmtText.textContent = `₹ ${formatCurrency(total)}`;
  if (nameText) nameText.textContent = merchantName;
  if (upiIdText) upiIdText.textContent = upiId;
  if (invNoText) invNoText.textContent = `#${String(invNo).replace(/^#/, '')}`;
  if (utrInput) utrInput.value = "";
  if (partialWrap) partialWrap.style.display = "none";
  if (partialAmtInput) partialAmtInput.value = (total > 0 ? (total / 2).toFixed(2) : "0.00");

  const cleanInvNo = String(invNo).replace(/[^a-zA-Z0-9]/g, '');
  const qrSuffix = (inv.qrToken || d.qrToken || inv.id || "").toString().replace(/[^a-zA-Z0-9]/g, '').slice(-4).toUpperCase() || Math.random().toString(36).substring(2, 6).toUpperCase();
  const upiTr = `${cleanInvNo}${qrSuffix}`.slice(-20);
  const upiUri = `upi://pay?pa=${upiId}&pn=${encodeURIComponent(merchantName)}&am=${total.toFixed(2)}&cu=INR&tn=Invoice${cleanInvNo}-${qrSuffix}&tr=${upiTr}`;

  const canvas = document.getElementById("dynamic-upi-qr-canvas");
  const imgEl = document.getElementById("dynamic-upi-qr-img");

  let canvasSuccess = false;
  if (canvas && typeof QRious !== "undefined") {
    try {
      new QRious({
        element: canvas,
        value: upiUri,
        size: 240,
        level: 'H'
      });
      canvas.style.display = "block";
      if (imgEl) imgEl.style.display = "none";
      canvasSuccess = true;
    } catch (e) {
      console.warn("QRious dynamic canvas render failed:", e);
    }
  }

  if (!canvasSuccess && imgEl) {
    if (canvas) canvas.style.display = "none";
    imgEl.src = `https://api.qrserver.com/v1/create-qr-code/?size=240x240&data=${encodeURIComponent(upiUri)}`;
    imgEl.style.display = "block";
  }

  window.showAppModal("dynamic-upi-qr-modal");
};

window.closeDynamicUpiModal = function() {
  window.hideAppModal("dynamic-upi-qr-modal");
};

window.copyDynamicUpiId = function() {
  const upiId = (globalSettings.upiId || globalSettings.bank?.upi || globalSettings.bank?.upiId || "7386262139@upi").trim();
  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(upiId).then(() => {
      if (typeof showFloatingToast === 'function') {
        showFloatingToast("📋 UPI ID copied: " + upiId, "info", 2500);
      }
    }).catch(() => {});
  }
};

window.toggleDynamicUpiPartialPayment = function() {
  const wrap = document.getElementById("dynamic-upi-partial-wrap");
  if (!wrap) return;
  const isHidden = wrap.style.display === "none" || !wrap.style.display;
  wrap.style.display = isHidden ? "block" : "none";
  if (isHidden) {
    const input = document.getElementById("dynamic-upi-partial-amt");
    if (input) setTimeout(() => input.focus(), 100);
  }
};

window.confirmDynamicUpiPaymentCompleted = function() {
  if (typeof window.isViewOnlyUser === 'function' && window.isViewOnlyUser()) {
    if (typeof showFloatingToast === 'function') {
      showFloatingToast("⛔ Access Denied: Payment completion is strictly prohibited in View-Only mode.", "error", 4500);
    }
    return;
  }
  if (typeof window.isCustomerAccount === 'function' && window.isCustomerAccount()) {
    if (typeof showFloatingToast === 'function') {
      showFloatingToast("⛔ Access Denied: Customer accounts cannot mark invoices as paid.", "error", 4500);
    }
    return;
  }

  if (!currentActiveUpiInvoice) {
    if (typeof showFloatingToast === 'function') showFloatingToast("⚠️ No active invoice selected.", "warning");
    return;
  }

  const inv = currentActiveUpiInvoice;
  const d = inv.details || inv;
  const total = Number(d.balanceDue !== undefined && d.balanceDue > 0 ? d.balanceDue : (d.grandTotal || d.total || inv.grandTotal || 0));
  const utr = (document.getElementById("dynamic-upi-utr-input")?.value || "").trim();
  const invNo = inv.invoiceNo || d.invoiceNo || '0001';

  if (inv.isDraftBilling || !inv.id || !invoicesDb.some(x => x.id === inv.id)) {
    // --- 1. ACTIVE DRAFT BILLING FORM UPDATE ---
    if (elements.billPaymentMode) elements.billPaymentMode.value = "UPI / QR";
    if (typeof window.setPaymentStatusSegment === 'function') {
      window.setPaymentStatusSegment("Paid");
    }
    if (elements.billPaidAmount) elements.billPaidAmount.value = total.toFixed(2);
    if (elements.billBalancePaid) elements.billBalancePaid.value = "0.00";
    if (elements.billPaymentDate) elements.billPaymentDate.value = new Date().toISOString().split('T')[0];

    if (!currentInvoice) currentInvoice = {};
    currentInvoice.paymentMode = "UPI / QR";
    currentInvoice.paymentStatus = "Paid";
    currentInvoice.paidAmount = total;
    currentInvoice.balanceDue = 0;
    if (utr) currentInvoice.paymentReference = utr;

    if (typeof calculateSummaryAndTable === 'function') {
      calculateSummaryAndTable();
    }

    if (typeof playAudioFeedback === 'function') playAudioFeedback("success");
    else if (typeof playScannerBeep === 'function') playScannerBeep();

    closeDynamicUpiModal();

    if (typeof showFloatingToast === 'function') {
      showFloatingToast(`✅ Payment of ₹ ${formatCurrency(total)} received via UPI QR! Bill #${invNo} marked as PAID.`, "success", 4500);
    }

    // Highlight Save & Print Button
    const saveBtn = document.getElementById("btn-save-print-a4") || document.getElementById("btn-save-generate-invoice");
    if (saveBtn) {
      saveBtn.classList.add("pulse-highlight");
      setTimeout(() => saveBtn.classList.remove("pulse-highlight"), 3500);
      try { saveBtn.focus(); } catch(_) {}
    }
  } else {
    // --- 2. EXISTING SAVED INVOICE SETTLEMENT ---
    const dbInv = invoicesDb.find(x => x.id === inv.id || x.invoiceNo === inv.invoiceNo) || inv;
    const totalAmt = Number(dbInv.total || (dbInv.details && dbInv.details.total) || total);

    dbInv.paidAmount = totalAmt;
    dbInv.balanceDue = 0;
    dbInv.paymentStatus = "Paid";
    dbInv.paymentMode = "UPI / QR";
    if (utr) dbInv.paymentReference = utr;

    if (dbInv.details) {
      dbInv.details.paidAmount = totalAmt;
      dbInv.details.balanceDue = 0;
      dbInv.details.paymentStatus = "Paid";
      dbInv.details.paymentMode = "UPI / QR";
      if (utr) dbInv.details.paymentReference = utr;
    }

    if (!dbInv.paymentHistory) dbInv.paymentHistory = [];
    dbInv.paymentHistory.push({
      date: new Date().toISOString(),
      amount: total,
      mode: "UPI / QR",
      reference: utr,
      status: "Paid",
      source: "Dynamic UPI QR Modal"
    });
    if (typeof window.ensureInvoicePaymentHistory === 'function') {
      window.ensureInvoicePaymentHistory(dbInv);
    }

    try {
      localStorage.setItem("invoices", JSON.stringify(invoicesDb));
      window.invoicesDb = invoicesDb;
    } catch (e) {
      console.warn("Error persisting invoices:", e);
    }
    if (window.AaryanDB && typeof window.AaryanDB.saveInvoice === 'function') {
      try { window.AaryanDB.saveInvoice(dbInv); } catch (e) {}
    }
    if (typeof syncDatabaseToServer === 'function') {
      try { syncDatabaseToServer("invoices", dbInv); } catch (e) {}
    }
    if (typeof renderInvoicesTable === "function") renderInvoicesTable();
    if (typeof loadInvoicesHistoryTable === "function") loadInvoicesHistoryTable();
    if (typeof updateDashboardOverview === "function") updateDashboardOverview();
    if (typeof syncPreviewIfOpen === 'function') syncPreviewIfOpen(dbInv);
    if (typeof window.broadcastDatabaseMutation === 'function') window.broadcastDatabaseMutation();
    if (typeof window.publishRetainedDatabaseState === 'function') window.publishRetainedDatabaseState();

    if (typeof playAudioFeedback === 'function') playAudioFeedback("success");
    closeDynamicUpiModal();

    if (typeof showFloatingToast === 'function') {
      showFloatingToast(`✅ Invoice #${dbInv.invoiceNo} marked PAID! Balance settled to ₹0.00.`, "success", 4000);
    }
  }
};

window.confirmDynamicUpiPartialPayment = function() {
  if (typeof window.isViewOnlyUser === 'function' && window.isViewOnlyUser()) {
    if (typeof showFloatingToast === 'function') {
      showFloatingToast("⛔ Access Denied: Recording partial payments is disabled in View-Only mode.", "error", 4500);
    }
    return;
  }
  if (typeof window.isCustomerAccount === 'function' && window.isCustomerAccount()) {
    if (typeof showFloatingToast === 'function') {
      showFloatingToast("⛔ Access Denied: Customer accounts cannot record payments.", "error", 4500);
    }
    return;
  }

  if (!currentActiveUpiInvoice) return;
  const input = document.getElementById("dynamic-upi-partial-amt");
  const partialAmt = parseFloat(input?.value) || 0;
  if (partialAmt <= 0) {
    if (typeof showFloatingToast === 'function') showFloatingToast("⚠️ Please enter a valid payment amount.", "warning");
    return;
  }

  const utr = (document.getElementById("dynamic-upi-utr-input")?.value || "").trim();
  const inv = currentActiveUpiInvoice;
  const d = inv.details || inv;
  const total = Number(d.balanceDue !== undefined && d.balanceDue > 0 ? d.balanceDue : (d.grandTotal || d.total || inv.grandTotal || 0));

  if (inv.isDraftBilling || !inv.id || !invoicesDb.some(x => x.id === inv.id)) {
    if (elements.billPaymentMode) elements.billPaymentMode.value = "UPI / QR";
    if (typeof window.setPaymentStatusSegment === 'function') {
      window.setPaymentStatusSegment(partialAmt >= total ? "Paid" : "Partial");
    }
    if (elements.billPaidAmount) elements.billPaidAmount.value = partialAmt.toFixed(2);
    if (elements.billBalancePaid) elements.billBalancePaid.value = "0.00";
    if (elements.billPaymentDate) elements.billPaymentDate.value = new Date().toISOString().split('T')[0];
    if (currentInvoice && utr) currentInvoice.paymentReference = utr;

    if (typeof calculateSummaryAndTable === 'function') {
      calculateSummaryAndTable();
    }
    closeDynamicUpiModal();
    if (typeof showFloatingToast === 'function') {
      showFloatingToast(`✅ Recorded partial UPI payment of ₹ ${formatCurrency(partialAmt)}.`, "success", 4000);
    }
  } else {
    // Existing saved invoice
    const dbInv = invoicesDb.find(x => x.id === inv.id || x.invoiceNo === inv.invoiceNo) || inv;
    const curPaid = Number(dbInv.paidAmount || 0);
    const curBal = Number(dbInv.balanceDue !== undefined ? dbInv.balanceDue : (dbInv.total - curPaid));
    const settledAmt = Math.min(partialAmt, curBal);
    const newPaid = curPaid + settledAmt;
    const newBal = Math.max(0, curBal - settledAmt);
    const finalStatus = newBal <= 0.01 ? "Paid" : "Partial";

    dbInv.paidAmount = newPaid;
    dbInv.balanceDue = newBal;
    dbInv.paymentStatus = finalStatus;
    dbInv.paymentMode = "UPI / QR";
    if (utr) dbInv.paymentReference = utr;

    if (dbInv.details) {
      dbInv.details.paidAmount = newPaid;
      dbInv.details.balanceDue = newBal;
      dbInv.details.paymentStatus = finalStatus;
      dbInv.details.paymentMode = "UPI / QR";
      if (utr) dbInv.details.paymentReference = utr;
    }

    if (!dbInv.paymentHistory) dbInv.paymentHistory = [];
    dbInv.paymentHistory.push({
      date: new Date().toISOString(),
      amount: settledAmt,
      mode: "UPI / QR",
      reference: utr,
      status: finalStatus,
      source: "Dynamic UPI QR Modal Partial Payment"
    });
    if (typeof window.ensureInvoicePaymentHistory === 'function') {
      window.ensureInvoicePaymentHistory(dbInv);
    }

    try {
      localStorage.setItem("invoices", JSON.stringify(invoicesDb));
      window.invoicesDb = invoicesDb;
    } catch (e) {}
    if (window.AaryanDB && typeof window.AaryanDB.saveInvoice === 'function') {
      try { window.AaryanDB.saveInvoice(dbInv); } catch (e) {}
    }
    if (typeof syncDatabaseToServer === 'function') {
      try { syncDatabaseToServer("invoices", dbInv); } catch (e) {}
    }
    if (typeof renderInvoicesTable === "function") renderInvoicesTable();
    if (typeof loadInvoicesHistoryTable === "function") loadInvoicesHistoryTable();
    if (typeof updateDashboardOverview === "function") updateDashboardOverview();
    if (typeof syncPreviewIfOpen === 'function') syncPreviewIfOpen(dbInv);
    if (typeof window.broadcastDatabaseMutation === 'function') window.broadcastDatabaseMutation();

    closeDynamicUpiModal();
    if (typeof showFloatingToast === 'function') {
      showFloatingToast(`✅ Recorded ₹ ${formatCurrency(settledAmt)} payment! New balance: ₹ ${formatCurrency(newBal)} (${finalStatus}).`, "success", 4000);
    }

    // Auto-dispatch WhatsApp confirmation for the payment
    if (globalSettings && globalSettings.whatsappAutoSend !== false) {
      const d = dbInv.details || dbInv;
      const buyer = d.buyer || {};
      const phone = buyer.phone || dbInv.phone || '';
      
      let isBotReady = window.whatsappBotStatus && (window.whatsappBotStatus.isReady || window.whatsappBotStatus.status === 'CONNECTED');
      if (phone && phone.toString().replace(/\D/g, '').length >= 10 && (isBotReady || typeof dispatchWhatsAppBotMessage === 'function')) {
        const invNo = dbInv.invoiceNo || d.invoiceNo || '';
        const msg = `✅ *PAYMENT RECEIVED*\n\n🏛️ *AARYAN AQUA NEEDS*\n\n📄 *Invoice #:* ${invNo}\n💰 *Amount Paid:* ₹ ${formatCurrency(settledAmt)}\n🔴 *Remaining Due:* ₹ ${formatCurrency(newBal)}\n\nThank you for your payment! 🙏`;
        try {
          dispatchWhatsAppBotMessage({ phone, text: msg }).then(ok => {
            if (ok && typeof showFloatingToast === 'function') {
              showFloatingToast("📲 Payment confirmation sent via WhatsApp Bot!", "success");
            }
          });
        } catch (err) {
          console.warn("Failed to dispatch WA payment confirmation:", err);
        }
      }
    }
  }
};

window.shareDynamicUpiWhatsApp = function() {
  if (!currentActiveUpiInvoice) return;
  const d = currentActiveUpiInvoice.details || currentActiveUpiInvoice;
  const buyer = d.buyer || currentActiveUpiInvoice.buyer || {};
  const phone = buyer.phone || d.phone || currentActiveUpiInvoice.phone || '';
  const total = Number(d.balanceDue !== undefined && d.balanceDue > 0 ? d.balanceDue : (d.grandTotal || d.total || currentActiveUpiInvoice.grandTotal || 0));
  const invNo = currentActiveUpiInvoice.invoiceNo || d.invoiceNo || '0001';
  const upiId = (globalSettings.upiId || globalSettings.bank?.upi || globalSettings.bank?.upiId || "7386262139@upi").trim();
  const merchantName = (globalSettings?.company?.name || 'Aaryan Aqua Needs').replace(/[^a-zA-Z0-9 ]/g, '').trim();
  const cleanInvNo = String(invNo).replace(/[^a-zA-Z0-9]/g, '');
  const qrSuffix = (currentActiveUpiInvoice.qrToken || d.qrToken || currentActiveUpiInvoice.id || "").toString().replace(/[^a-zA-Z0-9]/g, '').slice(-4).toUpperCase() || Math.random().toString(36).substring(2, 6).toUpperCase();
  const upiTr = `${cleanInvNo}${qrSuffix}`.slice(-20);
  
  const upiUri = `upi://pay?pa=${upiId}&pn=${encodeURIComponent(merchantName)}&am=${total.toFixed(2)}&cu=INR&tn=Invoice${cleanInvNo}-${qrSuffix}&tr=${upiTr}`;
  const message = `*Aaryan Aqua Needs - Instant Payment Request*\n\n📄 *Invoice #:* ${invNo}\n💰 *Amount Due:* ₹ ${formatCurrency(total)}\n\n👉 *Pay directly via UPI (PhonePe / GPay / Paytm / BHIM):*\n${upiUri}\n\nThank you for your business! 🐟`;

  if (typeof sendWhatsAppBotTextMessage === 'function' && phone) {
    sendWhatsAppBotTextMessage(phone, message);
    showFloatingToast(`📲 UPI Payment link dispatched to ${phone} via WhatsApp!`, 3000);
    closeDynamicUpiModal();
  } else {
    window.open(`https://api.whatsapp.com/send?text=${encodeURIComponent(message)}`, '_blank');
  }
};

// ============================================================================
// NATIVE GENERAL APP ARCHITECTURE: PWA INSTALLATION, MODAL BACK-STACK, HAPTICS
// ============================================================================

// --- 1. PWA NATIVE INSTALLATION PROMPT MANAGER ---
window.deferredPwaPrompt = null;

window.addEventListener('beforeinstallprompt', (e) => {
  // Prevent default mini-infobar from appearing on mobile
  e.preventDefault();
  // Never show PWA installation prompts if already in Electron desktop app or installed standalone PWA
  const isDesktopOrStandalone = (typeof isElectronApp !== 'undefined' && isElectronApp) || 
    (window.matchMedia && window.matchMedia('(display-mode: standalone)').matches) || 
    window.navigator.standalone;
  if (isDesktopOrStandalone) return;

  window.deferredPwaPrompt = e;
  
  // Reveal native app install buttons on web browsers only
  const headerInstallBtn = document.getElementById('btn-pwa-install-header');
  if (headerInstallBtn) {
    headerInstallBtn.classList.remove('hidden');
    headerInstallBtn.style.display = 'inline-flex';
  }

  const sidebarInstallBtn = document.getElementById('btn-pwa-install-sidebar');
  if (sidebarInstallBtn) {
    sidebarInstallBtn.classList.remove('hidden');
    sidebarInstallBtn.style.display = 'flex';
  }

  // Reveal bottom mobile banner ONLY on mobile devices (<= 768px) and if not dismissed this session
  if (!sessionStorage.getItem('pwa_banner_dismissed') && window.innerWidth <= 768) {
    const mobileBanner = document.getElementById('pwa-mobile-install-banner');
    if (mobileBanner) {
      mobileBanner.classList.remove('hidden');
      mobileBanner.style.display = 'flex';
    }
  }
  console.log('[PWA] Native app installation prompt ready.');
});

window.triggerPwaInstall = async function() {
  if (typeof window.triggerHapticFeedback === 'function') {
    window.triggerHapticFeedback(15);
  }

  if (window.deferredPwaPrompt) {
    window.deferredPwaPrompt.prompt();
    const { outcome } = await window.deferredPwaPrompt.userChoice;
    console.log('[PWA] User response to install prompt:', outcome);
    if (outcome === 'accepted') {
      showFloatingToast("🚀 Installing Aaryan Aqua App on your device...", 2500);
      window.dismissPwaBanner();
    }
    window.deferredPwaPrompt = null;
  } else {
    const isIos = /iphone|ipad|ipod/.test(navigator.userAgent.toLowerCase());
    const isStandalone = window.matchMedia('(display-mode: standalone)').matches || window.navigator.standalone;
    
    if (isStandalone) {
      showFloatingToast("✅ Aaryan Aqua is already installed and running as a standalone app!", 3000);
    } else if (isIos) {
      const iosModal = document.getElementById('ios-pwa-modal');
      if (iosModal) iosModal.classList.remove('hidden');
    } else {
      showFloatingToast("📲 To install: tap your browser menu (⋮ or Share) > select 'Install app' or 'Add to Home Screen'!", 4500);
    }
  }
};

window.dismissPwaBanner = function() {
  sessionStorage.setItem('pwa_banner_dismissed', 'true');
  const mobileBanner = document.getElementById('pwa-mobile-install-banner');
  if (mobileBanner) {
    mobileBanner.classList.add('hidden');
    mobileBanner.style.display = 'none';
  }
};

window.closeIosInstallModal = function(e) {
  if (e && e.target && e.target !== document.getElementById('ios-pwa-modal') && !e.target.classList.contains('btn-close-modal') && !e.target.classList.contains('btn-primary')) {
    return;
  }
  const iosModal = document.getElementById('ios-pwa-modal');
  if (iosModal) iosModal.classList.add('hidden');
};

window.addEventListener('appinstalled', (evt) => {
  console.log('[PWA] Aaryan Aqua successfully installed to home screen / OS!');
  showFloatingToast("🎉 Aaryan Aqua App installed! You can now launch it directly from your Home Screen or Desktop.", 5000);
  const headerInstallBtn = document.getElementById('btn-pwa-install-header');
  if (headerInstallBtn) {
    headerInstallBtn.classList.add('hidden');
    headerInstallBtn.style.display = 'none';
  }
  const sidebarInstallBtn = document.getElementById('btn-pwa-install-sidebar');
  if (sidebarInstallBtn) {
    sidebarInstallBtn.classList.add('hidden');
    sidebarInstallBtn.style.display = 'none';
  }
  window.dismissPwaBanner();
});

// --- 2. ANDROID HARDWARE / GESTURE BACK BUTTON (MODAL BACK-STACK) ---
window._modalCloseStack = [];

window.pushModalBackStack = function(closeCallback) {
  if (typeof closeCallback !== 'function') return;
  window._modalCloseStack.push(closeCallback);
  try {
    history.pushState({ modalOpen: true, stackDepth: window._modalCloseStack.length }, '');
  } catch (e) {}
};

window.popModalBackStack = function() {
  if (window._modalCloseStack.length > 0) {
    const cb = window._modalCloseStack.pop();
    try { cb(); } catch (e) {}
  }
};

window.addEventListener('popstate', (e) => {
  // If we have an explicit callback in stack, trigger it
  if (window._modalCloseStack.length > 0) {
    const cb = window._modalCloseStack.pop();
    try { cb(); } catch (e) {}
    return;
  }
  // Check if mobile sidebar is open
  const wrapper = document.querySelector('.dashboard-wrapper');
  if (wrapper && wrapper.classList.contains('sidebar-open')) {
    if (typeof window.closeMobileSidebar === 'function') {
      window.closeMobileSidebar();
      return;
    }
  }
  // Check if any modal-overlay is visible
  const visibleModals = document.querySelectorAll('.modal-overlay:not(.hidden)');
  if (visibleModals && visibleModals.length > 0) {
    const topModal = visibleModals[visibleModals.length - 1];
    topModal.classList.add('hidden');
    const closeBtn = topModal.querySelector('.btn-close-modal, .btn-close, [onclick*="close"]');
    if (closeBtn && typeof closeBtn.click === 'function') {
      closeBtn.click();
    }
  }
});

// --- 3. NATIVE HAPTIC VIBRATION FEEDBACK ---
window.triggerHapticFeedback = function(durationMs = 12) {
  if (navigator && typeof navigator.vibrate === 'function') {
    try { navigator.vibrate(durationMs); } catch (e) {}
  }
};

// --- 4. APP NETWORK ONLINE / OFFLINE DETECTOR ---
function updateAppNetworkStatus(isInitial = false) {
  const banner = document.getElementById('app-network-banner');
  const text = document.getElementById('network-banner-text');
  const icon = document.getElementById('network-banner-icon');
  if (!banner || !text) return;

  if (navigator.onLine) {
    if (!isInitial) {
      banner.classList.add('online');
      banner.classList.remove('hidden');
      banner.style.display = 'flex';
      text.textContent = '🟢 Back Online — Syncing records with Cloud Mesh...';
      if (icon) icon.className = 'fa-solid fa-cloud-arrow-up';
      setTimeout(() => {
        banner.classList.add('hidden');
        banner.style.display = 'none';
      }, 2800);
    } else {
      banner.classList.add('hidden');
      banner.style.display = 'none';
    }
  } else {
    banner.classList.remove('online');
    banner.classList.remove('hidden');
    banner.style.display = 'flex';
    text.textContent = '⚠️ Working Offline — Invoices saved locally & auto-sync when online.';
    if (icon) icon.className = 'fa-solid fa-wifi';
  }
}

window.addEventListener('online', () => updateAppNetworkStatus(false));
window.addEventListener('offline', () => updateAppNetworkStatus(false));

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', () => updateAppNetworkStatus(true));
} else {
  updateAppNetworkStatus(true);
}



// =========================================================
// --- SAFE SPA ENTRY POINT (Runs after all definitions) ---
// =========================================================
if (typeof document !== 'undefined') {
  if (document.readyState === 'loading') {
    document.addEventListener("DOMContentLoaded", initializeApp);
  } else {
    // If DOM is already interactive/complete, initialize immediately
    setTimeout(initializeApp, 0);
  }
}


/* Auto-Unblur Stat Cards on Click */
document.addEventListener("click", function(e) {
  if (e.target && e.target.closest("#stat-total-amount, #stat-total-collected, #stat-total-balance, #stat-total-profit, .maskable-financial, .stat-card")) {
    if (document.body.classList.contains("counter-privacy-active") || document.body.classList.contains("strict-privacy-enabled")) {
      document.body.classList.remove("counter-privacy-active", "strict-privacy-enabled");
      try {
        localStorage.setItem("counter_privacy_mode", "false");
        if (typeof globalSettings !== 'undefined' && globalSettings && globalSettings.security) {
          globalSettings.security.counterPrivacyMode = false;
        }
        const cb = document.getElementById("set-counter-privacy-mode");
        if (cb) cb.checked = false;
      } catch(_) {}
    }
  }
});

// ============================================================================
// UNRECOGNIZED BARCODE QUICK-LINK & ADD ACTIONS
// ============================================================================
window.showUnrecognizedBarcodePrompt = function(barcode) {
  const clean = String(barcode || "").trim();
  if (!clean) return;

  const card = document.getElementById("barcode-unrecognized-card");
  const valEl = document.getElementById("unrecognized-barcode-val");
  const selectEl = document.getElementById("quick-link-product-select");
  if (!card) return;

  if (valEl) valEl.textContent = clean;

  if (selectEl) {
    selectEl.innerHTML = '<option value="">-- Choose existing product to link --</option>';
    const prods = Array.isArray(window.productsDb) ? window.productsDb : [];
    prods.forEach(p => {
      const desc = p.description || p.name || ('Product #' + p.id);
      const bc = p.barcode ? (' [Barcode: ' + p.barcode + ']') : ' [No barcode]';
      const opt = document.createElement("option");
      opt.value = p.id;
      opt.textContent = desc + ' (₹' + parseFloat(p.rate || 0).toFixed(2) + ')' + bc;
      selectEl.appendChild(opt);
    });
  }

  card.style.display = "block";
};

window.linkBarcodeToSelectedProduct = function() {
  const card = document.getElementById("barcode-unrecognized-card");
  const valEl = document.getElementById("unrecognized-barcode-val");
  const selectEl = document.getElementById("quick-link-product-select");
  const barcode = valEl ? valEl.textContent.trim() : "";
  const prodId = selectEl ? selectEl.value : "";

  if (!barcode) {
    if (typeof showFloatingToast === 'function') showFloatingToast("No barcode to link.", "warning");
    return;
  }
  if (!prodId) {
    if (typeof showFloatingToast === 'function') showFloatingToast("Please select a product from the list.", "warning");
    return;
  }

  const prods = Array.isArray(window.productsDb) ? window.productsDb : [];
  const prod = prods.find(p => String(p.id) === String(prodId));
  if (!prod) {
    if (typeof showFloatingToast === 'function') showFloatingToast("Selected product not found.", "error");
    return;
  }

  prod.barcode = barcode;
  if (prod.stock === undefined || prod.stock === null || prod.stock <= 0) {
    prod.stock = 100;
  }

  try {
    localStorage.setItem("products", JSON.stringify(prods));
  } catch (e) {}
  if (window.TurboDataStore && typeof window.TurboDataStore.rebuildIndexes === 'function') {
    window.TurboDataStore.rebuildIndexes();
  }
  if (window.SupabaseDB && window.SupabaseDB.isConfigured() && typeof window.SupabaseDB.upsertProduct === 'function') {
    window.SupabaseDB.upsertProduct(prod).catch(() => {});
  }

  if (card) card.style.display = "none";
  if (typeof showFloatingToast === 'function') {
    showFloatingToast('🔗 Linked barcode ' + barcode + ' to "' + prod.description + '"! Adding to bill...', "success", 3500);
  }

  const addRes = window.addScannedProductToInvoice(prod);
  if (window.isContinuousScanMode) {
    window.showLiveScanFeedback(prod, addRes);
  } else {
    window.closeBarcodeScannerModal();
  }
};

window.quickCreateProductWithBarcode = function() {
  const card = document.getElementById("barcode-unrecognized-card");
  const valEl = document.getElementById("unrecognized-barcode-val");
  const nameInput = document.getElementById("quick-create-prod-name");
  const rateInput = document.getElementById("quick-create-prod-rate");
  const barcode = valEl ? valEl.textContent.trim() : "";
  const name = nameInput ? nameInput.value.trim() : "";
  const rate = rateInput ? parseFloat(rateInput.value) || 0 : 0;

  if (!barcode) {
    if (typeof showFloatingToast === 'function') showFloatingToast("No barcode to create product for.", "warning");
    return;
  }
  if (!name) {
    if (typeof showFloatingToast === 'function') showFloatingToast("Please enter a product name.", "warning");
    if (nameInput) nameInput.focus();
    return;
  }
  if (rate <= 0) {
    if (typeof showFloatingToast === 'function') showFloatingToast("Please enter a valid rate (₹).", "warning");
    if (rateInput) rateInput.focus();
    return;
  }

  const prods = Array.isArray(window.productsDb) ? window.productsDb : [];
  const newProd = {
    id: "prod_" + Date.now(),
    description: name,
    rate: rate,
    salesRate: rate,
    barcode: barcode,
    stock: 100,
    status: "In Stock",
    category: "General",
    gstRate: 0,
    hsn: "3808"
  };

  prods.push(newProd);
  window.productsDb = prods;

  try {
    localStorage.setItem("products", JSON.stringify(prods));
  } catch (e) {}
  if (window.TurboDataStore && typeof window.TurboDataStore.rebuildIndexes === 'function') {
    window.TurboDataStore.rebuildIndexes();
  }
  if (window.SupabaseDB && window.SupabaseDB.isConfigured() && typeof window.SupabaseDB.upsertProduct === 'function') {
    window.SupabaseDB.upsertProduct(newProd).catch(() => {});
  }
  if (typeof renderProductsTable === 'function') renderProductsTable();

  if (card) card.style.display = "none";
  if (nameInput) nameInput.value = "";
  if (rateInput) rateInput.value = "";

  if (typeof showFloatingToast === 'function') {
    showFloatingToast('✨ Created product "' + name + '" with barcode ' + barcode + '! Adding to bill...', "success", 3500);
  }

  const addRes = window.addScannedProductToInvoice(newProd);
  if (window.isContinuousScanMode) {
    window.showLiveScanFeedback(newProd, addRes);
  } else {
    window.closeBarcodeScannerModal();
  }
};

// Automated Background Backup Watcher (runs 4 seconds after boot)
setTimeout(() => {
  try {
    const sched = (typeof globalSettings !== 'undefined' && globalSettings.backupSchedule) ? globalSettings.backupSchedule : null;
    if (!sched || sched.enabled === false || sched.frequency === 'manual') return;

    const now = Date.now();
    const lastWeekly = parseInt(localStorage.getItem("last_weekly_auto_backup") || "0", 10);
    const lastMonthly = parseInt(localStorage.getItem("last_monthly_auto_backup") || "0", 10);
    const ONE_WEEK_MS = 7 * 24 * 60 * 60 * 1000;
    const ONE_MONTH_MS = 30 * 24 * 60 * 60 * 1000;

    let triggerType = null;
    if ((sched.frequency === 'monthly' || sched.frequency === 'both') && (now - lastMonthly > ONE_MONTH_MS)) {
      triggerType = "MONTHLY_AUTOMATED";
      localStorage.setItem("last_monthly_auto_backup", String(now));
    } else if ((sched.frequency === 'weekly' || sched.frequency === 'both') && (now - lastWeekly > ONE_WEEK_MS)) {
      triggerType = "WEEKLY_AUTOMATED";
      localStorage.setItem("last_weekly_auto_backup", String(now));
    }

    if (triggerType && typeof window.sendDataBackupToEmail === 'function') {
      console.log(`[Auto-Backup] Dispatching background ${triggerType} store backup...`);
      window.sendDataBackupToEmail({ isSilent: true, scheduleType: triggerType });
    }
  } catch(e) {
    console.warn("Auto-backup watcher note:", e);
  }
}, 4000);
